import type { BankQuestion } from "@/lib/bank";

/** Taxation & Business Law (Management & Commerce): 715 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"mgmt-tax-law-1","question":"A registered supplier in Maharashtra sells goods to a buyer in Maharashtra, and the goods are delivered within Maharashtra. Which GST applies?","options":["CGST + SGST","IGST (integrated tax)","Only CGST at full rate","Only SGST at full rate"],"answer":0,"explanation":"Supplier and place of supply are in the same state, so it is an intra-state supply, taxed half as CGST and half as SGST.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-2","question":"A supplier in Delhi sells goods to a buyer in Jaipur, and the goods move from Delhi to Jaipur. Which GST applies?","options":["CGST + SGST of Delhi","CGST + SGST of Rajasthan","IGST","No GST, as it is a stock transfer"],"answer":2,"explanation":"The supplier is in Delhi and the place of supply (where movement ends) is Rajasthan, so it is an inter-state supply attracting IGST.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-3","question":"The list price of goods is ₹1,00,000. A 5% trade discount on the list price is shown on the invoice; packing charged separately is ₹2,000 and freight charged by the supplier for delivering the goods is ₹3,000. What is the taxable value?","options":["₹1,00,000","₹1,05,000","₹95,000","₹97,000"],"answer":0,"explanation":"The discount shown on the invoice at the time of supply is excluded: 95,000. Packing and freight charged by the supplier are incidental and included: 95,000 + 2,000 + 3,000 = ₹1,00,000.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-4","question":"A supplier sells goods for ₹50,000 (excluding GST). It also receives a subsidy of ₹5,000 from a private trust, directly linked to this sale's price, and charges ₹1,000 interest for late payment. What is the taxable value?","options":["₹50,000","₹55,000","₹56,000","₹51,000"],"answer":2,"explanation":"Value includes subsidies directly linked to price unless given by the Central or State Government, and also interest or late fees for delayed payment: 50,000 + 5,000 + 1,000 = ₹56,000.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-5","question":"Three months after a sale, a supplier decides to give the customer a 5% discount that was not provided for in any agreement made before the supply. Under GST:","options":["The taxable value can be reduced by a GST credit note, since tax was overcharged","The value is not reduced; only a financial credit note without GST can be issued","The government refunds the GST attributable to the discount","The value is reduced and the customer need not reverse any ITC"],"answer":1,"explanation":"A post-supply discount reduces value only if it was agreed before or at the time of supply, is linked to specific invoices and the recipient reverses the matching ITC. An unplanned later discount does not qualify.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-6","question":"For a month, output tax is IGST ₹50,000, CGST ₹30,000 and SGST ₹30,000. Input tax credit available is IGST ₹70,000, CGST ₹10,000 and SGST ₹15,000. What is the minimum cash payment needed?","options":["₹35,000","₹15,000","₹20,000","₹25,000"],"answer":1,"explanation":"IGST credit is used first: ₹50,000 against IGST, and the remaining ₹20,000 against CGST/SGST in any proportion. If at least ₹5,000 goes to SGST, no credit is stranded: total output 1,10,000 − total credit 95,000 = ₹15,000 cash. Using IGST credit only against IGST leaves ₹35,000 to pay.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-7","question":"Which of these set-offs of input tax credit is NOT allowed under GST?","options":["IGST credit against CGST liability","CGST credit against IGST liability","SGST credit against IGST liability","CGST credit against SGST liability"],"answer":3,"explanation":"CGST and SGST belong to different governments, so neither credit can pay the other. Both can pay IGST, and IGST credit can pay either.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-8","question":"A company receives legal services worth ₹2,00,000 from an advocate, on which GST is payable under reverse charge at 18% (assume). Its electronic credit ledger has ₹1,00,000. How does it discharge the liability?","options":["Pay ₹36,000 in cash, then take it as input tax credit","Set off ₹36,000 from the credit ledger, as credit is fungible","Nothing: the advocate charges and pays the tax himself","Pay ₹36,000 in cash; no ITC as the tax was paid under RCM"],"answer":0,"explanation":"Tax under reverse charge must be paid through the cash ledger, not from existing credit. Once paid, it is available as ITC if the service is used in the business.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-9","question":"A, registered in Gujarat, orders goods from S in Maharashtra and asks S to deliver them directly to C, also in Maharashtra; S bills A. What tax does S charge A?","options":["CGST + SGST of Maharashtra, as the goods physically move within Maharashtra","IGST: place of supply is A's principal place of business (Gujarat)","No GST on S's leg, as the goods never leave Maharashtra","CGST + SGST of Gujarat, as A is the billed buyer"],"answer":1,"explanation":"In a bill-to-ship-to supply, the place of supply for S's sale is the principal place of business of the person on whose direction the goods are delivered (A, Gujarat). Supplier in Maharashtra + place of supply in Gujarat = IGST.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-10","question":"A shop sells a festival hamper of sweets, dry fruits and a packaged juice for one price. Sold separately, the items would attract 5%, 12% and 18% (assume these rates). How is the hamper taxed?","options":["As a composite supply at 5%, the rate of the main item","Each item at its own rate on an apportioned price","As a mixed supply at 18% on the whole price","At the average of the three rates"],"answer":2,"explanation":"The items are not naturally bundled (each is sold on its own), so it is a mixed supply, taxed at the highest rate applicable to any item in it.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-11","question":"Which statement about a supplier of goods under the GST composition scheme is correct?","options":["It can charge GST separately on its invoices at the composition rate","It cannot take input tax credit or collect tax from its customers","It can make inter-state outward supplies of goods without restriction","It must issue tax invoices showing GST like a regular taxpayer"],"answer":1,"explanation":"A composition taxpayer pays tax on turnover out of its own pocket, issues a bill of supply, cannot collect tax from buyers, cannot take ITC and cannot make inter-state outward supplies of goods.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-12","question":"How many statements about a composition taxpayer supplying goods are correct? (1) It issues a bill of supply, not a tax invoice. (2) It can claim input tax credit on its purchases. (3) It can make inter-state outward supplies of goods on payment of IGST. (4) It pays tax on its reverse-charge inward supplies at the composition rate.","options":["One","Two","Three","Four"],"answer":0,"explanation":"Only (1) is correct. A composition taxpayer cannot claim ITC (2), cannot make inter-state outward supplies of goods (3), and pays tax on reverse-charge inward supplies at the normal rates, not the composition rate (4).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-13","question":"In which case is input tax credit allowed?","options":["A 30-seater bus bought by a factory to carry its workers","Outdoor catering for an employees' party that no law requires","Club membership for the company's directors","Goods given away as free samples"],"answer":0,"explanation":"The block on motor vehicles covers only vehicles for carrying persons with a seating capacity of up to 13 (including the driver), so a 30-seater bus qualifies. Catering not required by law, club membership and free samples are blocked under Section 17(5).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-14","question":"For which of these is input tax credit allowed?","options":["Works contract for constructing the company's office building","Works contract for installing plant and machinery","Cement used to build the factory's boundary wall","Repairs capitalised to the office building"],"answer":1,"explanation":"Works contracts and goods for constructing immovable property are blocked, except for plant and machinery. A boundary wall and an office building are civil structures, not plant and machinery.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-15","question":"Assertion (A): A company that claims income-tax depreciation on the full cost of a machine including its ₹1,80,000 GST cannot also take ₹1,80,000 as input tax credit. Reason (R): The GST law denies input tax credit on the tax component of capital goods when depreciation is claimed on that tax component.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Section 16(3) prevents a double benefit: tax cannot be both capitalised for depreciation and claimed as credit. That rule is exactly what A applies.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-16","question":"A recipient takes input tax credit but does not pay the supplier the value and tax within 180 days of the invoice. What happens?","options":["The credit is reversed with interest and can be re-availed once payment is made","The credit lapses permanently, even if payment is made later","Nothing, since the supplier has already paid the tax to the government","The supplier must issue a credit note and refund the GST it collected to the buyer"],"answer":0,"explanation":"The proviso to Section 16(2) requires payment within 180 days; otherwise the credit is reversed with interest, and it can be taken again when the payment is made.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-17","question":"Which of these is a supply under GST even though no consideration is received?","options":["Permanent transfer of business machinery, on which ITC was taken, to a relative","Free samples distributed without having claimed any ITC on them","A donation received by a charity where no benefit at all is given back to the donor","Salary paid to an employee for services rendered in employment"],"answer":0,"explanation":"Schedule I treats the permanent transfer or disposal of business assets on which ITC was availed as a supply even without consideration. Salary is outside GST (employee services, Schedule III).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-18","question":"A business has taxable intra-state supplies of ₹40 lakh, exempt supplies of ₹10 lakh and exports of ₹15 lakh. It also received inward supplies of ₹5 lakh on which it paid tax under reverse charge, and it charged GST of ₹7.2 lakh on its taxable supplies. What is its aggregate turnover?","options":["₹70 lakh","₹65 lakh","₹72.2 lakh","₹55 lakh"],"answer":1,"explanation":"Aggregate turnover includes taxable, exempt and export supplies (40 + 10 + 15 = ₹65 lakh) but excludes inward supplies under reverse charge and the taxes themselves.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-19","question":"A Karnataka supplier makes intra-state sales of ₹10,00,000 and inter-state sales of ₹5,00,000, all at 18% (assume). Its input tax credit is IGST of ₹1,50,000 only. How much does it pay in cash?","options":["₹1,80,000","₹2,70,000","₹1,20,000","₹1,50,000"],"answer":2,"explanation":"Output: CGST 90,000 + SGST 90,000 + IGST 90,000 = 2,70,000. IGST credit pays IGST 90,000 and the balance 60,000 goes to CGST/SGST. Cash = 2,70,000 − 1,50,000 = ₹1,20,000. Using IGST credit only against IGST leaves ₹1,80,000 to pay.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-20","question":"Exports are zero-rated under GST. How can an exporter handle them?","options":["Only by paying IGST on the export and then claiming a refund of that IGST","Only under a letter of undertaking, with no refund of accumulated input tax credit","Under LUT without IGST with refund of unused ITC, or pay IGST and claim its refund","Exports are exempt supplies, so the related input tax credit must be reversed"],"answer":2,"explanation":"Zero-rating keeps the exporter's ITC alive through either route. Exempt supplies, by contrast, require ITC reversal.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-21","question":"Which of these is a composite supply?","options":["Goods sold with packing, transport and insurance at one price","A hamper of chocolates and a water bottle sold for one price","Two unrelated products sold together as a festive combo offer","A gift box containing dry fruits and a wristwatch at one price"],"answer":0,"explanation":"In a composite supply the items are naturally bundled and supplied together in the ordinary course of business, with one principal supply (here the goods). The others are mixed supplies.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-22","question":"A company pays sitting fees to an independent director who is not its employee, and salary to its whole-time director who is an employee. Which is correct?","options":["Both are supplies, and each director charges GST on his invoice to the company","Neither is within GST, since all directors are treated as officers of the company","Company pays GST on the sitting fees under reverse charge; the salary is not a supply","The whole-time director's salary attracts GST under reverse charge; sitting fees do not"],"answer":2,"explanation":"Services by a director to the company are under reverse charge, so the company pays tax on the sitting fees. Services by an employee to the employer in the course of employment are outside GST (Schedule III).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-23","question":"GST is best described as:","options":["An origin-based tax on production","A destination-based tax on consumption","A direct tax on income of businesses","A tax levied on goods only, not services"],"answer":1,"explanation":"GST accrues to the state where the goods or services are consumed, with credit at every stage so that only value addition is taxed.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-24","question":"Which of these was NOT subsumed into GST?","options":["Central excise duty on most goods","Service tax","Basic customs duty","State VAT"],"answer":2,"explanation":"Basic customs duty on imports continues separately; IGST is levied on imports in addition. Excise (except on certain items such as petroleum and tobacco), service tax and VAT were subsumed.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-25","question":"A supplier in Tamil Nadu sells goods to an SEZ unit located in Tamil Nadu. How is the supply treated under GST?","options":["An intra-state supply attracting CGST + SGST of Tamil Nadu","An exempt supply, with proportionate reversal of the supplier's ITC","A non-taxable supply outside GST, as SEZs are foreign territory","An inter-state, zero-rated supply (IGST with refund, or under LUT)"],"answer":3,"explanation":"The IGST Act treats a supply to an SEZ developer or unit as inter-state even when both are in the same state, and it is zero-rated.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-26","question":"The price of an article, inclusive of GST at 18% (assume), is ₹11,800. How much GST is included in it?","options":["₹2,124","₹1,800","₹1,180","₹1,416"],"answer":1,"explanation":"Tax = 11,800 × 18/118 = ₹1,800 on a value of ₹10,000. Taking 18% of the tax-inclusive price gives ₹2,124.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-27","question":"Common inputs carry input tax credit of ₹1,00,000. In the period, taxable turnover is ₹60 lakh and exempt turnover ₹40 lakh. How much credit must be reversed?","options":["₹40,000","₹60,000","₹66,667","Nil"],"answer":0,"explanation":"Credit on common inputs is reversed in the ratio of exempt turnover to total turnover: 1,00,000 × 40/100 = ₹40,000. Dividing by taxable turnover instead gives ₹66,667.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-28","question":"A company holds GST registrations in Karnataka and Kerala under the same PAN. Which is correct?","options":["Both form one taxable person, so transfers between them are not supplies","Each registration is a distinct person; a stock transfer between them is a supply","Only services between them are supplies; goods transfers are mere stock movement","Transfers between them are exempt, since no consideration changes hands between them"],"answer":1,"explanation":"Separate registrations of the same PAN are distinct persons, and Schedule I treats supplies between distinct persons in the course of business as supplies even without consideration.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-29","question":"An architect registered in Mumbai designs a building to be built in Pune for a client registered in Delhi. What tax does the architect charge?","options":["IGST, as the place of supply is the client's location in Delhi","CGST + SGST of Delhi, since the client is registered there","No GST, as services relating to immovable property are outside GST","CGST + SGST of Maharashtra, as the property is located in Pune"],"answer":3,"explanation":"For services directly related to immovable property, including architects' services, the place of supply is the location of the property (Maharashtra). The supplier is also in Maharashtra, so it is intra-state. Using the general B2B rule (recipient's location) wrongly gives IGST.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-30","question":"Which of these is treated as neither a supply of goods nor a supply of services?","options":["Sale of a building after its completion certificate has been issued","Sale of old office furniture by a company","Renting of a commercial shop","Transfer of stock between registrations of the same company in different states"],"answer":0,"explanation":"Schedule III excludes the sale of land and of a building after its completion certificate. Renting is a supply of services; selling business assets and inter-state stock transfers are supplies.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-31","question":"Which of these is NOT one of the five heads of income under Indian income tax?","options":["Salaries","Income from house property","Capital gains","Income from investments"],"answer":3,"explanation":"The five heads are salaries, house property, profits and gains of business or profession, capital gains and income from other sources. Investment income falls under one of these (usually other sources or capital gains).","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-32","question":"Assume the basic rule: an individual is resident if in India for 182 days or more in the year, or for 60 days or more in the year and 365 days or more in the four preceding years. Mr X, a foreign citizen, was in India for 70 days this year and 400 days in the four preceding years. What is his status?","options":["Non-resident, because he is a foreign citizen","Non-resident, because he stayed less than 182 days","Resident, under the 60-day + 365-day test","Resident only for income received in India"],"answer":2,"explanation":"Residence depends on physical presence, not citizenship. 70 ≥ 60 and 400 ≥ 365, so the second condition is met and he is resident.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-33","question":"Assume the basic residence tests (182 days; or 60 days in the year plus 365 days in the four preceding years), and that for an Indian citizen who leaves India during the year for employment abroad the 60-day figure is replaced by 182 days. Ms Y, an Indian citizen, leaves for a job abroad after spending 150 days in India this year; she was in India throughout the four preceding years. What is her status?","options":["Resident, because she is an Indian citizen","Resident, because of more than 365 days in the preceding four years","Resident but only for Indian income","Non-resident, because she was in India for less than 182 days"],"answer":3,"explanation":"For a citizen leaving for employment, the relaxed 60-day test does not apply; she needs 182 days. With 150 days she fails both tests and is non-resident, whatever her past stay.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-34","question":"Mr Z is non-resident this year. How many of these are taxable in India in his hands? (1) Salary for work done in India, credited to his Dubai account (2) Profits of a business controlled from abroad, earned and received abroad (3) Interest on a savings account with an Indian bank (4) Rent from a house in London, received in London","options":["One","Two","Three","Four"],"answer":1,"explanation":"A non-resident is taxed only on income received, or accruing or arising, in India. (1) accrues in India because the work is done here; (3) arises in India. (2) and (4) are foreign income received abroad. Two are taxable.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-35","question":"A let-out house has a gross annual value of ₹3,60,000. The owner paid municipal taxes of ₹30,000 and interest of ₹1,00,000 on a loan taken to buy it. Assume a standard deduction of 30% of net annual value. What is the income from house property?","options":["₹1,52,000","₹2,31,000","₹1,22,000","₹1,31,000"],"answer":3,"explanation":"Net annual value = 3,60,000 − 30,000 = 3,30,000. Standard deduction 30% = 99,000 → 2,31,000. Less interest 1,00,000 = ₹1,31,000. Taking 30% of the gross value instead (and ignoring taxes) gives ₹1,52,000.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-36","question":"Take expected rent as the higher of municipal value and fair rent, but not more than the standard rent under rent-control law; gross annual value is the higher of expected rent and actual rent received. Municipal value ₹2,40,000; fair rent ₹2,70,000; standard rent ₹2,60,000; actual rent received ₹2,50,000. What is the gross annual value?","options":["₹2,70,000","₹2,50,000","₹2,60,000","₹2,40,000"],"answer":2,"explanation":"Higher of municipal value and fair rent = 2,70,000, capped at standard rent → expected rent 2,60,000. GAV = higher of 2,60,000 and actual rent 2,50,000 = ₹2,60,000. Forgetting the standard-rent cap gives ₹2,70,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-37","question":"For a self-occupied house, assume annual value is nil, interest deduction is capped at ₹2,00,000, and pre-construction interest is allowed in five equal instalments starting from the year construction is completed. Pre-construction interest was ₹1,50,000 and interest for the current year (the year of completion) is ₹1,80,000. What is the income from house property?","options":["Loss of ₹2,00,000","Loss of ₹2,10,000","Loss of ₹3,30,000","Loss of ₹1,80,000"],"answer":0,"explanation":"Interest allowable = 1,50,000 ÷ 5 + 1,80,000 = 2,10,000, but the cap limits it to 2,00,000. With nil annual value, the loss is ₹2,00,000. Claiming all the pre-construction interest at once gives ₹3,30,000.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-38","question":"Under a regime that allows HRA exemption, assume the exemption is the least of: HRA received; rent paid minus 10% of salary; and 50% of salary (metro city). Salary (for this purpose) is ₹6,00,000, HRA received ₹1,80,000 and rent paid ₹2,10,000 in a metro city. What is the exempt HRA?","options":["₹1,80,000","₹1,50,000","₹3,00,000","₹30,000"],"answer":1,"explanation":"The three limits are 1,80,000; 2,10,000 − 60,000 = 1,50,000; and 3,00,000. The least is ₹1,50,000, so ₹30,000 of the HRA is taxable.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-39","question":"Land is sold for ₹50,00,000, but its stamp duty value is ₹56,00,000. Assume that if the stamp duty value exceeds the consideration by more than 10%, the stamp duty value is taken as the sale consideration. Cost of acquisition (no indexation) is ₹30,00,000 and brokerage is 1% of the actual sale price. What is the capital gain?","options":["₹19,50,000","₹26,00,000","₹20,00,000","₹25,50,000"],"answer":3,"explanation":"110% of 50,00,000 = 55,00,000, and 56,00,000 exceeds it, so consideration = 56,00,000. Brokerage = 50,000. Gain = 56,00,000 − 30,00,000 − 50,000 = ₹25,50,000. Using the actual price gives ₹19,50,000.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-40","question":"Property is sold for ₹80,00,000; its stamp duty value is ₹87,00,000. Assume the stamp duty value replaces the consideration only if it exceeds the consideration by more than 10%. Cost of acquisition is ₹45,00,000, cost of improvement ₹5,00,000 and transfer expenses ₹1,00,000 (no indexation). What is the capital gain?","options":["₹36,00,000","₹29,00,000","₹34,00,000","₹30,00,000"],"answer":1,"explanation":"110% of 80,00,000 = 88,00,000; 87,00,000 does not exceed it, so the actual ₹80,00,000 is used. Gain = 80,00,000 − 45,00,000 − 5,00,000 − 1,00,000 = ₹29,00,000. Using the stamp duty value gives ₹36,00,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-41","question":"Which set-off of losses is permitted?","options":["Long-term capital loss against short-term capital gain","Business loss against salary income","Speculation business loss against non-speculation business income","Short-term capital loss against long-term capital gain"],"answer":3,"explanation":"A short-term capital loss can be set off against both short-term and long-term gains, but a long-term capital loss only against long-term gains. Business losses cannot be set off against salary, and speculation losses only against speculation income.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-42","question":"An individual has salary income of ₹8,00,000, a loss from house property of ₹2,50,000, business income of ₹1,00,000, a short-term capital gain of ₹50,000 and a long-term capital loss of ₹70,000. Assume a house-property loss can be set off against other heads only up to ₹2,00,000. What is the gross total income?","options":["₹7,50,000","₹7,00,000","₹6,50,000","₹8,00,000"],"answer":0,"explanation":"8,00,000 − 2,00,000 (capped HP loss) + 1,00,000 + 50,000 STCG = ₹7,50,000. The long-term capital loss cannot be set off against the short-term gain and is carried forward, as is ₹50,000 of the HP loss.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-43","question":"Which of these is agricultural income?","options":["Income from poultry farming carried on at a farmhouse","Dividend received from a tea-plantation company","Rent from agricultural land in India used for agriculture","Sale of trees that grew naturally, without any cultivation"],"answer":2,"explanation":"Rent or revenue from agricultural land in India used for agriculture is agricultural income. Poultry is not agriculture, a dividend is from a company, and naturally grown trees involve no agricultural operations.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-44","question":"A company credits a consultant's professional fees to his account in its books on 31 March and pays him on 15 April. For a TDS provision that applies at credit or payment, whichever is earlier, when must tax be deducted?","options":["On 15 April, when the cash is actually paid","When the consultant raises his invoice later","At the end of the following quarter","On 31 March, when the amount is credited"],"answer":3,"explanation":"Under the 'credit or payment, whichever is earlier' rule, crediting the payee's account (including a suspense or provision account) triggers deduction, so TDS is due on 31 March.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-45","question":"A business paid a resident contractor ₹10,00,000 without deducting the TDS that was due. Its profit before this adjustment is ₹25,00,000. Assume 30% of an expense is disallowed when TDS is not deducted, and that the disallowed amount is allowed in the year the TDS is later deducted and paid. What is its business income this year?","options":["₹25,00,000","₹28,00,000","₹35,00,000","₹22,00,000"],"answer":1,"explanation":"Disallowance = 30% × 10,00,000 = 3,00,000, added back: 25,00,000 + 3,00,000 = ₹28,00,000. The ₹3,00,000 becomes deductible in the year the TDS is paid. Disallowing the whole expense gives ₹35,00,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-46","question":"Tax deducted at source (TDS) is best described as:","options":["A penalty levied on the payer for filing the return late","A final tax on the payee's income, with no later credit or adjustment allowed","An additional tax over and above the payee's regular income tax","Tax collected where income is paid, credited against the payee's liability"],"answer":3,"explanation":"The payer deducts tax and deposits it; the payee claims it as a credit when computing final tax.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-47","question":"Which statement about advance tax is correct?","options":["It is paid after the year ends, as self-assessment tax along with the return","It is a tax paid now on the expected income of the next year","It is paid in instalments during the year in which the income is earned","It applies only to companies, not to individuals or firms"],"answer":2,"explanation":"Advance tax ('pay as you earn') is paid in instalments during the year itself when estimated liability crosses the threshold; shortfalls attract interest.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-48","question":"Mr A gifts ₹10 lakh to his wife without adequate consideration. She invests it in a fixed deposit and earns ₹80,000 interest, which she reinvests and earns ₹6,000 more. Under the clubbing rules, what is included in Mr A's income?","options":["₹86,000","Nil, because a gift to a spouse is exempt","₹6,000","₹80,000"],"answer":3,"explanation":"Income from assets transferred to a spouse without adequate consideration is clubbed with the transferor's income: the ₹80,000. Income earned on that clubbed income (the ₹6,000 on reinvested interest) is not clubbed; it is the wife's income.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-49","question":"A proprietor's profit and loss account shows a net profit of ₹12,00,000 after debiting income tax of ₹2,00,000, book depreciation of ₹1,50,000 and personal expenses of ₹30,000, and after crediting dividend income of ₹50,000 (taxed under another head). Tax depreciation allowable is ₹1,80,000. What is the business income?","options":["₹14,00,000","₹13,80,000","₹12,90,000","₹13,50,000"],"answer":3,"explanation":"12,00,000 + 2,00,000 (income tax) + 1,50,000 (book depreciation) − 1,80,000 (tax depreciation) − 50,000 (dividend) + 30,000 (personal expenses) = ₹13,50,000. Leaving the dividend in gives ₹14,00,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-50","question":"Which of these is taxed under 'Income from other sources'?","options":["Interest on a bank FD held as an investment by a salaried person","Rent received from a let-out residential flat owned by the taxpayer","Gain on sale of listed shares held as long-term investments","Salary arrears received from a former employer this year"],"answer":0,"explanation":"Interest income not chargeable under another head goes to other sources. Rent from a building is house property, share gains are capital gains and arrears are salary.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-51","question":"Assume that gifts of money from non-relatives are fully taxable if their aggregate in the year exceeds ₹50,000, while gifts from relatives are exempt. During the year Ms P receives ₹80,000 from a friend and ₹2,00,000 from her brother. How much is taxable?","options":["₹30,000","₹80,000","₹2,80,000","Nil"],"answer":1,"explanation":"The brother is a relative, so ₹2,00,000 is exempt. Gifts from non-relatives total ₹80,000, which exceeds ₹50,000, so the whole ₹80,000 (not just the excess of ₹30,000) is taxable.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-52","question":"Which statement correctly distinguishes tax planning, tax avoidance and tax evasion?","options":["All three are legal ways of reducing tax, differing only in degree","Evasion becomes legal if the concealed income is voluntarily disclosed in a later year","Planning follows the law's intent; avoidance exploits loopholes; evasion is illegal","Planning and evasion are the same; only avoidance is against the law"],"answer":2,"explanation":"Planning (e.g. claiming eligible deductions) is legitimate; avoidance is technically within the letter but against the spirit and can be countered by anti-avoidance rules; evasion (suppressing income, false expenses) is a crime.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-53","question":"How is the residential status of a company determined?","options":["By the residence of the majority of its shareholders during the year","By the place where most of its sales and profits are made during the previous year","By the citizenship and residence of the majority of its directors","An Indian company is always resident; a foreign one if its POEM is in India"],"answer":3,"explanation":"Incorporation in India makes a company resident every year; a foreign company becomes resident only if its place of effective management (where key management decisions are actually taken) is in India.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-54","question":"Mr Q is non-resident. His income: salary for work done in India, received in Dubai ₹5,00,000; interest from an Indian bank ₹50,000; rent from a house in London received in London ₹3,00,000; dividend from a US company received in the US ₹1,00,000. What is his income taxable in India?","options":["₹5,50,000","₹9,50,000","₹50,000","₹8,50,000"],"answer":0,"explanation":"A non-resident is taxed on income accruing or received in India: salary for Indian work (₹5,00,000) and Indian interest (₹50,000) = ₹5,50,000. The London rent and US dividend are foreign income received abroad. If he were an ordinarily resident, all ₹9,50,000 would be taxed.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-55","question":"A block of assets taxed at 15% has an opening WDV of ₹10,00,000. An asset costing ₹4,00,000 is added and put to use for less than 180 days; an asset from the block is sold for ₹2,00,000. Assume only half the rate is allowed on an asset used for less than 180 days in the year. What is the depreciation?","options":["₹1,80,000","₹1,65,000","₹1,50,000","₹1,20,000"],"answer":2,"explanation":"Deduct the sale from the opening WDV first: (10,00,000 − 2,00,000) × 15% = 1,20,000. New asset: 4,00,000 × 7.5% = 30,000. Total ₹1,50,000. Full rate on everything gives ₹1,80,000; netting the sale against the new asset instead gives ₹1,65,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-56","question":"A block of depreciable assets has a WDV of ₹3,00,000 at the start of the year, with no additions. The only asset in the block, held for many years, is sold for ₹5,00,000. How is the ₹2,00,000 excess treated?","options":["As a long-term capital gain, because the asset was held for many years","As business income of ₹5,00,000","No gain arises; the WDV simply becomes negative","As a short-term capital gain, whatever the holding period"],"answer":3,"explanation":"For assets in a block, when sale proceeds exceed the opening WDV plus additions, the excess is deemed a short-term capital gain regardless of how long the asset was held.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-57","question":"A company incurs ₹40,000 of expenses wholly to earn dividend income that is exempt in its hands. Can it deduct these expenses from its taxable income?","options":["Yes, all business expenses are deductible in full","No, expenses on exempt income are disallowed","Yes, but only half of the expenses are allowed","Only if the dividend received exceeds the expenses"],"answer":1,"explanation":"Expenditure incurred in relation to income that does not form part of total income is not allowed as a deduction.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-58","question":"Assertion (A): A small business opting for presumptive taxation may declare income at a prescribed percentage of turnover without maintaining detailed books. Reason (R): Presumptive schemes aim to reduce compliance burden by deeming income on a simple base.","options":["Both A and R are true, but R is not the correct explanation of A","A is true but R is false","Both A and R are true, and R is the correct explanation of A","A is false but R is true"],"answer":2,"explanation":"Presumptive schemes deem income at a percentage of turnover or receipts precisely to spare small taxpayers detailed accounting and audit, so R is the very reason for A, not just a true side fact.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-59","question":"The Permanent Account Number (PAN) is issued by:","options":["The Income Tax Department","The Reserve Bank of India","The GST Council","The Ministry of Corporate Affairs"],"answer":0,"explanation":"PAN is a ten-character alphanumeric identifier issued by the Income Tax Department.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-60","question":"Which of these is a direct tax?","options":["GST","Customs duty","Excise duty","Income tax"],"answer":3,"explanation":"A direct tax is borne by the person on whom it is levied. Income tax is direct; GST, customs and excise are indirect taxes passed on to consumers.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-61","question":"Goods displayed in a shop window with price tags are, in contract law:","options":["An invitation to offer","A standing offer to all","An acceptance in advance","A binding promise to sell"],"answer":0,"explanation":"A display invites customers to make offers; the customer offers to buy and the shopkeeper may accept or refuse.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-62","question":"Under the Indian Contract Act, a contract is:","options":["Any agreement between two persons","An agreement enforceable by law","Any promise made in writing","Any agreement involving money"],"answer":1,"explanation":"Section 2(h): an agreement enforceable by law is a contract. All contracts are agreements, but social or illegal agreements are not contracts.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-63","question":"A offers to sell his bike to B for ₹1,00,000. B replies that he will pay ₹90,000. A refuses. B then writes that he accepts the price of ₹1,00,000. A no longer wishes to sell. What is the legal position?","options":["There is a contract at ₹1,00,000, since B finally accepted A's original price","There is a contract at ₹90,000, the last price B proposed","No contract: the counter-offer rejected A's offer, which then lapsed","There is a contract, but it is voidable at A's option"],"answer":2,"explanation":"A counter-offer is a rejection of the original offer, which then lapses. B's later 'acceptance' is only a fresh offer, which A may decline.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-64","question":"A writes to B offering his car for ₹5 lakh and adds: 'If I hear nothing from you by Friday, I shall treat the car as sold to you.' B does not reply. What is the position on Friday?","options":["A contract arises on Friday by A's stated term","B is bound, because he did not reject the offer","A contract arises if B privately intended to accept the offer","No contract: silence cannot be imposed as acceptance"],"answer":3,"explanation":"Acceptance must be communicated by some act or words. An offeror cannot impose silence as acceptance on the offeree.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-65","question":"A posts an offer on 1 January, which B receives on 3 January. B posts his acceptance on 5 January; it reaches A on 8 January. B sends a revocation of his acceptance by courier, which reaches A on 7 January. What is the result?","options":["The revocation is valid, because it reached A before the acceptance did","The revocation is invalid, because the contract was concluded on 5 January","The revocation is invalid, because an acceptance can never be revoked","There is no contract, because A did not reply"],"answer":0,"explanation":"Acceptance is complete against the acceptor only when it comes to the proposer's knowledge (8 January), so B may revoke it until then. His revocation reached A on 7 January, so no contract arises.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-66","question":"How many of these statements are correct? (1) Communication of an offer is complete when it comes to the knowledge of the offeree. (2) Communication of an acceptance is complete against the proposer when it is put in the course of transmission. (3) Communication of an acceptance is complete against the acceptor when it comes to the knowledge of the proposer. (4) An offer can still be revoked after the acceptance has been posted, if the acceptance has not yet reached the proposer.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (3) state Section 4 correctly. (4) is wrong: an offer can be revoked only before the acceptance is put in the course of transmission against the proposer, i.e. before it is posted.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-67","question":"A company advertises a reward of ₹10,000 to anyone who finds its missing dog. X reads the advertisement, finds the dog and returns it, without first telling the company that he accepts. Can X claim the reward?","options":["No, because he did not communicate his acceptance first","Yes: performing a general offer's conditions is acceptance","Only if the company agrees to pay after the dog is returned","No, because an offer made to the public cannot be accepted"],"answer":1,"explanation":"A general offer is accepted by anyone who performs its conditions with knowledge of it; separate communication of acceptance is not needed (the Carlill principle).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-68","question":"A servant traces his master's missing nephew. Only later does he learn that the master had announced a reward for finding the boy. Can he claim the reward?","options":["Yes, because he performed exactly the act that the offer called for","Yes, but only a reasonable part, as he acted unknowingly","Yes, once he learns of the reward and then claims it","No: an offer cannot be accepted by one who does not know of it"],"answer":3,"explanation":"Acceptance requires knowledge of the offer. Doing the act in ignorance of the offer is not acceptance (Lalman Shukla v Gauri Dutt).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-69","question":"A woman gifts her property to her daughter on condition that the daughter pays an annual sum to the woman's brother. The daughter later refuses, arguing that the brother gave no consideration. Can the brother enforce the promise?","options":["Yes: consideration may move from the promisee or any other person","No, because no consideration moved from the brother himself","No, because a gift subject to a condition is void","Only the woman can sue, since the brother is a stranger to the deal"],"answer":0,"explanation":"Under Section 2(d), consideration may move from the promisee 'or any other person'. The gift of property by the woman is consideration for the daughter's promise (Chinnaya v Ramayya).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-70","question":"At B's request, A repaired B's roof last year without fixing any price. B now promises to pay A ₹20,000. Is the promise enforceable?","options":["No, because past consideration is no consideration in Indian contract law","Yes: past consideration at the promisor's request is valid in India","Only if the promise is in writing and registered under Section 25","No, because it is a gratuitous promise without fresh consideration"],"answer":1,"explanation":"Section 2(d) recognises an act already done ('has done') at the desire of the promisor as consideration. Indian law accepts past consideration, unlike English law.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-71","question":"Which of these agreements made without consideration are valid? (a) A father's written and registered promise, made out of natural love and affection, to give a house to his son (b) An oral promise to pay a time-barred debt (c) A promise to compensate a person who has already voluntarily paid a tax on the promisor's behalf (d) An unwritten promise to give someone a gift in future","options":["(a) only","(a), (b) and (c)","(a) and (c) only","All four"],"answer":2,"explanation":"Section 25 exceptions: (a) written, registered, natural love and affection between near relations; (c) compensation for something already done voluntarily for the promisor. A promise to pay a time-barred debt must be in writing and signed, so (b) fails; (d) has no exception.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-72","question":"A minor mortgages his house to a moneylender in return for a loan and later sues to have the mortgage cancelled. What is the legal position of the mortgage?","options":["Valid, since the minor received and used the loan money","Voidable at the lender's option once the minor's age is known","Valid once the minor attains majority and ratifies it","Void ab initio; the minor cannot be held liable on it"],"answer":3,"explanation":"An agreement with a minor is void ab initio (Mohori Bibee v Dharmodas Ghose), so the mortgage cannot be enforced against him.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-73","question":"How many of these statements about minors are correct? (1) A minor can be a promisee or beneficiary under a contract. (2) An agreement with a minor is void ab initio. (3) A minor can act as an agent. (4) A minor can be admitted to the benefits of an existing partnership with the consent of all partners.","options":["One","Two","Three","Four"],"answer":3,"explanation":"All four are correct. Mohori Bibee v. Dharmodas Ghose held a minor's agreement void ab initio; a minor can still be a promisee or beneficiary, can act as an agent (the principal is bound), and can be admitted to the benefits of a partnership with all partners' consent.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-74","question":"A person who is usually of unsound mind but occasionally of sound mind:","options":["Can never make a valid contract at any time","May make a contract when he is of sound mind","Can contract only through a court-appointed guardian","Can contract only for necessaries supplied to him"],"answer":1,"explanation":"Section 12: a person usually of unsound mind but occasionally sound may contract when he is of sound mind; the reverse applies to a person usually sound but occasionally not.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-75","question":"C, a stranger to the deal, threatens to harm A's son unless A sells his car cheaply to B. B knows nothing of the threat. What is the status of the contract?","options":["Valid, because B neither used nor knew of the coercion","Void ab initio, as A's free consent was wholly absent","Voidable by A, as coercion may come from any person","Illegal, so neither party can enforce it against the other"],"answer":2,"explanation":"Coercion need not come from the other party, and it may be directed against anyone; it makes the contract voidable at the option of the party whose consent was so obtained.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-76","question":"A spiritual guru persuades a devotee to gift him most of her property. The devotee later challenges the gift. Which is correct?","options":["Valid unless the devotee herself proves fraud or coercion","Void, because spiritual advisers cannot lawfully receive gifts from devotees","Valid, because a gift needs no consideration to be binding","Voidable; the guru must prove he did not exercise undue influence"],"answer":3,"explanation":"Where one party is in a position to dominate the will of the other (a spiritual adviser over a devotee) and the transaction looks unconscionable, undue influence is presumed and the dominant party must prove it was not used.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-77","question":"How many of these statements are correct? (1) Misrepresentation is an innocent false statement, while fraud is made knowingly or recklessly to deceive. (2) Both make the contract voidable at the option of the deceived party. (3) Mere silence about facts likely to affect consent is always fraud. (4) A contract is not voidable for misrepresentation if the party could have discovered the truth with ordinary diligence.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (4) are correct. (3) is wrong: silence is fraud only where there is a duty to speak or the silence is itself equivalent to speech.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-78","question":"How many of these statements about mistake are correct? (1) If both parties are mistaken about a fact essential to the agreement, it is void. (2) A unilateral mistake of fact makes the contract voidable. (3) A contract is not voidable because of a mistake about a law in force in India. (4) A mistake about a foreign law is treated like a mistake of fact.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1) Section 20, (3) Section 21 and (4) its proviso are correct. (2) is wrong: under Section 22 a unilateral mistake of fact does not make a contract voidable.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-79","question":"Which of these agreements is void?","options":["An agreement in restraint of an adult's marriage","An agreement made with an illiterate pardanashin woman","An agreement made under coercion by a third party","An agreement to sell goods on credit for six months"],"answer":0,"explanation":"Section 26 makes agreements in restraint of the marriage of any person other than a minor void. Coercion makes a contract voidable, not void.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-80","question":"A sells the goodwill of his business to B and agrees not to carry on a similar business within the same city for three years. Is the restraint enforceable?","options":["No, as Section 27 voids every agreement in restraint of trade","Yes, if the limits are reasonable, under the sale-of-goodwill exception","Only if the restraint is registered with the Registrar of Firms within a year","Only if B pays separate extra consideration for the restraint"],"answer":1,"explanation":"Section 27 makes restraints of trade void, but its exception allows a seller of goodwill to agree not to compete within specified local limits, so long as they are reasonable.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-81","question":"Which of these clauses in a commercial contract are valid? (1) Future disputes will be referred to arbitration. (2) A party's rights are extinguished unless he sues within three months. (3) Only the courts of Mumbai, which have jurisdiction, will hear disputes. (4) Neither party may approach any court at all.","options":["(1) and (3) only","(1), (2) and (3)","(1) only","All four"],"answer":0,"explanation":"Section 28 voids agreements that absolutely restrict legal proceedings or extinguish rights on a shortened period. Arbitration clauses and choosing one of several competent courts are allowed.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-82","question":"Consent is NOT free when it is caused by:","options":["Advertisement","Negotiation","Coercion","Discount"],"answer":2,"explanation":"Coercion, undue influence, fraud, misrepresentation and mistake prevent consent from being free.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-83","question":"A agrees to pay B ₹1 lakh if B marries C. C dies before any marriage. What happens to the agreement?","options":["B can claim the money, as A's promise was absolute","It becomes voidable at A's option","A must pay half, as B was ready to perform","It becomes void, as the event is now impossible"],"answer":3,"explanation":"A contingent contract to do something if an uncertain event happens becomes void when that event becomes impossible (Section 32).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-84","question":"A promises to pay B ₹5 lakh if a certain ship does not return within a year. The ship sinks six months later. Can B enforce the promise now?","options":["Yes, as it is now certain the ship will not return in time","No, he must wait until the full year has run out","No, the contract is void as a wagering agreement","Only if the ship was insured and the insurer has already paid out on it"],"answer":0,"explanation":"Under Section 35, a contract contingent on an event not happening within a fixed time can be enforced when the time expires or when it becomes certain before then that the event will not happen.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-85","question":"Assertion (A): A contract of insurance is not a wagering agreement. Reason (R): The insured has an insurable interest in the subject matter, and the contract protects against a real loss.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"In a wager neither party has any interest other than the stake. Insurance is valid because the insured stands to suffer a genuine loss, which is what R says.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-86","question":"A agrees to pay a public servant ₹2 lakh to secure a government job for A's son. What is the status of the agreement?","options":["Valid, if the job is in fact obtained for the son","Voidable at A's option, as he was induced to pay","Void, as its object is unlawful and opposed to public policy","Valid, but the money is refundable to A if no government job comes"],"answer":2,"explanation":"An agreement whose object involves corruption of public officers is unlawful under Section 23 and void.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-87","question":"A agrees to sell his house to B for ₹50 lakh, and further agrees that if B uses it as a gambling den, B will pay ₹1 crore. Which is correct?","options":["The whole agreement is void, as it is tainted throughout by gambling","Both promises are enforceable, as B agreed to both","Only the second promise is enforceable, as it is specific","The sale for ₹50 lakh is enforceable; the second promise is void"],"answer":3,"explanation":"Section 57: where persons promise first to do legal things and then, in specified circumstances, illegal things, the first set is a contract and the second a void agreement.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-88","question":"How does an illegal agreement differ from an agreement that is merely void?","options":["They are identical in effect; both are simply unenforceable","Collateral transactions are tainted by an illegal agreement but not by a merely void one","A void agreement can be ratified later, but an illegal one cannot","An illegal agreement stays valid and enforceable until it is challenged in court by a party"],"answer":1,"explanation":"Every illegal agreement is void, but not every void agreement is illegal. Agreements collateral to an illegal one are also void; those collateral to a merely void agreement can be enforced.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-89","question":"Which of these is NOT an exception to the rule that a stranger to a contract cannot sue on it?","options":["A creditor of a party who expects payment from the contract proceeds","A beneficiary under a trust created by the contract","A person entitled to provision under a family settlement","A person to whom a party has expressly acknowledged an obligation (estoppel)"],"answer":0,"explanation":"Recognised exceptions include trusts, family settlements, acknowledgement or estoppel, covenants running with land and agency. A mere creditor of a party has no right to sue on the contract.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-90","question":"At an auction, a bidder makes the highest bid but withdraws it before the auctioneer's hammer falls. Which is correct?","options":["He is bound, because the highest bid is itself an acceptance","He may withdraw, but is liable to pay damages to the seller","He can withdraw: a bid is an offer until the hammer falls","He can withdraw only with the seller's consent to the withdrawal"],"answer":2,"explanation":"In an auction the auctioneer invites offers; each bid is an offer that can be withdrawn until it is accepted by the fall of the hammer.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-91","question":"A finds a wallet lying on the road and takes it. What is his legal position with respect to the wallet?","options":["He becomes its owner","He is in the position of a bailee","He is the owner's agent","He becomes a trustee only after one year"],"answer":1,"explanation":"Under Section 71, a person who finds goods belonging to another and takes them into custody has the same responsibility as a bailee.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-92","question":"A delivers goods to B's house by mistake, intending no gift. B knows this and uses the goods. What is B's liability?","options":["None, because there was no contract between A and B","B must return only what remains unused, and need pay nothing for the rest","B must pay only if he signed a receipt for the goods","B must compensate A, who acted non-gratuitously, for the benefit"],"answer":3,"explanation":"Section 70: where a person lawfully does something for another, not intending to do so gratuitously, and the other enjoys the benefit, the latter must compensate or restore it.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-93","question":"A pays ₹40,000 to a municipality as property tax under the mistaken belief that he owes it; in fact the liability is B's. What can A do?","options":["Recover it from the municipality, as money paid by mistake","Nothing, as tax once paid can never be recovered","Recover it only from B, whose tax liability he has discharged by mistake","Recover it only if the municipality agrees to refund"],"answer":0,"explanation":"Section 72: a person to whom money is paid by mistake or under coercion must repay or return it.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-94","question":"B holds land on lease from A. B fails to pay the government revenue due on it, and the land is advertised for sale. A pays the revenue to prevent the sale. What is A's right?","options":["None, because he paid voluntarily without B's request","He becomes owner of B's leasehold interest in the land","Recover it from B, as an interested person paying B's dues","He can recover it only from the government as excess revenue"],"answer":2,"explanation":"Section 69: a person interested in paying money that another is bound by law to pay, who pays it, is entitled to be reimbursed by that other.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-95","question":"A mill's broken crankshaft is given to a carrier to take to the makers as a pattern. The carrier is told nothing about the mill being idle without it, and delivers late. Can the mill owner recover the profits lost during the delay?","options":["Yes, all losses caused by the breach are recoverable","No: the lost profit was neither natural nor contemplated","Yes, but only half, as both parties were at fault","Only if the carrier was negligent in transporting the crankshaft"],"answer":1,"explanation":"Hadley v Baxendale: damages cover losses arising naturally from the breach or that both parties contemplated when contracting. Special circumstances not communicated make the loss too remote.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-96","question":"A contract states that ₹5 lakh is payable on breach. One party breaks it; the other's actual loss is ₹2 lakh. Under Section 74, what can the court award?","options":["Exactly ₹5 lakh, as agreed by both parties","Only the proved actual loss of ₹2 lakh, strictly measured by evidence","₹5 lakh plus the actual loss of ₹2 lakh","Reasonable compensation up to ₹5 lakh, without exact proof of loss"],"answer":3,"explanation":"Section 74 ignores the English penalty/liquidated-damages split: the court awards reasonable compensation capped at the stipulated sum, and actual loss need not be proved exactly. The tempting 'exactly ₹5 lakh' is wrong because the full sum is not automatic, and 'only proved loss' is wrong because exact proof is not required.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-97","question":"On 1 March, A tells B he will not deliver the goods due on 1 June. What is B's position?","options":["B may treat the contract as ended and sue now, or wait till 1 June","B must wait until 1 June before taking any legal action","The contract becomes automatically void the moment A states his refusal","B can only claim specific performance on 1 June"],"answer":0,"explanation":"An anticipatory breach lets the promisee rescind and sue immediately, or keep the contract alive until the due date (Section 39); if he waits, he takes the risk of supervening events.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-98","question":"B agreed to buy 1,000 units at ₹500 each but refused delivery on the due date, when the market price was ₹440. The seller resold a month later at ₹400. What damages can the seller recover?","options":["₹1,00,000","₹40,000","₹60,000","₹5,00,000"],"answer":2,"explanation":"Damages = (contract price − market price on the date of breach) × quantity = (500 − 440) × 1,000 = ₹60,000. The further fall to ₹400 is the seller's loss for not mitigating promptly.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-99","question":"A hires a hall for a concert, but the hall is destroyed by fire, through no one's fault, before the concert date. What happens to the contract?","options":["The hall owner must pay damages for non-performance","It becomes void, as performance is now impossible","A must still pay the rent agreed for the concert","It is suspended until the hall is rebuilt and available"],"answer":1,"explanation":"Section 56: a contract to do an act that afterwards becomes impossible, through no fault of the promisor, becomes void (supervening impossibility, as in Taylor v Caldwell).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-100","question":"A owes B ₹1 lakh. A, B and C agree that B will accept C as his debtor instead of A. This is:","options":["Rescission","Alteration","Remission","Novation"],"answer":3,"explanation":"Substituting a new contract (here with a new party) for the old one is novation (Section 62); the original contract need not be performed.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-101","question":"A publisher commissions A to write a book for a series for ₹50,000. After A has written half the book, the publisher abandons the series. What can A claim?","options":["Reasonable pay for work done, on a quantum meruit basis","Nothing, because the book was not completed as the contract required","The full ₹50,000, but only after finishing the book","Only his out-of-pocket expenses incurred on the book"],"answer":0,"explanation":"When one party is prevented from completing performance by the other's breach, he can recover reasonable remuneration for what he has done (quantum meruit, as in Planche v Colburn).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-102","question":"A contract by which one party promises to save the other from loss caused by the conduct of the promisor or any other person is a contract of:","options":["Guarantee","Bailment","Indemnity","Agency"],"answer":2,"explanation":"Section 124 defines a contract of indemnity; a guarantee involves a promise to discharge a third person's liability on default.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-103","question":"In a contract of guarantee, the three parties are:","options":["Indemnifier, indemnity holder and creditor","Surety, principal debtor and creditor","Bailor, bailee and surety","Principal, agent and creditor"],"answer":1,"explanation":"The surety gives the guarantee, the principal debtor owes the money, and the creditor receives the guarantee.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-104","question":"B borrows from C, with A as surety. B defaults. C sues A without first suing B. Is this allowed?","options":["No, the creditor must first exhaust his remedies against B","Yes, as the surety's liability is co-extensive with B's","Only if B has been declared insolvent by a court","Only with the court's permission, after notice to B"],"answer":1,"explanation":"Section 128 makes the surety's liability co-extensive with the debtor's. Unless the contract says otherwise, the creditor may proceed against the surety directly.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-105","question":"A gives C a continuing guarantee for goods C supplies to B, up to ₹5 lakh. B buys goods worth ₹2 lakh and then ₹1.5 lakh. A then revokes the guarantee by notice to C. Afterwards B buys a further ₹1 lakh. B defaults on everything. What is A's liability?","options":["₹4.5 lakh","₹5 lakh","Nil","₹3.5 lakh"],"answer":3,"explanation":"A continuing guarantee can be revoked for future transactions by notice (Section 130). A remains liable for transactions before revocation: 2 + 1.5 = ₹3.5 lakh, not for the ₹1 lakh supplied afterwards.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-106","question":"A guarantees that C will lend B ₹5 lakh repayable in 12 months. Without A's consent, C and B change the loan to ₹8 lakh repayable in 24 months. What is A's position?","options":["A is discharged as to transactions after the variance","A is liable for ₹8 lakh, as he guaranteed the loan","A is liable for ₹5 lakh, repayable in 24 months","A remains liable in full until he objects in writing to C"],"answer":0,"explanation":"Section 133: any variance in the terms between the creditor and principal debtor without the surety's consent discharges the surety as to transactions after the variance.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-107","question":"How many of these discharge a surety, wholly or partly? (1) The creditor releases the principal debtor. (2) The creditor varies the terms of the contract with the debtor without the surety's consent. (3) The creditor makes a binding agreement to give the debtor extra time, without the surety's consent. (4) The creditor loses a security that was given at the time of the guarantee.","options":["One","Two","Three","Four"],"answer":3,"explanation":"All four discharge the surety: variance in terms (Section 133), release of the principal debtor (Section 134) and a binding agreement to give time (Section 135) discharge him wholly, and loss of security discharges him to the extent of its value (Section 141).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-108","question":"A surety pays the whole debt to the creditor after the principal debtor defaults. What right does the surety get?","options":["Only a right to a share of the principal debtor's future profits","None, because a guarantee is a gratuitous promise","A right to sue the creditor for the amount paid","The creditor's rights and securities against the debtor"],"answer":3,"explanation":"On payment, the surety steps into the creditor's shoes (Section 140) and may recover the amount from the principal debtor (Section 145).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-109","question":"A, B and C separately guarantee the same debt with limits of ₹1 lakh, ₹2 lakh and ₹3 lakh, with no agreement among themselves. The debtor defaults on ₹4 lakh. How much does C bear?","options":["₹2 lakh","₹1.5 lakh","₹1.33 lakh","₹3 lakh"],"answer":1,"explanation":"Section 147: co-sureties bound in different sums pay equally as far as their limits allow. Equal shares would be ₹1.33 lakh each, but A's limit is ₹1 lakh; the remaining ₹3 lakh is shared equally by B and C: ₹1.5 lakh each. Sharing in proportion to limits (₹2 lakh) is wrong.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-110","question":"Which of these is a bailment?","options":["Leaving a car with a mechanic for repair","Depositing money in a savings account","Parking in a self-park lot while keeping the car keys","Buying goods on credit"],"answer":0,"explanation":"Bailment is delivery of goods for a purpose, to be returned or dealt with as directed. A bank deposit is a debt, not bailment of the same notes; keeping your keys means no delivery of possession.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-111","question":"A bailee takes the care of the goods that a prudent person would take of his own similar goods, but they are stolen by armed robbers. There is no special contract. Is the bailee liable?","options":["Yes, a bailee is an insurer of the goods bailed","Yes, but only for half the value of the goods","No, as he took the care required of a bailee","Only if the goods were valuable and declared"],"answer":2,"explanation":"Sections 151–152: a bailee must take the care of a man of ordinary prudence; having done so, he is not liable for loss in the absence of a special contract.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-112","question":"Which of these statements about liens are correct? (1) A tailor may keep a suit until he is paid for stitching it. (2) Without any agreement, a tailor may keep a suit to recover dues on earlier, already delivered suits. (3) Bankers have a general lien. (4) Wharfingers have a general lien.","options":["(1) and (3) only","(1), (3) and (4) only","(2), (3) and (4) only","All four"],"answer":1,"explanation":"(1) is a particular lien for skill and labour on the goods (Section 170). (2) would need a general lien, which only bankers, factors, wharfingers, attorneys of a High Court and policy brokers have, or one given by agreement (Section 171).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-113","question":"A mercantile agent in possession of goods with the owner's consent pledges them, in the ordinary course of business, to a pawnee who acts in good faith and has no notice of any lack of authority. Is the pledge valid?","options":["No, only the owner himself can validly pledge goods he owns","Only if the owner later ratifies the agent's pledge","No, it is void as against the owner of the goods","Yes, as valid as if the owner had expressly authorised it"],"answer":3,"explanation":"Section 178 protects a good-faith pawnee who takes a pledge from a mercantile agent in possession with the owner's consent, acting in the ordinary course of business.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-114","question":"A pawns gold for a loan of ₹1,00,000 and defaults. After reasonable notice, the pawnee sells the gold for ₹1,30,000, incurring sale expenses of ₹5,000. What happens to the proceeds?","options":["The pawnee keeps the ₹30,000","₹30,000 is paid to the pawnor","₹1,25,000 is paid to the pawnor","₹25,000 is paid to the pawnor"],"answer":3,"explanation":"Section 176: on default and reasonable notice, the pawnee may sell; he recovers the debt and sale expenses, and any surplus goes to the pawnor: 1,30,000 − 1,00,000 − 5,000 = ₹25,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-115","question":"In agency, the person for whom the agent acts is called the:","options":["Principal","Bailor","Surety","Indemnifier"],"answer":0,"explanation":"An agent is employed to act for, or represent, another person, called the principal (Section 182).","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-116","question":"An agent exceeds his authority and buys two machines on the principal's behalf. The principal wants to ratify the purchase of one and reject the other, which were bought in one transaction. Can he?","options":["No: ratifying part of a transaction ratifies the whole","Yes, he may ratify whichever part of it he chooses","Yes, but he must then pay the agent's commission on both machines","Only with the seller's consent to splitting the deal"],"answer":0,"explanation":"Section 199: a person ratifying an unauthorised act done on his behalf ratifies the whole transaction of which it forms part.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-117","question":"A authorises B to sell A's land and to pay himself, out of the proceeds, a debt that A owes him. A later wants to revoke B's authority, and then A dies. What is the position?","options":["A can revoke at any time, and his death ends the agency","Neither revocation nor A's death ends it, as B has an interest","Only A's legal heirs can revoke it after his death","The agency ends automatically when A's debt to B falls due for payment"],"answer":1,"explanation":"Section 202: where the agent has an interest in the property that is the subject of the agency, the agency cannot be ended to the prejudice of that interest, even by the principal's death or insanity.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-118","question":"An agent contracts with a third party without disclosing that he acts for a principal. The third party later discovers the principal. Whom can the third party hold liable?","options":["Only the agent","Only the principal","Neither, because the contract is void","Either the agent or the principal"],"answer":3,"explanation":"With an undisclosed principal, the third party can enforce the contract against the agent, or against the principal on discovering him (Section 231 and the following provisions).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-119","question":"How many of these statements are correct? (1) A sub-agent acts under the control of the original agent. (2) The agent is responsible to the principal for the acts of a properly appointed sub-agent. (3) A properly appointed sub-agent is directly responsible to the principal for ordinary negligence. (4) A substituted agent, named with the principal's authority, becomes the principal's own agent.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (4) are correct (Sections 191, 192 and 194). (3) is wrong: a sub-agent is responsible to the principal only for fraud or wilful wrong, otherwise only to the agent.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-120","question":"Which of these ordinarily ends an agency?","options":["The agent's change of residential address","A sharp rise in the market price of the goods","The death or insanity of principal or agent","The principal's failure to sign a letter"],"answer":2,"explanation":"Section 201: an agency ends on revocation, renunciation, completion of the business, death or insanity of either party, or the principal's insolvency (subject to the exception for agency coupled with interest).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-121","question":"Under the Sale of Goods Act, how does a 'sale' differ from an 'agreement to sell'?","options":["In a sale, ownership passes at once; in an agreement to sell, later","In a sale, the price is always paid later than in an agreement to sell","An agreement to sell must be in writing, but a sale may be oral","There is no difference; the terms are used interchangeably"],"answer":0,"explanation":"A sale transfers property in the goods immediately; an agreement to sell becomes a sale when the time elapses or the conditions are met.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-122","question":"What remedy does a buyer have for a breach of warranty, as opposed to a breach of condition?","options":["He may reject the goods and also claim damages","He may claim damages only, not reject the goods","He may only reject the goods, with no damages","He has no remedy once the goods have been delivered"],"answer":1,"explanation":"A condition is essential to the main purpose; its breach allows repudiation. A warranty is collateral; its breach gives only a claim for damages.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-123","question":"A buyer accepts goods under a contract that is not severable and later discovers a breach of a condition. What can he do (absent any contrary term)?","options":["Reject the goods and recover the full price paid","Rescind the contract at any time within the limitation period","Nothing at all, as acceptance waives every breach","Claim damages only, as for a breach of warranty"],"answer":3,"explanation":"Section 13(2): once a buyer has accepted the goods under a non-severable contract, a breach of condition can be treated only as a breach of warranty.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-124","question":"In a sale by sample as well as by description, the goods must:","options":["Correspond with the sample only, as it prevails","Correspond with the description only, as it prevails","Correspond with both the sample and the description","Only be of merchantable quality, nothing more"],"answer":2,"explanation":"Section 15: where goods are sold by sample as well as description, it is not enough that the bulk matches the sample if it does not also match the description.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-125","question":"A buyer asks a chemist for a hot-water bottle and relies on the chemist's choice. The bottle bursts on first use and injures her. Which is correct?","options":["The seller is liable: purpose known, reliance on his skill, goods unfit","No liability, because of the rule of caveat emptor","Liability only if the bottle was sold under a brand name","Only the manufacturer can be liable for a defect, not the retail chemist"],"answer":0,"explanation":"Section 16(1) implies a condition of fitness for purpose when the buyer makes the purpose known (it can be obvious, as here) and relies on the seller's skill or judgment, and the seller deals in such goods.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-126","question":"How many of these are implied in a contract of sale (unless excluded)? (1) A condition that the seller has the right to sell (2) A warranty that the buyer will enjoy quiet possession (3) A condition that the goods are fit for any purpose the buyer privately has in mind (4) A condition of merchantable quality where goods are bought by description from a seller who deals in such goods","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (4) are implied (Sections 14 and 16(2)). (3) is not: fitness for purpose is implied only when the purpose is made known and the buyer relies on the seller.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-127","question":"A buys a specific car that is in a deliverable state; delivery and payment are fixed for next week. That night the car is destroyed by fire without the seller's fault. Who bears the loss?","options":["The seller, because the car was still in his possession","They share it equally, as neither was at fault","The buyer only after he pays the price next week","The buyer, as property and risk passed on the contract"],"answer":3,"explanation":"Section 20: for an unconditional contract for specific goods in a deliverable state, property passes when the contract is made, even if payment and delivery are postponed; risk prima facie passes with property (Section 26).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-128","question":"A agrees to sell B a specific heap of rice at ₹40 a kg; the seller must weigh it to fix the price. Before it is weighed, the rice is destroyed by flood without anyone's fault. Who bears the loss?","options":["The buyer, because the goods were specific and identified at the contract","The seller, as property passes only after weighing and notice","They share it in proportion to the price paid so far","Neither: the contract becomes voidable by either party"],"answer":1,"explanation":"Section 22: where the seller must weigh, measure or test specific goods to fix the price, property passes only when that is done and the buyer has notice. Risk therefore stayed with the seller.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-129","question":"Goods are delivered to B on approval ('sale or return'). Before approving them, B pledges the goods with a moneylender. What is the effect?","options":["Property passes to B, as pledging adopts the transaction","Nothing changes; B can still return the goods to the seller","The pledge is void, as B was not yet the owner","Property passes only when B actually pays the price"],"answer":0,"explanation":"Section 24: property passes on approval, on any other act adopting the transaction (such as pledging or selling the goods), or on retaining them beyond the fixed or a reasonable time.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-130","question":"Which of these is NOT an exception to the rule that no one can give a better title than he himself has?","options":["Sale by a mercantile agent in possession with the owner's consent","Sale by a seller who stays in possession after a sale","Sale by a person with a voidable title before it is rescinded","Sale by a thief to an innocent buyer for value"],"answer":3,"explanation":"The Act protects good-faith buyers in the first three situations. A thief has no title at all, so even an innocent buyer for value gets none.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-131","question":"Who is an 'unpaid seller' under the Sale of Goods Act?","options":["A seller who has received the whole price in cash","A seller paid by a cheque that was duly honoured","A seller whose cheque from the buyer was dishonoured","A seller paid in full by bank transfer before delivery"],"answer":2,"explanation":"Section 45: a seller is unpaid when the whole price has not been paid or tendered, or when a negotiable instrument received as conditional payment has been dishonoured.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-132","question":"When can an unpaid seller exercise the right of stoppage in transit?","options":["Whenever any part of the price remains unpaid","On the buyer's insolvency, while goods are in transit","Only before the goods are handed to the carrier","Only if he still holds the bill of lading or other document of title"],"answer":1,"explanation":"Stoppage in transit (Section 50) is available only on the buyer's insolvency while the goods are with a carrier. Before handing over, the seller relies on his lien instead.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-133","question":"How many of these statements about an unpaid seller's rights are correct? (1) The lien depends on the seller keeping possession. (2) Stoppage in transit is available even if the buyer is solvent. (3) The lien is lost when the buyer lawfully obtains possession. (4) The lien is lost merely because the seller has obtained a court decree for the price.","options":["One","Two","Three","Four"],"answer":1,"explanation":"(1) and (3) are correct. (2) is wrong: stoppage needs insolvency. (4) is wrong: Section 49(2) says the seller does not lose his lien just because he has obtained a decree for the price.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-134","question":"At an auction that was not notified as subject to the seller's right to bid, the seller secretly employs a person to bid up the price. What can the buyer do?","options":["Nothing, as bidding by anyone is allowed","Only claim the difference in price","Report it but remain bound","Treat the sale as fraudulent"],"answer":3,"explanation":"Section 64: unless the right to bid is expressly reserved and notified, the seller may not bid or employ anyone to bid, and a sale in breach may be treated as fraudulent by the buyer.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-135","question":"A buyer ordered 100 units; the seller delivers 120. What may the buyer do?","options":["Accept 100 and reject 20, reject all, or take all 120 at contract rate","He must accept all 120 and pay for them at the contract rate","He must reject all 120, as a delivery of the wrong quantity cannot be accepted","He may accept all 120 but pay only for 100 at the contract rate"],"answer":0,"explanation":"Section 37 gives the buyer these choices when a larger quantity is delivered; if a smaller quantity is delivered, he may reject it or accept it and pay at the contract rate.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-136","question":"Which of these is NOT a negotiable instrument under the Negotiable Instruments Act, 1881?","options":["Promissory note","Bill of exchange","Cheque drawn on a bank","Share certificate"],"answer":3,"explanation":"The Act names promissory notes, bills of exchange and cheques; a share certificate is evidence of title to shares, not a negotiable instrument under this Act.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-137","question":"Under the Negotiable Instruments Act, 1881, a cheque is:","options":["A bill of exchange payable after a fixed period from sight","A bill on a specified banker payable only on demand, incl. e-cheques","A promissory note issued by a bank on behalf of its customer","Any unconditional written order to pay money to a named person or bearer"],"answer":1,"explanation":"Section 6 defines a cheque this way; it is always on a banker and always payable on demand.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-138","question":"X receives a cheque from Y as a birthday gift and takes it in good faith before it is due. Is X a holder in due course?","options":["Yes, because he took it in good faith","Yes, because he took it before maturity","No, because he did not take it for consideration","Only if Y was the drawer and signed it in X's favour"],"answer":2,"explanation":"A holder in due course must obtain the instrument for consideration, before maturity and without cause to believe there is any defect in the transferor's title (Section 9). A gift fails the consideration test.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-139","question":"How many of these statements are correct? (1) A holder in due course can get a better title than his transferor. (2) A holder who takes through a holder in due course and was not a party to any fraud has the same rights. (3) To be a holder in due course, a person must take the instrument for consideration, in good faith, before it becomes payable. (4) Every holder is presumed to be a holder in due course until the contrary is proved.","options":["One","Two","Three","Four"],"answer":3,"explanation":"All four are correct: (1) and (2) (Section 53) state the privileges of a holder in due course, (3) is the definition in Section 9, and (4) is the presumption in Section 118(g).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-140","question":"A cheque has two parallel transverse lines with 'HDFC Bank Ltd' written between them. This is a:","options":["Special crossing: payable only through HDFC Bank","General crossing, as two parallel lines are drawn","Not-negotiable crossing restricting transfer","Open cheque, payable in cash across the counter"],"answer":0,"explanation":"Writing a banker's name across the cheque, with or without lines, is a special crossing (Section 124). Two lines alone would be a general crossing.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-141","question":"A cheque is dishonoured and the payee sends the statutory demand notice under Section 138, which the drawer receives on 5 March. By what date must the drawer pay to avoid the offence?","options":["17 March","20 March","1 April","4 April"],"answer":1,"explanation":"The drawer has 15 days from receipt of the notice: 5 March + 15 days = 20 March. If he fails, the cause of action arises the next day and the complaint must be filed within one month of that.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-142","question":"Notice of dishonour is NOT necessary to charge the drawer when:","options":["The drawee is a public-sector bank","The amount of the cheque is below ₹10,000","The holder of the cheque is a minor","The drawer has countermanded payment"],"answer":3,"explanation":"Section 98 dispenses with notice in cases such as when the drawer has countermanded payment, when the party entitled has waived it, or when the party charged could suffer no damage from lack of notice.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-143","question":"In a promissory note, the person who promises to pay is called the:","options":["Drawer","Maker","Drawee","Endorsee"],"answer":1,"explanation":"A promissory note has a maker (who promises) and a payee. A bill of exchange has a drawer, a drawee and a payee.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-144","question":"A bill dated 15 January is payable two months after date. Three days of grace apply, and the resulting date is a public holiday. On what date is the bill due?","options":["17 March","18 March","19 March","15 March"],"answer":0,"explanation":"Two months after 15 January is 15 March; adding three days of grace gives 18 March. Because that day is a public holiday, the bill falls due on the preceding business day (Section 25): 17 March.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-145","question":"Which of these is NOT a material alteration of a negotiable instrument?","options":["Changing the date without the drawer's consent","Changing the amount without the drawer's consent","Converting a blank endorsement into a full one","Changing the place of payment without consent"],"answer":2,"explanation":"A holder may convert a blank endorsement into a full one (Section 49) without it being a material alteration. Changing the date, amount or place of payment without consent voids the instrument against non-consenting parties.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-146","question":"An endorser writes 'sans recourse' with his endorsement. What is the effect?","options":["He becomes liable to all later holders without limit","The instrument stops being negotiable","He guarantees payment by the drawee","He excludes his own liability to later holders"],"answer":3,"explanation":"Section 52 lets an endorser exclude his own liability by express words such as 'sans recourse'; the instrument stays negotiable.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-147","question":"A cheque reads 'Pay Ramesh or order'. Ramesh endorses it by signing only his name on the back. To whom is it now payable?","options":["To the bearer","Only to Ramesh","Only to Ramesh's bank","To no one until a full endorsement is added"],"answer":0,"explanation":"An endorsement in blank (signature only) makes the instrument payable to bearer (Section 54), until it is converted into a full endorsement.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-148","question":"A signs a blank promissory note on adequately stamped paper and gives it to B to fill in ₹20,000. B fills in ₹50,000 (within the stamp's coverage) and negotiates it for value to C, a holder in due course. How much can C recover from A?","options":["₹20,000 only, the agreed amount","₹50,000, because the stamp covers that amount","Nothing, as the note was incomplete when signed","₹30,000, the excess"],"answer":1,"explanation":"Section 20 (inchoate stamped instruments): the signer is liable to a holder in due course for any amount filled in, up to the amount the stamp covers. As between A and B, only ₹20,000 was authorised.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-149","question":"A agrees to sell B a specific cargo of wheat on a ship. Unknown to both, the ship had already sunk with the cargo before the agreement. What is the effect?","options":["The seller must supply another cargo","The buyer must pay the price","The contract is voidable at the buyer's option","The agreement is void"],"answer":3,"explanation":"Section 7 of the Sale of Goods Act: a contract for specific goods that, without the seller's knowledge, have perished at the time of the contract is void.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-150","question":"If the price is not fixed by the contract or by any agreed method, the buyer must pay:","options":["A reasonable price","The price the seller demands","The cost price","Nothing, as the contract is void"],"answer":0,"explanation":"Section 9(2): where the price is not determined, the buyer pays a reasonable price, which depends on the circumstances of each case.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-151","question":"Which case established that a company is a legal person separate from its members, even when one person holds almost all its shares?","options":["Royal British Bank v Turquand","Ashbury Railway Carriage v Riche","Salomon v Salomon & Co","Hadley v Baxendale"],"answer":2,"explanation":"Salomon v Salomon & Co (1897) held that a duly incorporated company is a distinct person from its members, so Mr Salomon as a secured creditor ranked ahead of unsecured creditors.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-152","question":"What is the minimum number of members needed to form a private company (other than a one person company)?","options":["Two","Seven","One","Three"],"answer":0,"explanation":"A private company needs at least two members, a public company seven and a one person company one.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-153","question":"A company's articles allow directors to borrow if authorised by a general-meeting resolution. A lender, acting in good faith, lends to the company on the directors' word, but no resolution had been passed. Is the company bound?","options":["No, because the lender is deemed to have constructive notice of the articles","Only if the shareholders later ratify the borrowing","No, the loan is void as no resolution was passed","Yes: indoor management lets outsiders assume internal steps were taken"],"answer":3,"explanation":"Royal British Bank v Turquand: an outsider who knows the articles permit the act need not check that internal formalities, such as passing a resolution, were actually carried out.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-154","question":"In which situation can an outsider NOT rely on the doctrine of indoor management?","options":["The company's internal resolution was passed late","The document he relied on was a forgery","The directors had not yet signed the minutes","The company had not filed its annual return"],"answer":1,"explanation":"The doctrine does not protect an outsider who knew of the irregularity, was put on enquiry by suspicious circumstances, or relied on a forged document, since a forgery is a nullity.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-155","question":"The doctrine of constructive notice means that a person dealing with a company is deemed to know:","options":["Its internal board minutes and proceedings","The private agreements among its directors","The contents of its memorandum and articles","Its future business plans as filed with its banks"],"answer":2,"explanation":"Once registered, the memorandum and articles are public documents, so outsiders are presumed to know their contents (indoor management protects them on internal matters).","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-156","question":"A company enters into a contract wholly outside the objects in its memorandum. All the shareholders later pass a resolution ratifying it. What is the status of the contract?","options":["Void; an ultra vires act cannot be ratified, even unanimously","Valid after the unanimous ratification by all of the shareholders","Voidable at the company's option within a reasonable time","Valid if the board of directors had approved it beforehand"],"answer":0,"explanation":"Ashbury Railway Carriage v Riche: an act ultra vires the memorandum is void ab initio and cannot be ratified, even by all the shareholders.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-157","question":"At a general meeting, 600 votes are cast in favour of a resolution, 220 against and 300 members abstain. Which is correct?","options":["It passes as both an ordinary and a special resolution","Passes as an ordinary resolution, fails as a special one","It fails as both, as the 300 abstentions count against it","It passes as a special resolution only"],"answer":1,"explanation":"Ordinary: votes for (600) exceed votes against (220). Special: votes for must be at least three times votes against, 3 × 220 = 660; 600 falls short. Abstentions are not counted.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-158","question":"A company's financial year ends on 31 March 2026, and its previous AGM was held on 20 August 2025. Without any extension, by when must its next AGM be held?","options":["30 September 2026","20 November 2026","31 December 2026","20 August 2026"],"answer":0,"explanation":"An AGM (other than the first) must be held within six months of the end of the financial year (30 September 2026) and within 15 months of the last AGM (20 November 2026). The earlier date, 30 September 2026, applies.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-159","question":"A company's articles provide for 11 directors, but two seats are vacant. Under Section 174, quorum is one-third of the total strength (a fraction counts as one) or two directors, whichever is higher, and vacant seats are not counted in total strength. What is the quorum?","options":["4","2","3","6"],"answer":2,"explanation":"Total strength = 11 − 2 vacancies = 9. One-third of 9 = 3, which is more than two, so the quorum is 3. Counting the vacant seats gives one-third of 11 = 3.67, rounded to 4.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-160","question":"What is the minimum number of directors a public company must have?","options":["One","Two","Seven","Three"],"answer":3,"explanation":"Under Section 149, a public company needs at least three directors, a private company two and a one person company one.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-161","question":"Which requirement does the Companies Act, 2013 impose on every company's board?","options":["At least one director must be a chartered accountant","At least one director must be resident in India (182+ days)","All directors must be Indian citizens resident in India","At least half the directors must be independent directors, in all cases"],"answer":1,"explanation":"Section 149(3) requires at least one resident director, meaning one who has stayed in India for 182 days or more during the financial year. Independent-director requirements apply to listed and prescribed companies.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-162","question":"A listed public company has 10 directors. At least one-third of the total directors must be independent, and any fraction is rounded up to one. What is the minimum number of independent directors?","options":["3","4","5","2"],"answer":1,"explanation":"One-third of 10 = 3.33; the fraction counts as one, so at least 4 independent directors are needed. Truncating to 3 is the usual error.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-163","question":"If a company's articles conflict with its memorandum, which prevails?","options":["The articles, being the more detailed document","The later document, as it reflects the latest intent","Whichever of the two documents the board chooses to follow","The memorandum, as the articles are subordinate to it"],"answer":3,"explanation":"The memorandum is the charter defining the company's powers; the articles regulate internal management within those limits. A conflicting article is void to that extent.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-164","question":"A Section 8 company is formed for charitable objects. Which feature does it have?","options":["It must apply profits to its objects and cannot pay dividends","It pays a fixed dividend to members, capped at 6% a year","It must have at least seven members, like any other public company","It cannot own immovable property in its own name"],"answer":0,"explanation":"A Section 8 company promotes objects such as charity, education or art, applies its income to those objects and is prohibited from paying dividends to its members.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-165","question":"A former employee bound by a valid non-compete covenant forms a company, controlled by him and his family, to solicit his old employer's customers. What will the court most likely do?","options":["Refuse relief, as the company is a separate person not bound by the covenant","Order the company to be wound up as formed for a fraudulent purpose","Award damages only against the family members who hold the shares","Lift the veil and restrain both him and the company, as it is a sham"],"answer":3,"explanation":"Courts disregard the separate personality of a company used as a façade to evade an existing legal obligation (as in Gilford Motor Co v Horne).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-166","question":"Which element of the definition of partnership in Section 4 of the Indian Partnership Act reflects mutual agency?","options":["An agreement between persons to share the profits of a business","Business carried on by all or any of them acting for all","Profits of the business are shared among partners","The business carried on must be lawful"],"answer":1,"explanation":"'Carried on by all or any of them acting for all' means each partner is both an agent of the others and a principal, which is the true test of partnership.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-167","question":"An unregistered firm wants to sue a customer to recover money due under a contract. What is the position?","options":["It can sue freely, as registration is optional","It can sue only in small-cause courts for small claims","It cannot sue to enforce the contract, but can be sued","It can sue only if all the partners consent in writing"],"answer":2,"explanation":"Section 69 bars an unregistered firm (and its partners on its behalf) from suing third parties to enforce contractual rights; third parties can still sue the firm, and partners can sue for dissolution or accounts.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-168","question":"Which of these can a partner do under his implied authority, without specific authority from the other partners?","options":["Buy goods of the kind the firm usually deals in","Submit a dispute of the firm to arbitration","Transfer immovable property belonging to the firm","Open a bank account for the firm in his own name"],"answer":0,"explanation":"Section 19(2) excludes arbitration, opening an account in his own name, compromising claims, transferring immovable property and similar acts from implied authority. Ordinary trading acts are within it.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-169","question":"How many of these statements are correct? (1) A person admitted as a partner is not liable for the firm's debts incurred before he joined. (2) A retiring partner remains liable to third parties for the firm's acts until public notice of his retirement is given. (3) A deceased partner's estate is liable for the firm's acts done after his death. (4) A person who holds himself out as a partner is liable to anyone who gave credit to the firm on that basis.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (2) and (4) are correct (Sections 31, 32 and 28). (3) is wrong: under Section 35 the estate of a deceased partner is not liable for acts of the firm after his death.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-170","question":"In which situation is a firm compulsorily dissolved, without any court order?","options":["A partner becomes of unsound mind","The firm suffers a loss for one whole year","A partner transfers his share to an outsider","All partners, or all but one, are insolvent"],"answer":3,"explanation":"Section 41: compulsory dissolution occurs on the insolvency of all, or all but one, partners, or when the business becomes unlawful. Unsoundness of mind is a ground for dissolution by the court (Section 44).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-171","question":"Under the LLP Act, 2008, what is the minimum requirement for designated partners?","options":["One designated partner who is an individual","At least two, of whom at least one is resident in India","Seven designated partners, as for a public company","Two designated partners, both of whom must be Indian citizens"],"answer":1,"explanation":"Every LLP must have at least two partners and at least two designated partners who are individuals, at least one of them resident in India.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-172","question":"How many of these statements about an LLP are correct? (1) It is a body corporate with perpetual succession. (2) A partner is personally liable for another partner's wrongful act. (3) There is no upper limit on the number of partners. (4) Mutual rights are governed by the LLP agreement, and where it is silent, by the First Schedule to the Act.","options":["One","Two","Three","Four"],"answer":2,"explanation":"(1), (3) and (4) are correct. (2) is wrong: a partner is not personally liable for another partner's wrongful act or misconduct, though he is liable for his own.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-173","question":"A minor admitted to the benefits of a partnership attains majority and does not give any public notice within six months. What is his position?","options":["He automatically ceases to be connected with the firm at all","He is liable only from the date of attaining majority","He may never become a partner in that firm thereafter","He becomes a partner, liable from his date of admission"],"answer":3,"explanation":"Section 30: if he fails to give public notice of his election within six months, he becomes a partner and is personally liable for all acts of the firm since he was admitted to its benefits.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-174","question":"In a partnership at will, one partner wants to end the firm. What must he do?","options":["Give written notice to all the other partners","Obtain the written consent of all the partners","Apply to the court for dissolution in every case","Wait until the firm makes a loss in its accounts"],"answer":0,"explanation":"Section 43: a partnership at will may be dissolved by any partner giving notice in writing to all the other partners; it is dissolved from the date mentioned in the notice or the date of communication.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-175","question":"Company A holds 30% of Company B's shares but has the power to appoint and remove all of B's directors. Is B a subsidiary of A?","options":["No, because A holds less than half the shares","Yes, because A controls the composition of B's board","Only if A also holds preference shares in B","Only if B's articles expressly name A as its holding company"],"answer":1,"explanation":"Under Section 2(87), control of the composition of the board of directors is enough to make a company a subsidiary, regardless of shareholding.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-176","question":"Copyright protects:","options":["Inventions with novelty and industrial application","Brand names and logos used in trade","The geographical origin of goods","Original literary, artistic and musical works"],"answer":3,"explanation":"Copyright protects the original expression of a work. Inventions are protected by patents, brand identifiers by trademarks and origin-linked goods by geographical indications.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-177","question":"A new process for making a medicine is protected by a:","options":["Trademark","Patent","Copyright","Design registration"],"answer":1,"explanation":"A patent protects an invention, a product or a process, that is new, involves an inventive step and is capable of industrial application.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-178","question":"A distinctive logo that identifies a company's goods in the market is protected as a:","options":["Patent","Geographical indication","Trademark","Copyright only"],"answer":2,"explanation":"A trademark is a mark capable of distinguishing one person's goods or services from another's, such as a logo, name or label.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-179","question":"A writes a bestselling novel about a school for young wizards. B writes his own novel on the same broad idea, with entirely different characters, plot and text. Has B infringed A's copyright?","options":["No: copyright protects the expression, not the idea","Yes, because the central idea and theme were copied from A","Only if B's book sells more copies than A's","Only if B fails to acknowledge A as inspiration"],"answer":0,"explanation":"Copyright does not protect ideas, themes or plots in the abstract, only their particular expression. Substantial copying of expression would be needed for infringement.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-180","question":"Under Section 3(d) of the Patents Act, a new form of a known substance is:","options":["Patentable if it is cheaper to manufacture","Patentable for ten years instead of twenty","Patentable if it is already patented in a WTO member country","Not patentable unless it shows enhanced efficacy"],"answer":3,"explanation":"Section 3(d), applied in the Novartis case, excludes mere new forms of known substances unless they differ significantly in efficacy, to prevent 'evergreening' of patents.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-181","question":"'Darjeeling Tea' is protected in India as a:","options":["Patent on a process","Geographical indication","Copyright in the brand name","Registered industrial design"],"answer":1,"explanation":"A geographical indication identifies goods as originating in a territory where a given quality or reputation is essentially due to that origin.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-182","question":"Which set correctly states the three tests an invention must pass to be patentable in India?","options":["Novelty, aesthetic appeal and commercial success","Inventive step, a registered trademark and novelty","Novelty, inventive step and industrial applicability","Industrial applicability, public demand and originality of expression"],"answer":2,"explanation":"An invention must be new, involve an inventive step (not obvious to a skilled person) and be capable of industrial application. Aesthetic appeal relates to designs and originality of expression to copyright.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-183","question":"Under the Consumer Protection Act, 2019, who is NOT a consumer?","options":["A trader who buys mobile phones to resell them","A person who buys a phone online for personal use","A person who hires a taxi for a family trip","A self-employed tailor who buys a sewing machine to earn his livelihood"],"answer":0,"explanation":"A person who buys goods for resale or for a commercial purpose is excluded; buying for self-employment to earn a livelihood is allowed, and online purchases are covered.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-184","question":"Under the Consumer Protection Act, 2019, a product liability action can be brought against:","options":["Only the manufacturer who made the defective product","Only the retailer who actually sold the product to the consumer","Only the advertiser or celebrity who endorsed it","Manufacturer, service provider or seller, as applicable"],"answer":3,"explanation":"The 2019 Act introduced product liability, making manufacturers, service providers and sellers liable for harm caused by defective products or deficient services, under specified conditions.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-185","question":"Under the Consumer Protection Act, 2019, where can a consumer file a complaint?","options":["Only where the seller has its head office","Also where the complainant resides or works for gain","Only before the National Commission in New Delhi, as an appeal","Only where the goods were manufactured"],"answer":1,"explanation":"The 2019 Act allows a complaint to be filed where the complainant resides or personally works for gain, in addition to the opposite party's location or where the cause of action arose; it also permits e-filing.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-186","question":"Under the Consumer Protection Act, 2019, the pecuniary jurisdiction of the commissions is based on:","options":["The compensation the consumer claims","The complainant's annual income level","The value of consideration paid for the goods or services","The number of complainants joining the complaint as a class"],"answer":2,"explanation":"The 2019 Act shifted the test from compensation claimed to the value of consideration paid for the goods or services, which prevents forum shopping by inflating claims.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-187","question":"Which body, created by the Consumer Protection Act, 2019, can order recall of unsafe goods, penalise endorsers of misleading advertisements and start class actions?","options":["Central Consumer Protection Authority","National Consumer Disputes Redressal Commission","Competition Commission of India","Bureau of Indian Standards"],"answer":0,"explanation":"The CCPA is a regulator that protects consumers as a class; the commissions decide individual disputes.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-188","question":"A Maharashtra trader makes intra-state taxable supplies of ₹20,00,000 at 18% (assume). Its intra-state purchases of ₹12,00,000 carried 18% GST, but ₹1,00,000 of these purchases was food for a staff party (blocked credit). There are no other items. How much GST does it pay in cash?","options":["₹1,44,000","₹1,62,000","₹1,80,000","₹3,60,000"],"answer":1,"explanation":"Output tax = 3,60,000. Total input GST = 2,16,000, of which 18,000 on the staff food is blocked; eligible ITC = 1,98,000. Cash = 3,60,000 − 1,98,000 = ₹1,62,000. Claiming the blocked credit gives ₹1,44,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-189","question":"A Delhi company's output tax this month is CGST ₹50,000 and SGST ₹50,000. It also received legal services of ₹1,00,000 under reverse charge at 18% (assume), intra-state. Its credit ledger already holds CGST ₹70,000 and SGST ₹70,000. What is the minimum cash it must pay this month?","options":["Nil","₹1,18,000","₹30,000","₹18,000"],"answer":3,"explanation":"Reverse-charge tax (CGST 9,000 + SGST 9,000 = ₹18,000) must be paid in cash. The forward-charge output of ₹1,00,000 can be fully met from the existing credit. The ₹18,000 then becomes available as ITC.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-190","question":"A trader bought goods for ₹5,00,000 plus GST of ₹90,000 and claimed the full input tax credit. Goods costing ₹1,00,000 are later destroyed in a fire. What must he do about the credit?","options":["Reverse ₹18,000","Reverse ₹90,000","Nothing","Reverse ₹9,000"],"answer":0,"explanation":"Credit is blocked on goods lost, stolen or destroyed, so the credit on the destroyed goods (18% of 1,00,000 = ₹18,000) must be reversed.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-191","question":"An individual has salary income of ₹3,00,000, non-speculative business income of ₹4,00,000, a speculation business loss of ₹60,000, a short-term capital loss of ₹30,000 and a long-term capital gain of ₹50,000. What is the gross total income?","options":["₹6,60,000","₹7,50,000","₹7,20,000","₹6,90,000"],"answer":2,"explanation":"The short-term loss can be set off against the long-term gain: 50,000 − 30,000 = 20,000. A speculation loss can be set off only against speculation income, so it is carried forward. GTI = 3,00,000 + 4,00,000 + 20,000 = ₹7,20,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-192","question":"Assume a deduction for specified savings capped at ₹1,50,000. An individual pays provident fund ₹90,000, life insurance premium ₹40,000, children's tuition fees ₹30,000 and home-loan principal ₹50,000, all eligible. What is the deduction?","options":["₹2,10,000","₹1,50,000","₹1,60,000","₹1,20,000"],"answer":1,"explanation":"Eligible payments total ₹2,10,000, but the deduction is capped at ₹1,50,000.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-193","question":"An individual's total tax liability for the year is ₹1,20,000. Tax of ₹80,000 was deducted at source and ₹30,000 was paid as advance tax. Ignoring interest, how much self-assessment tax is payable?","options":["₹40,000","₹90,000","₹1,10,000","₹10,000"],"answer":3,"explanation":"TDS and advance tax are credited against the final liability: 1,20,000 − 80,000 − 30,000 = ₹10,000.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-194","question":"A 17-year-old falsely tells a lender he is 19 and borrows ₹50,000. Which is correct?","options":["Void, and the minor is not estopped from pleading minority","The minor is bound because he lied about his age","The agreement becomes valid if he ratifies it at 18","The lender can sue the minor's parents on the contract instead"],"answer":0,"explanation":"An agreement with a minor is void, and the rule of estoppel does not apply against a minor, so he can plead minority despite his misstatement. A void agreement cannot be ratified, and parents are not liable on it.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-195","question":"A famous singer refuses to perform at a concert as contracted. What remedy will a court usually give the organiser?","options":["Specific performance compelling the singer to perform as agreed","An order forcing the performance plus damages","Damages, as personal service is not specifically enforced","Nothing, since performance was purely personal"],"answer":2,"explanation":"Courts do not compel personal performance; the organiser gets damages (and, in suitable cases, an injunction restraining the singer from performing elsewhere in breach of a negative covenant).","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-196","question":"A lends his car to B free of charge for a month. After a week, A needs it back. What is the position?","options":["A must wait until the agreed month ends","A can demand it only if B misuses the car","A cannot ask for it, as the bailment is for a fixed term","A may recall it early but must indemnify B for net loss"],"answer":3,"explanation":"Section 159: a lender in a gratuitous bailment may require return at any time, even before the agreed time, but must indemnify the bailee if the bailee, acting on the loan, suffers loss exceeding the benefit derived.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-197","question":"A government hospital provides treatment entirely free of charge to all patients. A patient alleges negligent treatment. Can he file a complaint under the Consumer Protection Act?","options":["Yes, it is a deficiency in service and the hospital is liable","No: a service rendered wholly free is not a 'service' under the Act","Only against the treating doctor in his personal capacity","Only directly before the National Commission as a class action suit"],"answer":1,"explanation":"'Service' under the Act excludes services rendered free of charge. Where a hospital charges some patients, its free services can also be covered, but a wholly free service is not (Indian Medical Association v V.P. Shantha).","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-198","question":"For a published literary work, how long does copyright generally last in India?","options":["The author's lifetime plus 60 years","50 years from publication","20 years from creation","The author's lifetime plus 70 years"],"answer":0,"explanation":"Under the Copyright Act, 1957, copyright in a published literary, dramatic, musical or artistic work lasts for the author's lifetime plus 60 years.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-199","question":"How many of these statements are correct? (1) An action for infringement requires a registered trademark. (2) Passing off can protect the goodwill of even an unregistered mark. (3) A trademark registration is valid for ten years and can be renewed for further periods of ten years. (4) A patent protects an invention for a limited term, after which anyone may use it.","options":["One","Two","Three","Four"],"answer":3,"explanation":"All four are correct. Infringement needs a registered mark, passing off protects unregistered goodwill, registration under the Trade Marks Act lasts ten years and is renewable indefinitely, and a patent expires after its term.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-200","question":"Which of these can be paid using the balance in a taxpayer's GST electronic credit ledger?","options":["Interest for delayed payment of tax","Late fee for filing a return late","Tax payable under reverse charge","Output tax under forward charge"],"answer":3,"explanation":"Section 49(4) allows the credit ledger to be used only for output tax, and reverse-charge tax is excluded from that. Interest, late fees and penalties must be paid from the cash ledger.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-201","question":"A consultant receives an advance of ₹2,00,000 on 5 June, completes the service on 10 June and issues the invoice on 20 June, within the time allowed. Under GST, what is the time of supply for the advance?","options":["10 June","5 June","20 June","30 June"],"answer":1,"explanation":"For services, when the invoice is issued within the prescribed period, the time of supply is the earlier of the invoice date and the date payment is received. The advance came first, so tax on it is due with reference to 5 June.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-202","question":"A service is completed on 1 May. The invoice should have been issued within 30 days but is issued only on 15 June, and payment is received on 20 June. What is the time of supply under GST?","options":["15 June","20 June","1 May","31 May"],"answer":2,"explanation":"When the invoice is not issued within the prescribed period, the time of supply is the earlier of the date of provision of service and the date of receipt of payment. Provision on 1 May comes first. A late invoice cannot postpone the tax point.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-203","question":"A company receives a service taxable under reverse charge. The supplier's invoice is dated 1 March; the company pays the supplier on 15 May. Under GST, the time of supply is the earlier of the payment date and the date immediately after 60 days from the invoice date. Which date is it?","options":["15 May","1 March","1 May","1 June"],"answer":2,"explanation":"Sixty days from 1 March runs to 30 April, so the date immediately after is 1 May. That is earlier than the 15 May payment, so the time of supply is 1 May and the company must pay the reverse-charge tax with reference to it, even though it has not yet paid the supplier.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-204","question":"A company supplies goods to a related company that makes mainly exempt supplies and so is not eligible for full input tax credit. The invoice price is lower than the open market value of such goods. How is the taxable value determined?","options":["The invoice price, since it was agreed between the parties","Cost of production plus 10%, in every case","The open market value of the supply","Nil, as supplies between related persons are not supplies"],"answer":2,"explanation":"Between related persons the transaction value is not accepted where price is influenced by the relationship; the open market value is used (falling back to like goods, then cost plus 10%, only if it is not available). The invoice value is accepted as open market value only when the recipient is eligible for full input tax credit.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-205","question":"A customs broker charges a client ₹50,000 as its fee. It also pays ₹2,00,000 of customs duty on the client's behalf as a pure agent (shown separately and recovered at actual) and spends ₹5,000 on its own staff travel to do the job, which it also recovers from the client. What is the taxable value of the broker's service?","options":["₹2,55,000","₹50,000","₹55,000","₹2,50,000"],"answer":2,"explanation":"Amounts paid as a pure agent on the client's behalf and recovered at actual are excluded from value, so the duty is out. The broker's own travel costs are incurred for its own service and are part of the value: 50,000 + 5,000 = ₹55,000.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-206","question":"Goods have a list price of ₹1,00,000. The invoice shows a 2% discount on list price given at the time of supply, and separately charges packing of ₹3,000. Freight of ₹5,000, which was the supplier's liability under the contract, is paid by the buyer directly to the transporter and not shown on the invoice. GST is charged separately. What is the taxable value?","options":["₹1,01,000","₹1,08,000","₹1,06,000","₹1,03,000"],"answer":2,"explanation":"Start at 1,00,000 − 2% = ₹98,000 (an invoice discount at the time of supply is excluded). Add packing ₹3,000 and the ₹5,000 the buyer paid on the supplier's behalf, which forms part of the consideration: ₹1,06,000. ₹1,01,000 misses the freight; ₹1,08,000 ignores the discount.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-207","question":"A business's input tax credit for a month is ₹3,00,000: ₹60,000 on inputs used only for taxable supplies, ₹40,000 used only for exempt supplies, ₹20,000 blocked (for personal consumption), and ₹1,80,000 on common inputs. Turnover for the month is ₹90 lakh taxable and ₹30 lakh exempt. How much credit can it keep?","options":["₹1,95,000","₹2,25,000","₹2,40,000","₹1,80,000"],"answer":0,"explanation":"Credit used only for taxable supplies is kept in full (₹60,000); exempt-only and blocked credit go out entirely. Common credit is apportioned by turnover: 1,80,000 × 90/120 = ₹1,35,000. Total ₹1,95,000. ₹2,25,000 apportions the whole ₹3,00,000; ₹2,40,000 does not apportion the common credit.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-208","question":"How many of these are conditions for a registered person to take input tax credit? (1) It holds a tax invoice or other prescribed document. (2) It has received the goods or services. (3) The tax charged has actually been paid to the government. (4) It has furnished its return. (5) It has already paid the supplier the full value before taking credit.","options":["Three","Five","Two","Four"],"answer":3,"explanation":"(1) to (4) are statutory conditions. (5) is not: credit can be taken before paying the supplier; it must only be reversed if the value and tax are not paid within 180 days of the invoice.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-209","question":"A machine is bought under one invoice but delivered in three lots in July, August and September. When can the buyer take input tax credit for it?","options":["In July, on receipt of the first lot","One-third in each of the three months of delivery","When the invoice is paid in full","In September, on receipt of the last lot"],"answer":3,"explanation":"Where goods under one invoice arrive in lots or instalments, credit is available only on receipt of the last lot or instalment.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-210","question":"For a manufacturer, input tax credit is available on which of these? (1) A truck used to transport its goods (2) Food and beverages for an office party it is not legally required to provide (3) Construction of its factory building (4) A works contract for installing plant and machinery","options":["(1), (3) and (4) only","(2) and (4) only","(1) and (2) only","(1) and (4) only"],"answer":3,"explanation":"Motor vehicles used to transport goods are outside the block. Food and beverages (unless provided under a legal obligation) and construction of immovable property such as a factory building are blocked. Works contracts for plant and machinery are allowed, since plant and machinery excludes buildings and civil structures.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-211","question":"Under the TDS system, who deducts the tax and deposits it with the government?","options":["The person making the payment (the deductor)","The person receiving the payment (the deductee)","The bank through which payment is made","The tax department, from the deductee's account"],"answer":0,"explanation":"The payer deducts tax at the time of credit or payment and deposits it; the payee gets credit for it against his own tax liability.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-212","question":"Under tax collected at source (TCS), who collects the tax?","options":["The buyer, from the seller, when paying the price","The employer, from each employee's salary every month","The tax department, from both parties at year end","The seller, from the buyer, in specified transactions"],"answer":3,"explanation":"TCS is the mirror image of TDS: the seller (or receiver of money in specified cases) collects tax from the buyer along with the price and deposits it, and the buyer gets credit for it.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-213","question":"A company pays a professional ₹3,00,000 as fees plus GST of ₹54,000 shown separately on the invoice. Assume TDS of 10% applies and that, where GST is shown separately, TDS is computed on the amount excluding GST. How much tax is deducted?","options":["₹30,000","₹35,400","₹27,000","₹5,400"],"answer":0,"explanation":"TDS is on the fee alone: 10% × 3,00,000 = ₹30,000. ₹35,400 wrongly includes the GST; ₹5,400 applies the rate to the GST only.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-214","question":"Assume listed equity shares held for more than 12 months give long-term capital gains, taxed at 12.5% on the gain exceeding ₹1,25,000 a year, without indexation. Shares bought for ₹6,00,000 two years ago are sold for ₹10,25,000, with brokerage of ₹5,000 on the sale. There are no other gains. What is the tax (ignoring cess and surcharge)?","options":["₹36,875","₹52,500","₹37,500","₹59,000"],"answer":0,"explanation":"Gain = 10,25,000 − 5,000 − 6,00,000 = ₹4,20,000. Taxable = 4,20,000 − 1,25,000 = ₹2,95,000; tax at 12.5% = ₹36,875. ₹52,500 ignores the ₹1,25,000 exemption; ₹37,500 ignores the brokerage; ₹59,000 uses 20%.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-215","question":"An individual has a long-term gain of ₹80 lakh on selling a residential house and claims exemption by investing ₹50 lakh in a new house. Assume the rule that if the new house is sold within three years of purchase, its cost is reduced by the exemption claimed when computing the gain. Two years later he sells the new house for ₹60 lakh. What is the short-term capital gain?","options":["₹10 lakh","Nil","₹50 lakh","₹60 lakh"],"answer":3,"explanation":"The ₹50 lakh exemption is withdrawn by reducing the new house's cost: 50 − 50 = nil. Short-term gain = 60 − 0 = ₹60 lakh. ₹10 lakh ignores the withdrawal of the exemption.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-216","question":"Assume listed shares are long-term if held for more than 12 months, and land and unlisted shares if held for more than 24 months. Which classification is correct for: (a) listed shares held 14 months, (b) land held 20 months, (c) unlisted shares held 30 months?","options":["(a) long-term, (b) short-term, (c) long-term","(a) short-term, (b) short-term, (c) long-term","(a) long-term, (b) long-term, (c) long-term","(a) long-term, (b) short-term, (c) short-term"],"answer":0,"explanation":"(a) 14 months exceeds 12, so long-term; (b) 20 months does not exceed 24, so short-term; (c) 30 months exceeds 24, so long-term.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-217","question":"In the same year an individual has short-term capital gain ₹2,00,000, long-term capital gain ₹3,00,000, short-term capital loss ₹3,00,000 and long-term capital loss ₹1,00,000. A short-term loss can be set off against any capital gain; a long-term loss only against long-term gain. What capital gain remains taxable?","options":["₹2,00,000","₹1,00,000","₹5,00,000","Nil"],"answer":1,"explanation":"Long-term loss against long-term gain: 3,00,000 − 1,00,000 = ₹2,00,000. Short-term loss ₹3,00,000 wipes out short-term gain ₹2,00,000 and the remaining ₹1,00,000 reduces long-term gain to ₹1,00,000. ₹2,00,000 wrongly confines the short-term loss to short-term gains and carries the excess forward.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-218","question":"Under GST, a manufacturer's capital goods carry input tax credit of ₹6,00,000 and are used for both taxable and exempt supplies. The common credit on capital goods is spread over a useful life of 5 years (60 months). In a month where exempt turnover is 25% of total turnover, how much of that month's credit is attributable to exempt supplies?","options":["₹10,000","₹1,50,000","₹7,500","₹2,500"],"answer":3,"explanation":"Monthly credit = 6,00,000 ÷ 60 = ₹10,000; the exempt share is 25% × 10,000 = ₹2,500 (and ₹7,500 is kept). ₹1,50,000 applies 25% to the whole credit at once.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-219","question":"A supplier removes goods for delivery on 10 August but issues the invoice only on 14 August; payment is received on 1 September. The invoice was required to be issued before or at the time of removal. What is the time of supply under GST?","options":["10 August","14 August","1 September","31 August"],"answer":0,"explanation":"For goods, the time of supply is the earlier of the invoice date (or the last date on which it should have been issued) and the payment date. The invoice was due by removal on 10 August, so issuing it late does not shift the time of supply.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-220","question":"An Indian company buys consultancy services for its business from a firm in the US that has no presence in India. How is GST paid?","options":["The US firm must register in India and charge IGST","The Indian company pays IGST under reverse charge","No GST, as the supplier is outside India","The Indian company pays CGST and SGST under forward charge"],"answer":1,"explanation":"Import of services is an inter-state supply, and when the supplier is outside India the recipient pays IGST under reverse charge. It can then claim that tax as input tax credit if used for business.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-221","question":"Assume that any business expense paid in cash to one person in one day above ₹10,000 is disallowed. A business pays a supplier in cash ₹9,000 on 3 May and ₹8,000 on 4 May (separate bills), and pays a contractor ₹15,000 in cash on 10 May. How much is disallowed?","options":["₹32,000","₹15,000","₹17,000","Nil"],"answer":1,"explanation":"The limit is per person per day. The supplier was paid ₹9,000 and ₹8,000 on different days, each within the limit. The contractor's ₹15,000 in one day exceeds it, so the whole ₹15,000 is disallowed. ₹17,000 wrongly adds the two supplier payments.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-222","question":"Assume a minor child's income is clubbed with the income of the parent whose income is higher, with an exemption of ₹1,500 a year per child, and that income from the child's own skill or talent is not clubbed. A minor earns ₹20,000 interest on a fixed deposit gifted by his father and ₹30,000 from his own singing performances. The father's income is higher. How much is clubbed in the father's hands?","options":["₹48,500","₹18,500","₹50,000","₹20,000"],"answer":1,"explanation":"Income from the minor's own talent (₹30,000) is excluded. The interest is clubbed after the ₹1,500 exemption: 20,000 − 1,500 = ₹18,500. ₹48,500 also clubs the performance income; ₹20,000 forgets the exemption.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-223","question":"Under GST, a registered supplier who has charged tax on goods that the buyer later returns issues which document to reduce the tax liability?","options":["A debit note","A bill of supply","A delivery challan","A credit note"],"answer":3,"explanation":"A credit note reduces the value and tax on an earlier invoice, for example on returns or where the taxable value or tax charged was too high. A debit note increases them.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-224","question":"A company transfers goods from its Maharashtra unit to its own branch in Karnataka, separately registered and eligible for full input tax credit. The invoice shows ₹80,000; goods of that kind sell in the open market for ₹1,00,000. What is the taxable value?","options":["₹1,00,000","₹80,000","Nil, as there is no consideration","₹90,000"],"answer":1,"explanation":"Separately registered establishments of the same person are distinct persons, so the transfer is a supply even without consideration. Where the recipient is eligible for full credit, the value declared in the invoice is deemed to be the open market value: ₹80,000. The 90%-of-resale-price option applies only to goods meant for further supply as such, and only at the supplier's option.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-225","question":"Under the Companies Act, 2013, who declares an interim dividend?","options":["The board of directors","The shareholders at the annual general meeting","The auditors","The Registrar of Companies"],"answer":0,"explanation":"Interim dividend is declared by the board between two AGMs. Final dividend is declared by the shareholders at the AGM on the board's recommendation.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-226","question":"Under the Insolvency and Bankruptcy Code, which authority admits an application to start the corporate insolvency resolution process against a company?","options":["The Debts Recovery Tribunal of the area","The Registrar of Companies","The National Company Law Tribunal","The High Court of the state"],"answer":2,"explanation":"The NCLT is the adjudicating authority for companies and LLPs. The Debts Recovery Tribunal handles insolvency of individuals and partnership firms.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-227","question":"A company's board recommends a final dividend of 15%. At the AGM, some shareholders propose raising it to 20%. What can the general meeting do?","options":["Declare 20% by an ordinary resolution of members","Declare 20% by a special resolution of members","Only accept or reject 15%; it cannot vary the rate","Declare 15% or less, but not more than recommended"],"answer":3,"explanation":"Shareholders declare the final dividend, but they cannot declare more than the board recommends. They may approve the recommended rate or a lower one.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-228","question":"How many of these statements about unpaid dividend are correct? (1) A declared dividend must be paid or the warrant posted within 30 days of declaration. (2) Dividend not paid or claimed within that period is transferred to a special Unpaid Dividend Account opened by the company in a scheduled bank. (3) Amounts lying unclaimed in that account for seven years are transferred to the Investor Education and Protection Fund. (4) Once transferred to the IEPF, the shareholder loses all right to claim the amount.","options":["Three","Two","Four","One"],"answer":0,"explanation":"(1), (2) and (3) are correct. (4) is wrong: a shareholder whose dividend (or shares) has gone to the IEPF can still claim a refund from the IEPF Authority by following the prescribed procedure.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-229","question":"A company paid dividends of 12%, 10% and 8% in its three preceding financial years. In the current year it has incurred a loss up to the end of the quarter immediately before the board meets to declare an interim dividend. What is the maximum rate of interim dividend it can declare?","options":["12%","10%","8%","Nil, as no dividend can be declared in a loss year"],"answer":1,"explanation":"Where a company has incurred a loss in the current year up to the quarter before the interim declaration, the interim dividend cannot exceed the average rate of the three preceding years: (12 + 10 + 8) ÷ 3 = 10%.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-230","question":"A company's current-year profit before depreciation is ₹50 lakh and depreciation for the year is ₹10 lakh. It carries forward losses of ₹15 lakh from earlier years. Ignoring transfers to reserves, what is the maximum dividend it can declare out of the current year's profits?","options":["₹40 lakh","₹35 lakh","₹25 lakh","₹50 lakh"],"answer":2,"explanation":"Dividend from current profits can be paid only after providing depreciation and setting off carried-over losses: 50 − 10 − 15 = ₹25 lakh. ₹40 lakh ignores the past losses; ₹35 lakh ignores depreciation.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-231","question":"A company issues equity shares of ₹10 each to the public at ₹9. What is the legal position under the Companies Act, 2013?","options":["Valid if approved by a special resolution of the members","Void: shares cannot be issued at a discount, save sweat equity and debt conversion","Valid if the discount is under 10% of the face value and disclosed in the prospectus","Valid, but the discount must be written off within five years"],"answer":1,"explanation":"The Act prohibits issuing shares at a discount; such an issue is void and attracts penalties. Sweat equity shares (and shares issued on conversion of debt under a statutory or RBI-approved scheme) are the exceptions.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-232","question":"A company's authorised capital is ₹10 crore and issued capital ₹6 crore. Shares of ₹5 crore face value have been subscribed, with ₹8 per ₹10 share called up. Calls in arrears are ₹20 lakh. What is the paid-up capital?","options":["₹3.8 crore","₹4 crore","₹5 crore","₹4.8 crore"],"answer":0,"explanation":"Called-up capital = 5 crore × 8/10 = ₹4 crore. Paid-up capital is what shareholders have actually paid: 4 crore − 20 lakh = ₹3.8 crore. ₹4 crore is the called-up figure; ₹5 crore is subscribed capital.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-233","question":"Which of these alterations of share capital needs confirmation by the Tribunal? (1) Subdividing shares of ₹10 into shares of ₹1 (2) Reducing share capital by returning surplus capital to shareholders (3) Increasing authorised capital (4) Consolidating shares of ₹1 into shares of ₹10 without changing voting rights","options":["(1) and (2) only","(2) only","(2) and (3) only","All four"],"answer":1,"explanation":"Reduction of share capital needs a special resolution and confirmation by the Tribunal, to protect creditors. Increasing authorised capital, subdivision and consolidation (without change in voting percentages) need only the authority in the articles and an ordinary resolution.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-234","question":"A listed company appoints an audit firm as its statutory auditor. Under the rotation rules, which is correct?","options":["One term of five years, then a ten-year cooling-off period","Reappointment every year without any upper limit","Three terms of five consecutive years each","At most two five-year terms, then a five-year cooling-off"],"answer":3,"explanation":"For listed and other prescribed companies, an individual auditor can serve one term of five consecutive years and an audit firm two such terms. After that there is a five-year cooling-off period before reappointment.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-235","question":"Which of these services may a company's statutory auditor provide to it, with the approval of the board or audit committee?","options":["Internal audit","Book-keeping and maintaining accounting records","Preparing and filing the company's tax returns","Investment advisory services"],"answer":2,"explanation":"The Act bars the statutory auditor from providing services such as accounting and book-keeping, internal audit, design of financial information systems, actuarial, investment advisory, investment banking, outsourced financial and management services. Taxation services are not on that list.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-236","question":"The shareholders of a company want to remove its statutory auditor before the end of his five-year term. What is required?","options":["An ordinary resolution at any general meeting, with notice to him","A board resolution passed with the audit committee's consent","An application to the Tribunal by members holding 10% of shares","Special resolution with prior Central Government approval and a hearing"],"answer":1,"explanation":"Removing an auditor before his term ends needs prior Central Government approval and a special resolution, and the auditor must be given a reasonable opportunity of being heard. (Separately, the Tribunal can order a change of auditor for fraud.)","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-237","question":"Who appoints the first auditor of a newly registered company (other than a government company)?","options":["The shareholders at the first AGM","The Registrar of Companies on incorporation","The Comptroller and Auditor-General","The board, within 30 days of registration"],"answer":3,"explanation":"The board appoints the first auditor within 30 days of registration. If it fails, the members appoint one at an extraordinary general meeting within 90 days. The first auditor holds office until the end of the first AGM.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-238","question":"A company falls under the CSR provisions. Its net profits (computed as required) for the three immediately preceding years were ₹30 crore, ₹45 crore and ₹15 crore. Assume it must spend 2% of the average net profit of those years. What is its CSR obligation?","options":["₹90 lakh","₹1.8 crore","₹60 lakh","₹30 lakh"],"answer":2,"explanation":"Average net profit = (30 + 45 + 15) ÷ 3 = ₹30 crore; 2% = ₹60 lakh. ₹90 lakh uses only the highest year; ₹1.8 crore uses the total instead of the average; ₹30 lakh uses only the latest year.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-239","question":"A company covered by CSR made net profits of ₹40 crore and ₹30 crore in two of its three immediately preceding years and a loss of ₹10 crore in the other. Assume the obligation is 2% of the average net profit of the three years. What is the obligation?","options":["₹46.67 lakh","₹70 lakh","₹1.2 crore","₹40 lakh"],"answer":3,"explanation":"The loss year is included in the average: (40 + 30 − 10) ÷ 3 = ₹20 crore; 2% = ₹40 lakh. Ignoring the loss but dividing by three gives ₹46.67 lakh; averaging only the two profit years gives ₹70 lakh.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-240","question":"How many of these statements about unspent CSR amounts are correct? (1) An unspent amount that does not relate to an ongoing project must be transferred to a fund specified in Schedule VII within six months of the end of the financial year. (2) An unspent amount relating to an ongoing project must be moved to a special Unspent CSR Account within 30 days of the end of the year. (3) Money in the Unspent CSR Account must be spent within three financial years, failing which it goes to a Schedule VII fund. (4) A company may simply explain the shortfall in the board's report and carry it forward indefinitely.","options":["Two","Four","One","Three"],"answer":3,"explanation":"(1), (2) and (3) describe the current scheme. (4) is wrong: since the amendments, a shortfall cannot just be explained away; it must be transferred as described, with penalties for default.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-241","question":"Which of these would NOT count as CSR expenditure?","options":["Building toilets in government schools in a backward district","A contribution to the PM's National Relief Fund under Schedule VII","A medical scheme only for the company's own employees and families","Funding a skill-training programme for unemployed rural youth"],"answer":2,"explanation":"Activities that benefit only the company's employees and their families are excluded from CSR. Schools' sanitation, skill training and contributions to specified funds are recognised CSR activities.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-242","question":"In a liquidation under the IBC, arrange these claims in the order of payment from highest priority: (a) workmen's dues for the 24 months before liquidation, ranking equally with secured creditors who have relinquished their security; (b) insolvency resolution process and liquidation costs; (c) unsecured financial creditors; (d) equity shareholders; (e) wages and unpaid dues of employees other than workmen for 12 months.","options":["a, b, e, c, d","b, e, a, c, d","b, a, c, e, d","b, a, e, c, d"],"answer":3,"explanation":"The waterfall starts with process and liquidation costs, then workmen's dues (24 months) equally with secured creditors who relinquished security, then other employees' dues (12 months), then unsecured financial creditors; equity shareholders come last.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-243","question":"In a corporate insolvency, the committee of creditors has these voting shares: Bank A 40%, Bank B 25%, NBFC C 20%, Bank D 15%. Assume a resolution plan needs the approval of at least 66% of the voting share. Which group of assenting creditors is enough to approve it?","options":["A, B and D","A and B","B, C and D","A and C"],"answer":0,"explanation":"A + B + D = 80%, which clears 66%. A + B = 65% falls just short; B + C + D = 60% and A + C = 60% also fail.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-244","question":"Under the IBC, an operational creditor (such as a supplier) wants to start insolvency proceedings against a company that owes it money. What must it do first?","options":["Deliver a demand notice and wait the prescribed period for payment or dispute","File the application directly before the NCLT without any notice","Obtain the prior written consent of all financial creditors through the committee","Get a money decree from a civil court and then execute it"],"answer":0,"explanation":"An operational creditor must first deliver a demand notice (with a copy of the invoice). Only if the debtor neither pays nor points out a pre-existing dispute within the prescribed period can it apply to the NCLT. A financial creditor can apply directly.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-245","question":"Once the NCLT admits a corporate insolvency application and declares a moratorium, how many of these follow? (1) No suit or proceeding can be started or continued against the corporate debtor. (2) A secured creditor cannot enforce its security against the debtor's assets. (3) The supply of essential goods and services to the debtor cannot be terminated during the moratorium. (4) Creditors are barred from proceeding against a personal guarantor of the debtor.","options":["Two","Three","Four","One"],"answer":1,"explanation":"(1), (2) and (3) follow from the moratorium. (4) does not: the moratorium protects the corporate debtor, and creditors can still proceed against a personal guarantor, as the Supreme Court has confirmed.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-246","question":"Which statements comparing an LLP with a company are correct? (1) An LLP has no upper limit on the number of partners. (2) A private company needs at least two members (unless it is a one person company). (3) An LLP partner's liability is limited to his agreed contribution, except in case of fraud. (4) An LLP must be managed by a board of directors.","options":["(1), (2) and (3) only","(1) and (3) only","(2), (3) and (4) only","All four"],"answer":0,"explanation":"(1), (2) and (3) are correct. (4) is wrong: an LLP is managed by its partners under the LLP agreement, with designated partners responsible for compliance; it has no board of directors.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-247","question":"How many of these statements about a casual vacancy in the office of auditor of a non-government company are correct? (1) A vacancy for a reason other than resignation is filled by the board within 30 days. (2) If the vacancy arises from the auditor's resignation, the board's appointment must also be approved by the company at a general meeting within three months. (3) An auditor appointed in a casual vacancy holds office for a fresh term of five years. (4) A resigning auditor need not inform anyone other than the board.","options":["Two","Three","Four","One"],"answer":0,"explanation":"(1) and (2) are correct under Section 139(8). (3) is wrong: an auditor appointed in a casual vacancy holds office only until the conclusion of the next AGM. (4) is wrong: a resigning auditor must file a statement with the company and the Registrar giving the reasons.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-248","question":"X, a partner in an LLP, negligently gives wrong advice to a client, and the LLP is held liable for ₹50 lakh. The LLP's assets are only ₹30 lakh. Partner Y had nothing to do with the advice. Who is liable for the loss?","options":["X and Y jointly and severally, like partners in an ordinary firm","The LLP from its assets, and X personally for his own wrong; not Y","Only the LLP, up to ₹30 lakh; the rest is lost and no partner pays","Y and X equally, in proportion to their capital contributions"],"answer":1,"explanation":"The LLP is liable for a partner's wrongful act in the course of its business. A partner is not personally liable for another partner's wrongful acts, but remains personally liable for his own. So X bears the shortfall personally and Y does not.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-249","question":"A cheque given to pay a debt is dishonoured because there is not enough money in the drawer's account. Once the statutory conditions are met, what can the payee pursue?","options":["Both a criminal complaint for dishonour and a civil suit for the money","Only a civil suit for recovery of the amount of the cheque","Only a complaint to the banking ombudsman against the drawer's bank branch","Nothing, as dishonour is a matter between the drawer and his bank"],"answer":0,"explanation":"Dishonour of a cheque issued for a legally enforceable debt is a criminal offence once notice is given and payment is not made in time. The payee can also file a civil suit for the money; the two remedies run independently.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-250","question":"In contract law, the remedy 'quantum meruit' means:","options":["Specific performance of the whole contract","A fixed penalty agreed upon in the contract","Payment of a reasonable sum for work done","Cancellation of the contract with no payment"],"answer":2,"explanation":"Quantum meruit ('as much as earned') lets a party recover a reasonable amount for what he has actually done, for example when the other party prevents him from completing the work.","difficulty":"easy","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-251","question":"After issuing a cheque for an existing debt, the drawer tells his bank to stop payment, and the cheque is returned 'payment stopped by drawer' although the account had enough money. In a prosecution for dishonour, which is correct?","options":["Stopping payment is always a complete defence, as the account had funds","Stop-payment is no defence by itself; the offence can still be made out","Only dishonour for 'insufficient funds' is covered, so no offence arises","The bank alone is liable for not honouring a funded cheque"],"answer":1,"explanation":"Courts have held that a drawer cannot escape liability merely by stopping payment. If the cheque was for a legally enforceable debt and the drawer fails to pay after the statutory notice, the offence is made out; he may still rebut the presumption by showing there was no debt.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-252","question":"A borrower gives the lender a cheque as 'security' when taking a loan. He defaults when the loan falls due, and the lender presents the cheque, which is dishonoured. Can the dishonour provisions apply?","options":["Yes, if a legally enforceable debt existed when it was presented","No, a security cheque can never attract any liability for dishonour","Only if the cheque was post-dated by less than one month","Only if the borrower had also signed a separate promissory note"],"answer":0,"explanation":"The Supreme Court has held that a cheque given as security is not excluded. If the loan had become due and payable when the cheque was presented, the cheque represents an enforceable debt and its dishonour can attract liability.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-253","question":"How many of these statements about a prosecution for cheque dishonour are correct? (1) The court presumes that the holder received the cheque for the discharge of a debt or liability. (2) The accused can rebut the presumption on a preponderance of probabilities. (3) The complainant must first prove the debt beyond reasonable doubt before any presumption arises. (4) The cheque must have been issued for a legally enforceable debt or other liability.","options":["Two","Four","One","Three"],"answer":3,"explanation":"(1), (2) and (4) are correct. (3) is wrong: once the cheque and signature are admitted, the presumption arises in favour of the holder, and the burden shifts to the accused, who need only raise a probable defence.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-254","question":"A company's cheque is dishonoured. How many of these statements about who can be prosecuted are correct? (1) Persons in charge of and responsible for the conduct of the company's business when the offence was committed can be liable. (2) Every director, including an independent non-executive director, is automatically liable. (3) The company itself should be made an accused for its officers to be prosecuted. (4) A director who proves the offence was committed without his knowledge, or that he exercised due diligence, is not liable.","options":["Two","Four","One","Three"],"answer":3,"explanation":"(1), (3) and (4) reflect the law. (2) is wrong: liability is not automatic; the complaint must show the director was in charge of and responsible for the business, and non-executive directors are generally not liable merely because they hold office.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-255","question":"Assume a cheque is valid for three months from its date. A cheque dated 1 January is presented on 15 April and dishonoured for insufficient funds. Which is correct?","options":["No criminal liability arises, but the payee can still sue on the debt","The drawer is criminally liable, as the funds were insufficient","The payee can present it again within one more month to revive liability","The bank must pay the stale cheque out of its own funds"],"answer":0,"explanation":"The criminal provision applies only if the cheque is presented within its validity period. A cheque presented after it has gone stale does not attract it, though the debt itself can still be recovered through a civil suit.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-256","question":"A draws an order cheque in favour of B. B endorses it to C for value. The cheque is dishonoured, and C gives notice of dishonour only to A. None of the exceptions that excuse notice applies. On the instrument, whom can C hold liable?","options":["Only A, as B is discharged for want of notice","Both A and B, jointly and severally, on the cheque","Only B, as the immediate endorser to C","Neither, as notice to only one party is incomplete"],"answer":0,"explanation":"A holder must give notice of dishonour to every party he wants to hold liable. Notice to the drawer does not keep the endorser liable, so B is discharged on the instrument and C can proceed only against A.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-257","question":"A seller agrees to export goods to a foreign buyer and receives an advance of ₹2 lakh. Before shipment, the government bans export of those goods, and the ban was not foreseeable. What is the position?","options":["The contract becomes void and the seller must return the ₹2 lakh advance","The seller may keep the advance as compensation","The buyer can claim damages for non-delivery","The contract is only suspended until the ban is lifted, and the advance stays with the seller"],"answer":0,"explanation":"A later law that makes performance unlawful frustrates the contract, making it void. A person who received an advantage under a contract that becomes void must restore it, so the seller refunds the advance; neither side owes damages.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-258","question":"A agrees to sell his car to B. A knows the car was destroyed in a fire the day before, but B does not know and could not have known. What is B's remedy?","options":["B can compel A to deliver another car of the same model","No remedy, as the agreement is simply void for impossibility","B can only report A to the police for cheating","Void, but A must compensate B for loss from non-performance"],"answer":3,"explanation":"An agreement to do something impossible is void. But where the promisor knew of the impossibility and the promisee did not, the promisor must compensate the promisee for the loss caused.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-259","question":"A buyer contracts to buy 500 units at ₹200 each and pays a 20% advance. The seller fails to deliver. On the delivery date the market price is ₹230; the buyer delays and buys a week later at ₹250. How much can the buyer recover from the seller in total?","options":["₹45,000","₹15,000","₹20,000","₹35,000"],"answer":3,"explanation":"Damages for non-delivery are the difference between the contract price and the market price on the date of breach: 500 × (230 − 200) = ₹15,000; the extra cost from delaying the purchase is the buyer's own loss. He also recovers his advance of 20% × 1,00,000 = ₹20,000. Total ₹35,000. Using ₹250 gives ₹45,000; forgetting the advance gives ₹15,000.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-260","question":"A owes B three debts: ₹10,000 due in January (now time-barred), ₹20,000 due in March and ₹15,000 due in May. A pays ₹15,000 without saying which debt it is for, and B does not appropriate it either. Under the Indian Contract Act, how is the payment applied?","options":["₹10,000 to the January debt and ₹5,000 to the March debt","₹15,000 to the May debt","₹15,000 to the March debt, as a time-barred debt cannot be paid","Proportionately across the three debts"],"answer":0,"explanation":"When neither party appropriates, the payment is applied to the debts in order of time, whether or not they are barred by limitation. So the January debt is cleared first and the balance goes towards the March debt.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-261","question":"In a contract where time is of the essence, the supplier delivers a week late and the buyer accepts the goods without saying anything. Later the buyer claims compensation for the delay. Which is correct?","options":["He can claim, as time was of the essence of the contract all along","He cannot, as he gave no notice of his claim on accepting late","He can reject the goods now and recover the full price","He can claim only if the contract had a penalty clause"],"answer":1,"explanation":"When time is essential, the promisee may avoid the contract on delay. If he instead accepts late performance, he cannot claim compensation for the delay unless he gives notice of that intention to the promisor at the time of acceptance.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-262","question":"A seller brings the agreed goods to the agreed place at the agreed time, but the buyer refuses to take delivery. What is the effect of this tender of performance?","options":["The seller must keep tendering the goods every day until accepted","The contract is automatically discharged with no remedy for either side","The seller is not liable for non-performance and keeps his rights","The seller must sell the goods at once and remit the proceeds to the buyer"],"answer":2,"explanation":"A proper offer to perform that is refused discharges the promisor from liability for non-performance, and he does not lose his rights under the contract, so he can claim damages from the buyer.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-263","question":"An indemnity-holder (promisee) is sued by a third party in a matter covered by the indemnity. Acting prudently and within his authority, he settles the case. Which can he recover from the indemnifier? (1) Damages he was compelled to pay (2) Costs of defending the suit (3) The sum paid under the compromise (4) Compensation for the time he personally spent, beyond legal costs","options":["(1) and (2) only","(1), (2) and (4) only","(1), (2) and (3) only","All four"],"answer":2,"explanation":"An indemnity-holder acting within the terms of the promise, prudently, can recover damages he was compelled to pay, costs he was compelled to pay in the suit, and sums paid under a reasonable compromise. There is no such statutory right to a fee for his own time.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-264","question":"A recipient takes input tax credit of ₹18,000 but has not paid the supplier when 180 days from the invoice have passed. It pays the supplier in full two months later. Which is correct?","options":["It loses the credit permanently after 180 days","It reverses the credit with interest, then re-takes it on paying","Nothing happens, as the supplier has already paid the tax to the government","The supplier must reverse its output tax on the invoice"],"answer":1,"explanation":"Credit must be reversed, with interest, if value and tax are not paid within 180 days of the invoice. On later payment the recipient is entitled to take the credit again.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-265","question":"A father bought land for ₹10 lakh years ago and died; his son inherited it and has now sold it for ₹60 lakh, paying ₹1 lakh of brokerage. Its fair market value when the son inherited it was ₹30 lakh. Assume the gain is long-term and taxed at 12.5% without indexation. What is the tax (ignoring cess and surcharge)?","options":["₹3.625 lakh","₹7.5 lakh","₹6.125 lakh","₹6.25 lakh"],"answer":2,"explanation":"For an inherited asset, the cost is the previous owner's cost (₹10 lakh), and his holding period counts too. Gain = 60 − 1 − 10 = ₹49 lakh; tax = 12.5% × 49 = ₹6.125 lakh. Using the value on inheritance gives ₹3.625 lakh; ignoring the brokerage gives ₹6.25 lakh.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-266","question":"An investor bought 1,000 shares at ₹300 each and later received 1,000 bonus shares (1 : 1). She now sells the 1,000 bonus shares at ₹500 each, ignoring expenses. Assume bonus shares have a cost of nil. What is the capital gain?","options":["₹3,50,000","₹5,00,000","₹2,00,000","₹3,00,000"],"answer":1,"explanation":"The bonus shares cost nothing, so the whole sale price of 1,000 × 500 = ₹5,00,000 is the gain; the original 1,000 shares keep their ₹300 cost. ₹3,50,000 wrongly averages the cost to ₹150 a share; ₹2,00,000 uses the original ₹300 cost.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-267","question":"A company's shareholders must approve a material related-party transaction by resolution. Who may NOT vote on that resolution?","options":["All the directors who also hold shares in the company","Members who are related parties to that particular transaction","All small members holding less than 1% of the paid-up share capital","The company's statutory auditors holding shares"],"answer":1,"explanation":"To prevent interested parties from approving their own deals, members who are related parties in the context of the transaction cannot vote on its approval. Other shareholders vote as usual.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-268","question":"How many of these statements about issuing further shares are correct? (1) A rights issue is offered to all existing shareholders, including preference shareholders, in proportion to their holdings. (2) The offer includes a right to renounce the shares in favour of another person only if the articles expressly provide for it. (3) A preferential issue to selected persons needs a special resolution. (4) Shares under an employee stock option scheme can be issued with only an ordinary resolution.","options":["Two","Four","Three","One"],"answer":3,"explanation":"Only (3) is correct. A rights issue under Section 62(1)(a) goes to equity shareholders only; the right to renounce is included unless the articles provide otherwise; and an employee stock option issue needs a special resolution.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-269","question":"Under the IBC, which of these cannot, merely in that capacity, apply to start a corporate insolvency resolution process against a company?","options":["A financial creditor such as a bank","An operational creditor such as a supplier","An equity shareholder of the company","The corporate debtor itself"],"answer":2,"explanation":"The Code allows a financial creditor, an operational creditor or the corporate debtor itself to apply. A shareholder is not a creditor and has no such right as a shareholder.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-270","question":"How many of these statements about who may submit a resolution plan under the IBC are correct? (1) A person whose loan account has been classified as a non-performing asset for the specified period is ineligible unless he clears the overdue amounts before submitting the plan. (2) An undischarged insolvent is ineligible. (3) A wilful defaulter may submit a plan if the committee of creditors agrees. (4) The resolution professional finally approves the plan.","options":["One","Three","Two","Four"],"answer":2,"explanation":"(1) and (2) are correct ineligibility rules. (3) is wrong: a wilful defaulter is ineligible regardless of what the committee wants. (4) is wrong: the committee of creditors approves the plan and the NCLT then approves it; the resolution professional only examines it and presents it.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-271","question":"A agrees to sell B 'a hundred tonnes of oil' at a stated price. Nothing in the agreement or the circumstances shows what kind of oil was meant. What is the status of the agreement?","options":["Valid, and B can choose any oil","Valid, and A can deliver any oil","Voidable at B's option","Void for uncertainty"],"answer":3,"explanation":"An agreement whose meaning is not certain, and cannot be made certain, is void. Had A been known to deal only in one kind of oil, the meaning could be made certain and the agreement would be valid.","difficulty":"moderate","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-272","question":"An order cheque payable to A is stolen. The thief forges A's endorsement and negotiates it to C, who takes it in good faith and for value. What is C's position?","options":["C is a holder in due course and can enforce it against the drawer","C can enforce it, but only after giving notice to A","C gets no title through a forged endorsement; A stays the owner","C and A share the right to the cheque equally"],"answer":2,"explanation":"A forged endorsement is a nullity, so nobody claiming through it, even in good faith and for value, gets title to an order instrument. A remains the owner and can recover it or its value. (A bearer cheque, which needs no endorsement, is treated differently.)","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement pattern"},
  {"id":"mgmt-tax-law-273","question":"A posts an offer to B on 1 March, which B receives on 4 March. On 5 March A posts a letter revoking the offer; it reaches B on 7 March. B posted his acceptance on 6 March, and it reaches A on 8 March. What is the legal position?","options":["A binding contract arose on 6 March; the revocation is too late","The revocation is effective because A posted it before B posted the acceptance","No contract arises because A learnt of the acceptance only after posting the revocation","A contract arose only on 8 March, when the acceptance reached A"],"answer":0,"explanation":"An offer can be revoked only before acceptance is complete against the proposer, which happens when the acceptance is posted (6 March). A revocation is complete only when it reaches the offeree (7 March), so it came too late; the date of posting a revocation does not count.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-274","question":"A makes a written offer to sell his warehouse to B. A dies the next day. B, who has no knowledge of the death, posts an unconditional acceptance within the time allowed. Under the Indian Contract Act, what is the position?","options":["The offer lapsed automatically on A's death, whether or not B knew","The contract binds B but not A's legal representatives","Valid: death revokes an offer only if known before acceptance","A contract arises only if A's legal heirs ratify B's acceptance"],"answer":2,"explanation":"Section 6(4) revokes a proposal on the proposer's death or insanity only if that fact comes to the acceptor's knowledge before acceptance. B accepted in ignorance, so a contract arises and binds A's estate (a sale of property is not a personal contract).","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-275","question":"A's offer says 'reply by e-mail only'. B accepts by a registered letter, which reaches A. A keeps quiet for several weeks and then claims there was no contract because the prescribed mode was not used. Is he right?","options":["Yes; acceptance in any other mode is a counter-offer needing fresh acceptance","No; by not insisting on the mode within a reasonable time, A accepted it","Yes; deviating from the prescribed mode makes the acceptance void","No; the mode of acceptance is never relevant under Indian law"],"answer":1,"explanation":"Section 7(2) lets the proposer, within a reasonable time after the acceptance is communicated, insist that it be made in the prescribed manner. If he fails to do so, he accepts the acceptance. A's long silence waived the condition.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-276","question":"At the Collector's request, A spent his own money building a market. Later, traders who rented shops there promised A a commission on goods sold. When they did not pay, A sued. What is the result?","options":["A succeeds, because past consideration is valid in India","A succeeds, because consideration may move from any person","A fails, because the agreement is not in writing and registered","A fails, as he did not build at the traders' desire"],"answer":3,"explanation":"Under Section 2(d) the act must be done at the desire of the promisor. Building at the Collector's request is not consideration for the traders' promise (Durga Prasad v Baldeo). Past consideration is valid only if the past act was done at the promisor's desire.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-277","question":"A trader sells 12 shirts on credit to B, a 17-year-old college student from a wealthy family, at prices suited to B's station. B's parents had already supplied him with an ample wardrobe. Can the trader recover the price from B's property?","options":["Yes, because clothes are always necessaries for a student","Yes, but only from B's parents, who are personally liable","No, but B must return the shirts, as a minor must restore benefits","No; B was already well supplied, so they were not necessaries"],"answer":3,"explanation":"Section 68 allows reimbursement from a minor's property only for necessaries – goods suited to his condition in life and his actual requirements at the time. A minor already adequately supplied does not need more (Nash v Inman). Parents are not liable merely by relationship.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-278","question":"In which of these cases does a seller's silence amount to fraud?","options":["A sells an unsound horse to his just-adult daughter who relies on him","A sells an unsound horse to a stranger B, who asks nothing","A sells B a used car 'as it is' after B inspects it at leisure","A sells B shares without mentioning that he expects the price to fall"],"answer":0,"explanation":"Mere silence is not fraud unless there is a duty to speak or the silence is itself equivalent to speech (Section 17, Explanation). A fiduciary-type relationship, such as a father dealing with a daughter who relies on him, creates that duty; a stranger owes none.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-279","question":"B buys a factory after A says it earns ₹20 lakh a year. The figure is false, but A believed it, and the audited books, which B was invited to inspect and could easily have checked, show the true profit of ₹12 lakh. B did not look at them. Can B avoid the contract?","options":["Yes; any misrepresentation makes a contract voidable","No; the truth was discoverable with ordinary diligence","Yes; the statement is fraud because it turned out to be false","No; the contract is void because of a mutual mistake of fact"],"answer":1,"explanation":"The Exception to Section 19 says a contract caused by misrepresentation (or fraud by silence) is not voidable if the party had the means of discovering the truth with ordinary diligence. A honestly believed the figure, so it is misrepresentation, not fraud, and B ignored an easy check.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-280","question":"B agrees to pay A a monthly salary of ₹50,000. In return A will manage B's lawful textile business and also run an illegal betting operation for B. B later refuses to pay. Can A enforce the salary for the lawful work?","options":["Yes, for the lawful part only, because the two parts are severable","Yes, because A has actually done the lawful work and earned it","No; one consideration for lawful and unlawful objects voids it all","No, but only because betting agreements are wagering agreements"],"answer":2,"explanation":"Section 24 makes the whole agreement void if any part of a single consideration for one or more objects is unlawful. The salary is one consideration for both objects, so nothing can be enforced, unlike reciprocal promises where the legal set can be separated.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-281","question":"A software firm's employment contract has two clauses: (1) while employed, the employee shall not work for any other firm; (2) for two years after leaving, he shall not join any competitor anywhere in India. How are they treated in India?","options":["Both clauses are valid because the employee agreed to them","Both clauses are void as restraints of trade under Section 27","Clause (1) is valid; clause (2) is void as a restraint of trade","Clause (1) is void; clause (2) is valid if it is reasonable in scope"],"answer":2,"explanation":"A negative covenant operating during employment is valid (Niranjan Shankar Golikari). A post-employment restraint falls under Section 27 and is void however reasonable, because the only statutory exception concerns the sale of goodwill (Superintendence Co. v Krishan Murgai).","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-282","question":"A agrees to pay B ₹2 lakh if B marries C. C then marries D. What is the status of the agreement?","options":["It remains contingent, because C could divorce D and marry B","It is enforceable at once, because the event can no longer happen","It was void from the start as an agreement in restraint of marriage","It becomes void, as the event is now treated as impossible"],"answer":3,"explanation":"Section 34: where the event is the way a living person will act at an unspecified time, it is treated as impossible when that person does anything that makes it impossible within a definite time. C's marriage to D does so, though a later divorce is conceivable.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-283","question":"A, B and C jointly promise to pay D ₹3,00,000. D recovers the whole amount from C. A is insolvent, and his estate can pay only half of his share. How much can C recover from B?","options":["₹1,00,000","₹1,25,000","₹1,50,000","₹1,75,000"],"answer":1,"explanation":"Each share is ₹1,00,000. A's estate pays ₹50,000, leaving ₹50,000 of A's share unpaid; under Section 43 that default is borne equally by B and C. So B owes his own ₹1,00,000 plus ₹25,000 = ₹1,25,000.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-284","question":"A fails to deliver a machine under contract. B could have hired a similar machine at once for ₹10,000 but, out of irritation, kept his plant idle for a month and lost profits of ₹2,00,000 that he could have avoided. What damages can B recover?","options":["Only the unavoidable loss, such as the hire charge, not the lost profits","The full ₹2,00,000, because A's breach directly caused the plant to stand idle","Nothing at all, because B refused to mitigate his loss in any way","Only nominal damages, because A's breach was not wilful or deliberate"],"answer":0,"explanation":"The Explanation to Section 73 requires the means of remedying the inconvenience to be taken into account. B can recover losses that reasonable mitigation would not have prevented; profits lost only because he failed to act reasonably are not recoverable.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-285","question":"A training firm registered only in Maharashtra conducts a two-day workshop in Goa for the employees of a company registered in Karnataka. What is the place of supply, and which tax applies?","options":["Place of supply is Goa; IGST","Place of supply is Maharashtra; CGST + SGST","Place of supply is Karnataka; IGST","Place of supply is Goa; CGST + SGST of Goa"],"answer":2,"explanation":"For training services supplied to a registered person, the place of supply is the recipient's location (Karnataka); the place of performance matters only for unregistered recipients. The supplier is in Maharashtra, so the supply is inter-state and IGST applies.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-286","question":"An employee of a company registered only in Delhi stays on business at a hotel registered in Rajasthan, and the bill is raised on the company's Delhi GSTIN. Which statement is correct?","options":["The hotel charges IGST, and the Delhi registration takes full input tax credit","Rajasthan CGST + SGST, which the Delhi registration cannot take as ITC","The hotel charges CGST + SGST of Delhi, because the recipient is in Delhi","No GST applies, because accommodation is used outside the recipient's state"],"answer":1,"explanation":"Services directly related to immovable property, including hotel accommodation, take the property's location as the place of supply. The supply is intra-state in Rajasthan, and Rajasthan CGST + SGST cannot be credited to a Delhi registration.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-287","question":"For a year a business with one PAN has: intra-state taxable supplies ₹30 lakh; exempt supplies ₹5 lakh; exports ₹8 lakh; transfers to its own branch registered in another state ₹4 lakh; inward supplies on which it paid tax under reverse charge ₹3 lakh; GST charged on its outward supplies ₹5.4 lakh. What is its aggregate turnover?","options":["₹52.4 lakh","₹50 lakh","₹43 lakh","₹47 lakh"],"answer":3,"explanation":"Aggregate turnover includes taxable, exempt and export supplies and inter-state supplies between distinct persons with the same PAN, but excludes GST and inward supplies taxed under reverse charge: 30 + 5 + 8 + 4 = 47. Adding the tax gives 52.4; adding reverse-charge purchases gives 50.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-288","question":"Which of these is a supply under GST even though no consideration is charged?\nI. A Delhi factory sends goods to the company's own depot in Haryana, which holds a separate GST registration.\nII. A factory moves goods to a second warehouse in the same state covered by the same registration.\nIII. A company permanently gives away an office laptop, on which it had taken input tax credit, to a charity.","options":["I and III only","I only","II and III only","I, II and III"],"answer":0,"explanation":"Schedule I treats supplies between distinct persons (separate registrations of the same PAN) and the permanent disposal of business assets on which credit was taken as supplies even without consideration. A movement within one registration is not a supply to another person.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-289","question":"A company distributes branded gift hampers, bought for the purpose, to its dealers at Diwali free of charge. What is the GST position of the tax paid on the hampers?","options":["Input tax credit is allowed because the gifts promote the business","Input tax credit is allowed, but the company must pay output tax on the gifts","Input tax credit is allowed only if each gift is below a stated value","Input tax credit is blocked because the goods are disposed of by way of gift"],"answer":3,"explanation":"Section 17(5) blocks credit on goods disposed of by way of gift or free samples. Business promotion does not unblock it. Since no credit is taken, there is also no deemed supply of business assets on which credit was taken.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-290","question":"Match each receipt with the head of income under which it is taxed.\n1. Rent received by a tenant from sub-letting part of his flat\n2. Salary and interest received by a partner from his firm\n3. Salary received by a Member of Parliament\n4. Rent received by the owner of a building let to a tenant who runs a shop in it\na. Income from house property  b. Profits and gains of business or profession  c. Income from other sources","options":["1-c, 2-b, 3-c, 4-a","1-a, 2-b, 3-c, 4-b","1-c, 2-c, 3-a, 4-a","1-a, 2-a, 3-b, 4-a"],"answer":0,"explanation":"House property income is taxed only in the owner's hands, so sub-letting income is 'other sources'. A partner's salary and interest are business income, not salary. An MP is not an employee, so the salary is 'other sources'. The tenant's use of the building does not change the owner's head.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-291","question":"In which case is the guarantee unenforceable for want of consideration?","options":["A agrees to sell goods to B on credit only because C promises to pay if B defaults","A has sued B for a debt; at C's request A agrees not to sue for a year, and C guarantees it","A lends money to B, and C guarantees repayment in exchange for a fee from B","A sold B goods on credit last month; today C, getting nothing, guarantees payment"],"answer":3,"explanation":"Under Section 127, anything done or promised for the benefit of the principal debtor is enough consideration for the surety. Forbearance to sue and a fresh supply are such benefits; a guarantee of a past, already-completed sale with nothing new given is void.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-292","question":"A gives a bank a continuing guarantee for loans to B up to ₹10 lakh. B borrows ₹4 lakh. A then dies; the bank, not knowing this, lends B a further ₹3 lakh. B defaults on both. For how much is A's estate liable, absent any contrary term?","options":["₹7 lakh","₹10 lakh","₹4 lakh","Nothing"],"answer":2,"explanation":"Under Section 131, the surety's death revokes a continuing guarantee for future transactions, unless the contract says otherwise. The estate stays liable for the ₹4 lakh lent before death but not for later advances.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-293","question":"C lends B ₹5 lakh with A as surety. When the loan falls due, (P) C makes a binding agreement with B to give him six months more, without A's consent; or (Q) C makes a binding agreement with X, a stranger, to give B six months more, without A's consent. In which case is A discharged?","options":["In Q only","In P only","In both P and Q","In neither P nor Q"],"answer":1,"explanation":"Section 135 discharges the surety when the creditor contracts with the principal debtor to give him time. Section 136 says an agreement to give time made with a third person, not with the principal debtor, does not discharge the surety.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-294","question":"A employs C to collect rents. C misappropriates some rent. Without telling B, A asks B to guarantee C's honesty in future; B does so. C later misappropriates again. Is B liable?","options":["No; the guarantee was obtained by concealing a material fact","Yes; a surety must make his own enquiries before he signs","Yes; the earlier fraud is irrelevant to C's honesty in the future","No; fidelity guarantees are void as against public policy"],"answer":0,"explanation":"Section 143 makes a guarantee invalid if the creditor obtains it by keeping silence about a material circumstance. C's earlier dishonesty was plainly material to the risk B was taking on.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-295","question":"A guarantees a loan to B on the understanding with the creditor C that C will not act on it until D also signs as a co-surety. D never signs. Can C enforce A's guarantee?","options":["Yes; A's liability is wholly independent of D's","Yes, but only for half the loan, as D was to share it equally","No, but only if A informs C before B defaults","No; the guarantee fails if the agreed co-surety never joins"],"answer":3,"explanation":"Section 144: where a guarantee is given on a contract that the creditor shall not act on it until another person joins as co-surety, the guarantee is not valid if that person does not join.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-296","question":"A rents out a car to B for a week. The car has a brake defect that A did not know of and could not easily have discovered. The brakes fail and B is injured. Is A liable?","options":["Yes; a bailor for hire answers for faults even if unaware of them","No; a bailor is liable only for faults he actually knew of and hid","No; the bailee must examine the goods before using them","Yes, but only if A was negligent in maintaining the car"],"answer":0,"explanation":"Section 150: a gratuitous bailor must disclose faults he knows of, but if the goods are bailed for hire, the bailor is responsible for damage arising from such faults whether or not he was aware of them.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-297","question":"B hires a car from A for his family's personal use only. B starts using it as a taxi for paying passengers. What right does A have?","options":["None until the agreed period of hire comes to its natural end","Only a claim for extra hire charges for taxi use","End the bailment, as B's use is inconsistent with its terms","Treat the car as sold to B and claim its full price"],"answer":2,"explanation":"Section 153 makes a bailment voidable at the bailor's option if the bailee does any act with the goods inconsistent with the conditions of the bailment. Commercial use breaches the agreed purpose.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-298","question":"A bails 100 bags of his rice with B, a warehouse keeper. Without A's consent, B mixes them with his own identical rice so that they cannot be separated. What is the position?","options":["A and B become joint owners in proportion to their shares","B must compensate A for the loss of the rice","A must bear the cost of separating the rice","A loses his rice because it is no longer identifiable"],"answer":1,"explanation":"Section 157: if the bailee mixes the goods without consent with his own so that they cannot be separated, the bailor is entitled to compensation. Proportional joint ownership (Section 155) arises only when the mixing is with consent.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-299","question":"A pledges gold with a bank for a loan of ₹2 lakh. Later the bank lends him a further ₹50,000 without any security being mentioned. A tenders ₹2 lakh with interest and demands the gold. What is the position?","options":["Return the gold, as a pledge secures only the debt it was made for","The bank may keep the gold only if A has signed a fresh pledge deed","The bank may sell the gold at once to recover the later advance","Keep the gold for the later advance too, as that is presumed by law"],"answer":3,"explanation":"Section 174 says the pawnee cannot, without a contract, retain the goods for any debt other than the one for which they were pledged, but such a contract is presumed, unless the contrary appears, for subsequent advances made by the pawnee.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-300","question":"X obtains jewellery from its owner by fraud, under a contract voidable at the owner's option. Before the owner rescinds the contract, X pledges the jewellery with Y, who acts in good faith and without notice of the fraud. What is Y's position?","options":["Y gets a good title as pawnee","Y must return the jewellery to the owner without any claim","Y gets a good title only if the owner fails to sue within a year","The pledge is void because X had no title"],"answer":0,"explanation":"Section 178A: a person in possession under a voidable contract can make a valid pledge before the contract is rescinded, if the pawnee acts in good faith without notice of the defect in the pledgor's title.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-301","question":"A, without B's authority, demands on B's behalf that C deliver goods belonging to B. C refuses. B now ratifies A's demand and sues C for damages for refusing a demand made by B's agent. Will B succeed?","options":["Yes; ratification relates back to the time of A's demand","No; ratification cannot subject a third person to damages or terminate his rights","Yes; C should have checked A's authority before refusing","No; an act can be ratified only by a principal of full age who knew of it in advance"],"answer":1,"explanation":"Ratification normally relates back, but Section 200 bars it where it would subject a third person to damages or end his right or interest. C cannot be made liable for refusing an unauthorised demand.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-302","question":"A principal revokes his agent's authority on 1 May but does not inform anyone else. On 5 May, the agent, still holding himself out as agent, buys goods from a regular supplier who knows nothing of the revocation. Is the principal bound?","options":["No; the authority ended on 1 May for all purposes","No; the agent alone is liable because he knew of the revocation","Yes; revocation does not bind third persons until known to them","Yes, but only if the principal later ratifies the purchase"],"answer":2,"explanation":"Section 208: termination of an agent's authority takes effect for third persons only when it becomes known to them. The principal is bound to the supplier, though he may claim against the agent for acting after revocation.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-303","question":"B, falsely claiming to be A's agent, contracts with C to sell A's land. A refuses to ratify. What is C's remedy?","options":["C can compel A to complete the sale of the land","C can enforce the sale against B personally, as if B owned the land","C has no remedy at all, because the contract was void","C can claim compensation from B for breach of warranty of authority"],"answer":3,"explanation":"Section 235 makes a person who untruly represents himself as an agent liable to the third party for any loss caused, if the alleged principal does not ratify. The principal is not bound by an unauthorised act he never ratified.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-304","question":"A clerk of a solicitors' firm, acting within his ostensible duties, induces a client to transfer her property to him and then sells it for his own benefit. Is the firm liable to the client?","options":["No; the firm itself gained nothing from the clerk's fraud","Yes; a principal answers for an agent's fraud in the course of employment","No; an agent's fraud always binds the agent alone, never the firm","Yes, but only if the firm's partners knew of or shared in the fraud at the time"],"answer":1,"explanation":"Under Section 238 and Lloyd v Grace, Smith & Co., misrepresentations or frauds by agents acting in the course of their business bind the principal as if he had committed them, whether or not he benefited.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-305","question":"A instructs his agent B to beat up C, who owes A money. B does so and is made to pay damages to C. Can B recover the damages from A?","options":["No; a principal is not bound to indemnify an agent for doing a criminal act","Yes; the principal must indemnify the agent for all acts done on his instructions","Yes, but only half the damages","No, unless A promised the indemnity in writing"],"answer":0,"explanation":"Sections 222–223 give an agent indemnity for lawful acts and acts done in good faith, but Section 224 says the employer is not liable for a criminal act even if he expressly promised to indemnify.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-306","question":"A cow kept by a farmer under a contract of bailment gives birth to a calf during the bailment. To whom must the calf be delivered when the bailment ends?","options":["To the bailee, as compensation for keeping the cow","To be shared equally between bailor and bailee","To the bailor, together with the cow","To the bailee, unless the bailor paid for its feed"],"answer":2,"explanation":"Section 163: in the absence of a contract to the contrary, the bailee must deliver to the bailor any increase or profit that has accrued from the goods bailed – the illustration in the Act is a cow and its calf.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-307","question":"B agrees to buy a specific machine installed in A's factory; A is to dismantle and pack it before B collects it. Before A finishes dismantling, the factory catches fire without anyone's fault and the machine is destroyed. Who bears the loss?","options":["B, because property in specific goods always passes when the contract is made","B, because he agreed to the price before the fire broke out","A, as property passes only once the goods are deliverable and B has notice","The loss is shared equally, as neither party was at fault"],"answer":2,"explanation":"Section 21: where the seller must do something to specific goods to put them into a deliverable state, property does not pass until that is done and the buyer has notice. Risk follows property (Section 26), so A bears the loss.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-308","question":"A seller agrees to sell 500 kg of unascertained sugar to a buyer in another city. He separates 500 kg, delivers it to a railway carrier consigned to the buyer and does not reserve any right of disposal. The goods are lost in transit through no one's fault. Who bears the loss?","options":["The buyer, as unconditional appropriation to the carrier passed property","The seller, because the buyer never actually received the goods","The carrier, who is always absolutely liable for goods in transit","The seller, as property in unascertained goods passes only on actual delivery"],"answer":0,"explanation":"Under Section 23, delivering goods to a carrier for transmission to the buyer, without reserving the right of disposal, is an unconditional appropriation that passes property. Risk passes with property, so the buyer bears the loss.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-309","question":"Goods are delivered to B on 'sale or return' terms for 7 days. B keeps them for three weeks without giving any notice of rejection, and they are then destroyed in a fire at his premises without his fault. Who bears the loss?","options":["The seller, because B never expressed approval","The seller, because goods on approval remain at the seller's risk until paid for","The loss is split because neither party was at fault","B, because the property passed to him when the 7 days expired"],"answer":3,"explanation":"Section 24: property passes to the buyer on approval if he retains the goods beyond the time fixed for return without giving notice of rejection. With property went the risk, so B must pay the price.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-310","question":"A sells his car to B and is paid, but B leaves the car with A for a few days. Meanwhile A sells and delivers the same car to C, who pays and has no notice of the first sale. Who gets the title?","options":["B, because property had already passed to him","C, as a seller left in possession can pass good title to C","B, because no one can give a better title than he has","Neither; both sales fail, and the car must be returned to A"],"answer":1,"explanation":"Section 30(1) is an exception to the nemo dat rule: where a seller continues in possession after the sale, a sale and delivery by him to a person receiving in good faith without notice is valid. B's remedy is against A.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-311","question":"A buyer orders 'Brand Z industrial adhesive' by its trade name from a dealer, mentioning that he needs it for bonding glass. The adhesive is of good quality but does not bond glass well. Does the buyer have a claim for breach of the implied condition of fitness for purpose?","options":["Yes; he made his particular purpose known to the seller","Yes; caveat emptor does not apply to purchases made from a dealer","No; implied conditions apply only to sales by sample","No; none is implied when a named article is bought by trade name"],"answer":3,"explanation":"The proviso to Section 16(1) says that, for the sale of a specified article under its patent or other trade name, there is no implied condition as to fitness for a particular purpose, because the buyer relies on the brand, not the seller's skill.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-312","question":"A buyer lawfully rejects goods delivered to him because they are not of the contracted quality. What must he do with the goods?","options":["Return them to the seller at his own cost","Sell them and remit the net proceeds to the seller","Just intimate his refusal; he need not return them","Keep them and pay a reasonably reduced price"],"answer":2,"explanation":"Section 43: unless otherwise agreed, a buyer who lawfully refuses delivery need not return the goods to the seller; it is enough to intimate the refusal.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-313","question":"A seller hands goods to a carrier for delivery to the buyer at a distant city without reserving any right of disposal. While they are in transit, the seller learns that the buyer has become insolvent and has not paid. Which right can the seller now use?","options":["Stoppage in transit, as his lien ended on delivery to the carrier","Lien, because the goods have not yet reached the buyer","Resale of the goods at once, without stopping them first","No right at all, because property has already passed to the buyer"],"answer":0,"explanation":"Section 49 ends the lien when goods go to a carrier for transmission to the buyer without reservation of the right of disposal. Section 50 then lets an unpaid seller resume possession while the goods are in transit if the buyer becomes insolvent.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-314","question":"Goods are in transit to an insolvent buyer. In which situation does the unpaid seller still have the right of stoppage in transit?","options":["The buyer has collected the goods from the carrier halfway through the journey","The goods are at the destination, but the carrier has not yet attorned to the buyer","The carrier has acknowledged at the destination that it holds the goods for the buyer","The carrier has wrongfully refused to deliver the goods to the buyer at destination"],"answer":1,"explanation":"Under Section 51, transit ends if the buyer takes delivery before the destination, if the carrier attorns to the buyer after arrival, or if the carrier wrongfully refuses to deliver to the buyer. Goods merely lying with the carrier at the destination are still in transit.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-315","question":"A buyer of non-perishable goods fails to pay. The unpaid seller, still holding the goods, resells them at a loss without giving the buyer any notice of his intention to resell. What is the consequence?","options":["He can recover the loss, because the buyer was already in default","The resale is void and the buyer can reclaim the goods from the new buyer","He can recover the loss but must pay interest to the buyer on the price","He cannot recover the loss, and the buyer would take any profit"],"answer":3,"explanation":"Under Section 54(2), the seller may resell non-perishable goods and recover the loss only after giving notice of his intention to resell. If he resells without notice, he cannot recover the loss, and the buyer is entitled to any profit.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-316","question":"Which of these is a valid promissory note under the Negotiable Instruments Act?","options":["'I promise to pay B ₹5,000 seven days after my marriage with C.'","'I promise to pay B ₹5,000 on C's death.'","'Mr B, I.O.U. ₹5,000.'","'I promise to pay B ₹5,000 and all other sums which shall be due to him.'"],"answer":1,"explanation":"A promissory note needs an unconditional promise to pay a certain sum. Death is certain to happen, though its time is not, so payment is not conditional. Marriage may never happen; an I.O.U. is a mere acknowledgment of debt; 'all other sums' makes the amount uncertain.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-317","question":"A cheque was originally drawn 'Pay Ravi or bearer'. Ravi endorses it 'Pay Sunil' and signs. It is then stolen from Sunil and presented by the thief at the bank, which pays it in good faith and without negligence. Is the bank discharged?","options":["No; the special endorsement made it payable only to Sunil","No; the bank should have verified the identity of the presenter","Yes; a cheque originally to bearer stays payable to bearer for the bank","Yes, but only if Sunil himself had endorsed it in blank before it was stolen"],"answer":2,"explanation":"Section 85(2): where a cheque is originally expressed to be payable to bearer, the drawee is discharged by payment in due course to the bearer, notwithstanding any endorsement, whether in full or in blank.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-318","question":"A cheque crossed generally with the words 'not negotiable' is stolen from the payee and transferred to C, who gives full value and has no notice of the theft. Can C enforce it against the drawer?","options":["No; C takes no better title than the thief, who had none","Yes; C is a holder in due course who paid full value","Yes; 'not negotiable' only stops further endorsement","No; a 'not negotiable' cheque cannot be transferred at all"],"answer":0,"explanation":"Section 130: a person taking a cheque crossed 'not negotiable' does not have, and cannot give, a better title than the transferor. The thief had no title, so C gets none, although the cheque remains transferable.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-319","question":"A cheque shows ₹25,000 in figures and 'Rupees Twenty Thousand only' in words. What amount is payable?","options":["₹25,000, the amount in figures","₹20,000, the amount in words","Nothing, because the cheque is void for uncertainty","Whichever amount the holder chooses"],"answer":1,"explanation":"Section 18: if the amount is stated differently in figures and words, the amount stated in words is the amount undertaken or ordered to be paid. (Banks in practice may return such cheques, but the legal rule is clear.)","difficulty":"moderate","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-320","question":"An instrument is so worded that it could be read either as a promissory note or as a bill of exchange. How must it be treated?","options":["It is void for ambiguity and unenforceable by anyone","It must be treated as a bill of exchange, being an order","The court decides which it is, based on the drafter's intention","The holder may elect to treat it as either, and is then bound"],"answer":3,"explanation":"Section 17: where an instrument may be construed either as a promissory note or as a bill of exchange, the holder may at his election treat it as either, and it is thereafter treated accordingly.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-321","question":"A bank wrongly dishonours a customer's cheque even though his account had enough funds. Who can claim compensation from the bank under the Negotiable Instruments Act?","options":["The payee, because the cheque in his favour was not paid","Both the drawer and the payee, sharing the compensation equally","The drawer (the customer), for loss caused by the default","No one, because a bank owes duties only under its account terms"],"answer":2,"explanation":"Section 31: the drawee of a cheque having sufficient funds must pay it when duly required, and in default must compensate the drawer for any loss or damage. The payee has no contract with the drawer's bank; his remedy is against the drawer.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-322","question":"X finds a bearer cheque lying on the road and keeps it. Is X a 'holder' of the cheque within the meaning of the Negotiable Instruments Act?","options":["No; a finder is not entitled in his own name to it or its amount","Yes; anyone in possession of a bearer cheque is its holder","Yes, but he is not a holder in due course as he paid nothing","No, but he becomes a holder if he presents it within three months"],"answer":0,"explanation":"Section 8 defines a holder as a person entitled in his own name to the possession of the instrument and to receive the amount. A finder or thief has possession but no such entitlement, though a later transferee in good faith may still become a holder in due course.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-323","question":"A cheque has two parallel transverse lines across its face with the words 'and Co.' between them and nothing else. A second cheque has 'State Bank of India' written across its face without any lines. How are they treated?","options":["The first is generally crossed and the second is specially crossed","Both are generally crossed, as both carry words written across the face","The first is specially crossed and the second is not crossed","The first is generally crossed and the second is not crossed"],"answer":0,"explanation":"A general crossing is two parallel transverse lines, with or without 'and company' (Section 123). A special crossing is the name of a banker written across the face – the lines are not needed (Section 124).","difficulty":"moderate","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-324","question":"M owns all but one of the shares of a timber company and is also its largest creditor. He insures the company's timber in his own name. The timber is destroyed by fire. Can M recover under the policy?","options":["No; the timber is the company's, so M has no insurable interest in it","Yes; as near-sole owner he bears the whole economic loss","Yes, but only to the extent of his loan to the company","No, because the company should have taken the policy jointly with him"],"answer":0,"explanation":"A company is a separate legal person and owns its property; a shareholder, even a dominant one, or an unsecured creditor has no insurable interest in specific company assets (Macaura v Northern Assurance Co.).","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-325","question":"During a war, a company registered in India supplies goods to a firm. Almost all its shareholders and all its directors are nationals of the enemy country. On which ground can a court lift the corporate veil here?","options":["To make the shareholders personally liable for the company's trade debts","To treat the company as a partnership","To tax the shareholders on the company's undistributed profits","To determine whether the company has an enemy character"],"answer":3,"explanation":"Courts look behind the corporate form to see who controls a company when deciding whether it has an enemy character (Daimler Co. v Continental Tyre). Limited liability for trade debts is otherwise preserved.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-326","question":"A private company's register shows 190 non-employee member entries, of which 6 are three pairs of persons holding shares jointly. In addition, 25 current employees and 8 former employees (who became members while employed and kept their shares) are members. How many members count towards the 200-member limit?","options":["223","187","190","215"],"answer":1,"explanation":"Joint holders count as one member, so 190 entries become 187. Current employees, and former employees who became members while employed and continue as members, are excluded. Counting everyone gives 223.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-327","question":"A company wants to move its registered office (i) to another building within the same city; (ii) to another state. Which approvals are needed?","options":["(i) A special resolution; (ii) a special resolution and the Tribunal's approval","(i) A board resolution; (ii) an ordinary resolution of members only","(i) Board resolution; (ii) special resolution plus Central Government approval","(i) Approval of the Regional Director; (ii) approval of the Registrar only"],"answer":2,"explanation":"A shift within the local limits of the same city is a board matter; moving outside the city's local limits would need a special resolution (Section 12(5)), and changing ROC jurisdiction within the state needs the Regional Director's confirmation. A shift to another state alters the memorandum, so it needs a special resolution and confirmation by the Central Government under Section 13(4).","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-328","question":"The articles of a public company contain an entrenchment clause stating that a specified provision may be altered only with the consent of all members. Which statement about entrenchment is correct?","options":["Entrenchment provisions are not permitted under the Companies Act, 2013","Private company: all members must agree; public company: a special resolution","Entrenchment provisions may be included only in the memorandum, never the articles","Entrenchment provisions can be adopted only with the Tribunal's approval"],"answer":1,"explanation":"Section 5(3)–(4) allows articles to say that specified provisions can be altered only if conditions stricter than a special resolution are met. Such provisions can be made at formation or by amendment – with all members' agreement in a private company and by special resolution in a public one.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-329","question":"A company's articles state that X shall be its solicitor for life. X is not a member. The company later appoints a different solicitor, and X sues the company relying on the articles. What is the likely outcome?","options":["X fails; the articles bind the company only to members as members","X succeeds, because the articles are a public document binding the company","X succeeds, because the company is estopped by its own articles","X fails only because a life appointment is void for uncertainty"],"answer":0,"explanation":"Section 10 makes the memorandum and articles a contract between the company and its members as members. An outsider cannot enforce them, even if named in them (Eley v Positive Government Security Life Assurance).","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-330","question":"Before a company was incorporated, its promoter signed a contract on its behalf to buy machinery. After incorporation the company wants to be bound by and enforce the contract. Which statement best reflects Indian law?","options":["The company automatically becomes a party to it on incorporation","The company can ratify it by board resolution like any agent's act","Such contracts are void ab initio, and even the promoter is not personally liable","No ratification, but it may enforce it under the Specific Relief Act if adopted"],"answer":3,"explanation":"A company not in existence cannot ratify, as ratification needs a principal in existence at the time (Kelner v Baxter); the promoter remains personally liable. The Specific Relief Act, 1963 lets the company enforce or be bound if the contract was for its purposes and it adopted it after incorporation.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-331","question":"A prospectus containing an untrue statement names X as a director. X proves that the prospectus was issued without his knowledge or consent and that, on becoming aware of its issue, he at once gave reasonable public notice of this. What is his civil liability to subscribers under Section 35?","options":["He is fully liable, because he was named as a director","He is liable only for the part of the loss he could have prevented","Not liable, as he proves no knowledge or consent and prompt notice","He is not liable only if he also resigns as director at once"],"answer":2,"explanation":"Section 35(2) protects a person who, having consented to be a director, withdrew his consent before the issue, or who proves that the prospectus was issued without his knowledge or consent and that on becoming aware of its issue he forthwith gave reasonable public notice to that effect.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-332","question":"A company has cumulative preference shares on which no dividend has been paid for the last two years. In general meetings, on which resolutions may these preference shareholders vote?","options":["Only on resolutions that directly affect the rights attached to their shares","On every resolution placed before the company","Only on resolutions to wind up the company","On no resolution until arrears are paid"],"answer":1,"explanation":"Section 47(2): preference shareholders ordinarily vote only on resolutions directly affecting their rights, or on winding up or reduction of capital. But if their dividend has not been paid for two years or more, they get the right to vote on all resolutions.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-333","question":"For which of these purposes may a company NOT use its securities premium account?","options":["Issuing fully paid bonus shares","Writing off preliminary expenses","Paying a dividend to equity shareholders","Providing the premium payable on redemption of debentures"],"answer":2,"explanation":"Section 52 limits the securities premium to purposes such as fully paid bonus shares, writing off preliminary expenses, writing off issue expenses, commissions or discounts, providing premium on redemption of preference shares or debentures, and buy-back. Dividends cannot be paid out of it.","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-334","question":"Which of these statements about a bonus issue under the Companies Act, 2013 are correct?\nI. It may be made out of the securities premium account.\nII. It may be made out of a reserve created by revaluation of assets.\nIII. It may be made in lieu of a dividend.\nIV. It may be made out of the capital redemption reserve account.","options":["I and IV only","I and II only","I, III and IV only","II and III only"],"answer":0,"explanation":"Section 63 allows bonus shares out of free reserves, securities premium or the capital redemption reserve, but not out of revaluation reserves, and never in lieu of dividend. The capital redemption reserve is expressly allowed as a source.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-335","question":"A company wants to buy back its equity shares. From which source can it NOT finance the buy-back?","options":["Its free reserves","Its securities premium account","Proceeds of an earlier issue of preference shares","Proceeds of an earlier issue of equity shares"],"answer":3,"explanation":"Section 68(1) permits buy-back out of free reserves, securities premium or the proceeds of an issue of shares or other securities, but no buy-back of any kind of shares can be made out of the proceeds of an earlier issue of the same kind of shares.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-336","question":"A member pays the full amount on his partly paid shares before the company makes the calls (calls in advance), as the articles allow. Which statement is correct?","options":["He gets full voting rights on the advance amount at once","No voting rights on the advance until that amount is called","The amount must be refunded, as calls in advance are prohibited","He becomes a creditor and loses his rights as a member"],"answer":1,"explanation":"Section 50 lets a company accept calls in advance if its articles authorise it (and it may pay interest on them), but the member is not entitled to voting rights on that amount until it is called and becomes payable.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-337","question":"How does transmission of shares differ from transfer of shares?","options":["Transmission is a voluntary sale by the holder and needs a stamped transfer deed","Transmission requires the prior consent of all the other members","Transmission applies only to preference shares, not equity shares","Transmission is by operation of law, e.g. death, with no transfer deed"],"answer":3,"explanation":"A transfer is a deliberate act of the holder by a duly stamped instrument of transfer. Transmission occurs by operation of law – death, insolvency or lunacy – and the legal heir or representative gets the shares on producing evidence, without a transfer deed or stamp duty.","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-338","question":"A company creates a charge on its machinery in favour of a lender but neither files it with the Registrar within the time allowed nor gets it registered later. The company goes into liquidation. What is the position of the lender?","options":["The charge is ignored by the liquidator, but the debt stays payable","The debt itself is extinguished along with the unregistered charge","The charge is valid because registration is only a formality","The lender gets priority over all creditors as the charge came first"],"answer":0,"explanation":"Under Section 77(3), an unregistered charge is not taken into account by the liquidator or any creditor. The lender becomes an unsecured creditor; the underlying debt is not destroyed.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-339","question":"X signed the memorandum of a company as a subscriber but was never allotted shares, and his name was never entered in the register of members. Is he a member?","options":["No; only persons entered in the register of members are members","No; a subscriber must also apply for shares in writing","Yes; subscribers are deemed members and entered on registration","Yes, but only after the first general meeting confirms it"],"answer":2,"explanation":"Under Section 2(55), the subscribers to the memorandum are deemed to have agreed to become members and, on registration, are entered as members. Membership of subscribers arises from subscription itself, unlike other members who need agreement plus entry in the register.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-340","question":"Members holding 12% of a company's paid-up capital with voting rights validly requisition an extraordinary general meeting. The board does nothing. What can the requisitionists do?","options":["Apply to the Tribunal, which alone can then call the meeting","Hold it themselves within three months and recover reasonable costs","Nothing, because calling general meetings is solely the board's power","Call the meeting themselves at any time, without any time limit"],"answer":1,"explanation":"Section 100: if the board does not, within 21 days of a valid requisition, proceed to call a meeting to be held within 45 days, the requisitionists may themselves call and hold it within three months, and the company must reimburse their reasonable expenses.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-341","question":"A public company wants to hold an extraordinary general meeting at shorter notice than 21 clear days. Whose consent is needed?","options":["A majority in number holding at least 95% of voting paid-up capital","At least 95% of the members entitled to vote, irrespective of capital","The board alone, if there is genuine urgency, with ROC intimation","Members holding a simple majority of the paid-up voting capital"],"answer":0,"explanation":"Section 101(1): for an AGM, consent of at least 95% of the members entitled to vote; for any other general meeting, a majority in number of members entitled to vote who represent at least 95% of the paid-up capital giving voting rights (or of total voting power for companies without share capital).","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-342","question":"A public company has 3,200 members. Unless its articles require more, what is the quorum for its general meeting?","options":["5 members personally present","30 members personally present","15 members personally present","Members holding one-tenth of the paid-up capital"],"answer":2,"explanation":"Section 103: for a public company, quorum is 5 members if members are not more than 1,000; 15 if more than 1,000 but not more than 5,000; and 30 if more than 5,000. A private company needs 2.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-343","question":"A shareholder appoints a proxy for a general meeting of a company with share capital. Which statement about the proxy is correct?","options":["The proxy must be a member of the company","The proxy can speak and vote on a show of hands","The proxy can vote on a show of hands but not on a poll","The proxy cannot speak and can vote only on a poll"],"answer":3,"explanation":"Under Section 105, a proxy need not be a member, but he has no right to speak at the meeting and is not entitled to vote except on a poll.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-344","question":"For which of these resolutions is a special notice required under the Companies Act, 2013?","options":["A resolution to declare a final dividend","A resolution to alter the articles of association","A resolution to remove a director before his term ends","A resolution to approve the annual financial statements"],"answer":2,"explanation":"Special notice (from members with the prescribed holding, at least 14 days before the meeting) is required for removing a director under Section 169 and for appointing an auditor other than the retiring auditor, among others. Altering the articles needs a special resolution, which is different.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-345","question":"A newly registered company held its first board meeting 25 days after incorporation. Its next meetings were held 100 days, 230 days and 300 days after incorporation. Has it complied with the requirement on the gap between board meetings?","options":["Yes; it held four meetings within its first year","Yes; the 120-day gap rule does not apply in the first year","No; the first meeting should have been held within 15 days","No; the second-to-third meeting gap exceeds 120 days"],"answer":3,"explanation":"Section 173(1) requires the first board meeting within 30 days of incorporation (met) and at least four meetings a year, with not more than 120 days between two consecutive meetings. Meetings on day 100 and day 230 are 130 days apart.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-346","question":"A director attends no board meetings in person over a 12-month period, but he joins one of the five meetings held during that time by video conferencing. The other four he misses after obtaining leave. Has his office become vacant under Section 167?","options":["Yes; he was absent in person from every meeting held","No; he attended one meeting, and video attendance counts","Yes; leave of absence does not count as attendance","No; office never falls vacant for absence if leave was granted"],"answer":1,"explanation":"Section 167(1)(b) vacates the office if a director absents himself from all board meetings held during 12 months, with or without leave. Attending even one meeting, including through the permitted video-conferencing mode, avoids this.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-347","question":"Shareholders want to remove a director who was appointed by the Tribunal under Section 242 in an oppression and mismanagement case. Can they do it by an ordinary resolution under Section 169?","options":["No; a director appointed by the Tribunal under Section 242 is excluded","Yes; any director can be removed by an ordinary resolution after special notice","Yes, but only by a special resolution passed after special notice","No, unless the director himself consents to removal in writing"],"answer":0,"explanation":"Section 169(1) allows removal of a director by ordinary resolution after giving him a reasonable opportunity of being heard, but it expressly excludes a director appointed by the Tribunal under Section 242.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-348","question":"A director is appointed as an additional director by the board under powers in the articles. Until when does he hold office?","options":["For a full term of five years from appointment","Until the next board meeting, which must confirm him","Until he is removed by the shareholders by an ordinary resolution","Till the next AGM or its last due date, whichever is earlier"],"answer":3,"explanation":"Section 161(1): an additional director holds office up to the date of the next AGM or the last date on which the AGM should have been held, whichever is earlier. He must then be appointed by the members to continue.","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-349","question":"A company's paid-up capital is ₹50 crore, free reserves ₹30 crore and securities premium ₹20 crore. Its existing borrowings are ₹70 crore, of which ₹10 crore are temporary loans from its bankers in the ordinary course of business. The board wants a fresh 5-year term loan of ₹45 crore. Is a special resolution under Section 180 needed?","options":["No; total borrowings of ₹115 crore are within twice the paid-up capital","Yes; non-temporary borrowings would be ₹105 crore, above the ₹100 crore limit","No; borrowings would be ₹100 crore, exactly at the permitted limit","Yes, because any single term loan above ₹40 crore always needs a special resolution"],"answer":1,"explanation":"Section 180(1)(c) needs a special resolution where borrowings, excluding temporary loans from bankers in the ordinary course, exceed paid-up capital + free reserves + securities premium = ₹100 crore. After the loan: ₹60 crore + ₹45 crore = ₹105 crore.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-350","question":"A company's paid-up capital is ₹100 crore, free reserves ₹60 crore and securities premium ₹20 crore. Under Section 186, up to what aggregate amount can it give loans, guarantees and investments in other bodies corporate without a special resolution?","options":["₹108 crore","₹80 crore","₹180 crore","₹96 crore"],"answer":0,"explanation":"The limit is the higher of 60% of (paid-up capital + free reserves + securities premium) = 60% × 180 = ₹108 crore, and 100% of (free reserves + securities premium) = ₹80 crore. So ₹108 crore. ₹96 crore applies 60% to paid-up capital and free reserves only.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-351","question":"Which of these is NOT a key managerial personnel (KMP) as defined in the Companies Act, 2013?","options":["The company secretary","The chief financial officer","The internal auditor","A whole-time director"],"answer":2,"explanation":"Section 2(51) lists the CEO, managing director or manager; the company secretary; the whole-time director; the CFO; and such other officers (not more than one level below directors, in whole-time employment) designated by the board. The internal auditor is not KMP by definition.","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-352","question":"Company A holds 60% of the voting power of Company B. A also holds 30% of the voting power of Company D, and B holds another 30% of D. Is D a subsidiary of A?","options":["No; A holds only 30% of D directly, which is below half","No; D is an associate of A, not a subsidiary","Yes, but only if A also controls D's board","Yes; with its subsidiary B, A controls over half of D"],"answer":3,"explanation":"Section 2(87) treats a company as a subsidiary if the holding company exercises or controls more than one-half of its total voting power either on its own or together with one or more of its subsidiaries. A + B = 60% of D.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-353","question":"Company P holds 25% of the total voting power of Company Q, and Q is not its subsidiary or joint venture. How is Q classified in relation to P?","options":["As a subsidiary, because P holds more than 20%","As a related party only if P's directors sit on Q's board","As an associate company, as P has significant influence","As a holding company of P, by cross-holding"],"answer":2,"explanation":"Under Section 2(6), an associate is a company in which another company has significant influence, meaning control of at least 20% of total voting power or of business decisions under an agreement, but which is not its subsidiary.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-354","question":"A company with share capital has 600 members. A group of 70 members, together holding 6% of the issued share capital (all calls paid), wants to file a petition for oppression and mismanagement under Section 241. Are they eligible to apply under Section 244, without any waiver?","options":["Yes; they are at least one-tenth of members, which is under 100","No; they need at least 100 members, whatever the total membership","No; they need members holding at least 10% of the issued share capital","Yes, but only with the Central Government's prior sanction"],"answer":0,"explanation":"Section 244 allows not less than 100 members or one-tenth of the total members, whichever is less (here 60), or members holding at least one-tenth of the issued share capital. 70 members satisfy the numerical test even though their holding is only 6%.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-355","question":"A one person company (OPC) is being incorporated. Which requirement relates specifically to an OPC?","options":["It must have at least two directors on its board","Its memorandum must name a nominee to succeed the sole member","Its single member may be a body corporate or an LLP","It must hold an annual general meeting every year with a quorum of two"],"answer":1,"explanation":"Section 3(1)(c) requires an OPC's memorandum to name a person, with his consent, who will become the member if the subscriber dies or becomes incapable of contracting. Only a natural person can be its member, it can have one director, and Section 96 on AGMs does not apply to it.","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-356","question":"For a month, a registered person's output tax is IGST ₹40,000, CGST ₹10,000 and SGST ₹10,000. Its input tax credit is IGST nil, CGST ₹30,000 and SGST ₹5,000. Using credit in the legally permitted order, how much must it pay in cash under each head?","options":["IGST ₹40,000; CGST nil; SGST ₹5,000","IGST ₹15,000; CGST nil; SGST nil","IGST ₹20,000; CGST nil; SGST nil","IGST ₹20,000; CGST nil; SGST ₹5,000"],"answer":3,"explanation":"CGST credit first pays CGST (₹10,000) and the balance ₹20,000 may pay IGST. SGST credit pays SGST ₹5,000, leaving ₹5,000 SGST in cash. CGST credit can never pay SGST, and SGST credit cannot pay CGST, so ₹5,000 of SGST stays payable in cash.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-357","question":"A supplier quotes a list price of ₹1,00,000 and gives a 5% discount on the invoice at the time of supply. The invoice also charges ₹3,000 for delivery to the buyer and ₹1,000 of a local levy that is not GST. Separately, the buyer pays ₹2,000 directly to a testing laboratory, a fee the supplier was contractually liable to pay and which is not included in the invoice price. What is the value of supply for GST?","options":["₹1,01,000","₹99,000","₹96,000","₹1,06,000"],"answer":0,"explanation":"Value = 95,000 (net of the invoice discount) + 3,000 incidental delivery charge + 1,000 non-GST tax + 2,000 supplier's liability borne by the recipient = ₹1,01,000. Leaving out the buyer-paid fee gives ₹99,000; ignoring the discount gives ₹1,06,000.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-358","question":"An Indian subsidiary receives management support services free of charge from its parent company located abroad, in the course of its business. What is the GST position?","options":["It is not a supply because there is no consideration at all","It is an export of services by the parent and hence zero-rated in India","A supply even without consideration, taxable under reverse charge","It is a supply only if the parent registers in India"],"answer":2,"explanation":"Schedule I treats import of services by a person from a related person outside India, in the course or furtherance of business, as a supply even without consideration. Tax on imported services is paid by the Indian recipient under reverse charge.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-359","question":"Which of these is a supply under GST?\nI. Sale of a completed flat after the completion certificate is issued and the builder has received the entire price after that date\nII. Sale of a flat in an under-construction project where the buyer pays instalments before completion\nIII. Sale of agricultural land","options":["I and II only","II only","I and III only","I, II and III"],"answer":1,"explanation":"Schedule III treats sale of land and, subject to the completion-certificate condition, sale of a completed building as neither goods nor services. Construction of a complex where any consideration is received before completion is a supply of services under Schedule II.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-360","question":"A contractor gives a machine on hire to a builder for six months; ownership stays with the contractor, and the builder gets the right to use it. How is this treated under GST?","options":["As a supply of goods","As a supply of services","As neither goods nor services","As a composite supply of goods and services taxed as goods"],"answer":1,"explanation":"Schedule II: transfer of the right to use goods without transfer of title is a supply of services. A transfer of title in goods would be a supply of goods.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-361","question":"A machinery maker registered in Gujarat sells a machine to a buyer registered in Maharashtra. Under the contract it must deliver and install the machine at the buyer's plant in Karnataka. What is the place of supply?","options":["Maharashtra, the buyer's registered location","Gujarat, where the movement begins","Maharashtra or Karnataka, at the buyer's choice","Karnataka, where the machine is installed"],"answer":3,"explanation":"Under Section 10(1)(d) of the IGST Act, where goods are assembled or installed at site, the place of supply is the place of installation or assembly – Karnataka. The usual 'movement terminates' rule gives way to this specific rule.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-362","question":"A catering company sells packaged meals to passengers on a train from Delhi to Mumbai. The meals were taken on board at Delhi and are sold as the train passes through Rajasthan and Gujarat. What is the place of supply of the meals?","options":["Rajasthan or Gujarat, where each meal is sold","Mumbai, the final destination of the train","Delhi, where the goods were taken on board","The supplier's principal place of business"],"answer":2,"explanation":"Section 10(1)(e) of the IGST Act: where goods are supplied on board a conveyance such as a train, the place of supply is the location where the goods are taken on board – Delhi.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-363","question":"An unregistered person living in Bengaluru buys a Mumbai–Delhi air ticket for himself from an airline registered in Maharashtra. What is the place of supply and which tax applies?","options":["Maharashtra, where he embarks; CGST + SGST","Karnataka, his place of residence; IGST","Delhi, the final destination of travel; IGST","Maharashtra, the airline's registered state; IGST"],"answer":0,"explanation":"For passenger transport to an unregistered person, the place of supply is where the passenger embarks on the conveyance for a continuous journey – Mumbai. The airline is in Maharashtra, so the supply is intra-state.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-364","question":"An unregistered individual in Pune hands over a parcel at a courier's Pune office for delivery to Kolkata. The courier company's supplying office is registered in Maharashtra. What is the place of supply of the courier service?","options":["West Bengal, where the parcel is delivered","The state of the courier company's head office","Maharashtra, where the parcel is handed over","Either state, at the courier company's choice"],"answer":2,"explanation":"For transport of goods, including mail and courier, to an unregistered person, the place of supply is the location where the goods are handed over for transport. So the supply is intra-state in Maharashtra.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-365","question":"The Indian branch of a foreign bank provides IT support to its head office abroad and receives payment in foreign exchange. Is this an export of services?","options":["No; a branch and its head office are mere establishments of one person","Yes; the recipient is outside India and payment is in foreign exchange","Yes, provided the place of supply is outside India under Section 13","No; IT support services can never qualify as an export of services"],"answer":0,"explanation":"An export of services needs, among other conditions, that the supplier and the recipient are not merely establishments of a distinct person (a branch and its head office). This condition fails even if the other conditions are met.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-366","question":"A registered dealer in Delhi (A) orders goods from a supplier in Haryana (S) and directs S to deliver them straight to A's customer in Delhi (C). A pays S. For input tax credit on S's invoice, when is A treated as having received the goods?","options":["Only when A physically receives and inspects the goods","Only when C pays A for the goods","Never; only C can take the credit on it","When S delivers the goods to C on A's direction"],"answer":3,"explanation":"Under Section 16(2)(b), goods delivered by the supplier to another person on the direction of the registered person are deemed received by the registered person. So A can take credit (subject to other conditions) when C receives the goods.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-367","question":"In which case is input tax credit available to the recipient, assuming GST rates and other conditions are met?","options":["A manufacturer buys a sedan for its sales director","A car dealer buys cars for resale","A company pays for club memberships for its managers","A firm pays for its employees' holiday travel"],"answer":1,"explanation":"Section 17(5) blocks credit on passenger motor vehicles (up to 13 seats), club memberships and travel benefits to employees on vacation. Vehicles bought for further supply of such vehicles are an express exception, so the dealer gets credit.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-368","question":"A registered professional buys a laptop for ₹1,00,000 plus GST of ₹18,000. He uses it 60% for his profession and 40% for personal purposes. How much input tax credit can he take?","options":["₹18,000","₹7,200","₹10,800","Nil"],"answer":2,"explanation":"Section 17(1): where goods are used partly for business and partly for other purposes, credit is restricted to the part attributable to business – 60% of ₹18,000 = ₹10,800. ₹7,200 is the personal share.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-369","question":"A supplier issues a credit note after a post-supply price reduction that was agreed before the supply. The recipient has already passed on the whole tax to its own customers by charging it in their prices and has not reversed any credit. What is the supplier's position?","options":["It can always reduce its output tax once a credit note is issued","It cannot reduce output tax, as the tax incidence was passed on","It can reduce output tax only in the following financial year","It must issue a debit note instead of a credit note"],"answer":1,"explanation":"The proviso to Section 34(2) bars a reduction in output tax liability if the incidence of tax and interest on the supply has been passed on to any other person – unjust enrichment is not allowed.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-370","question":"Three weeks after a supply, a supplier and buyer agree that, because of increased input costs, the buyer will pay ₹10,000 more than the invoice value. What document should the supplier issue?","options":["A debit note","A credit note","A revised bill of supply","A fresh tax invoice for a new supply"],"answer":0,"explanation":"Section 34(3): where the taxable value or tax in an invoice is less than the amount payable, the supplier issues a debit note. A credit note is for reductions or returns.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-371","question":"A customer orders food from a restaurant through a food-delivery app (an electronic commerce operator). Who is liable to pay GST on the restaurant service?","options":["The restaurant, under forward charge","The customer, under reverse charge","Nobody; food delivered through apps is exempt","The e-commerce operator"],"answer":3,"explanation":"Under Section 9(5) of the CGST Act, the government has notified restaurant services supplied through an e-commerce operator, so the operator pays the tax as if it were the supplier. Its own platform fee is a separate supply.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-372","question":"A registered trader sells only goods that are fully exempt from GST. What document should it issue to its customers?","options":["A tax invoice showing nil tax","A debit note","A receipt voucher","A bill of supply"],"answer":3,"explanation":"A registered person supplying exempt goods or services, or paying tax under the composition scheme, issues a bill of supply instead of a tax invoice under Section 31(3)(c).","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-373","question":"A buyer in Delhi imports goods from Germany. Which statement about GST on this import is correct?","options":["IGST is levied on import along with customs duty, and is creditable","CGST and SGST of Delhi are levied, because the importer is in Delhi","No GST applies, because imports are zero-rated like exports","The German supplier must register in India and charge IGST"],"answer":0,"explanation":"Import of goods is treated as an inter-state supply. IGST is levied under the Customs Tariff Act on the assessable value plus customs duty, collected with customs duty, and the importer can take credit of this IGST in the usual way.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-374","question":"An importer, while the goods are still on the high seas and before they are cleared for home consumption, sells them to a buyer by endorsing the bill of lading. How is this sale treated under GST?","options":["As an inter-state supply on which the importer must pay IGST","Neither goods nor services; the buyer pays IGST on clearance","As an export of goods, being a sale on the high seas","As a supply of services by the importer, taxable under RCM"],"answer":1,"explanation":"Schedule III treats the supply of goods by the consignee to another person, by endorsement of documents of title, after dispatch from the port of origin abroad but before clearance for home consumption, as neither goods nor services. Tax is collected at the customs stage.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-375","question":"An Indian trader buys goods from a supplier in China and sells them to a buyer in the UAE; the goods are shipped directly from China to the UAE and never enter India. What is the GST position of the trader's sale?","options":["It is an export of goods and zero-rated","It is an inter-state supply by the trader liable to IGST","It is neither a supply of goods nor services","It is an import of goods liable to IGST"],"answer":2,"explanation":"Schedule III covers supply of goods from a place outside India to another place outside India without the goods entering India, so merchant trading of this kind is outside GST.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-376","question":"A supplier delivers goods along with transport to the buyer's warehouse and transit insurance, all for one inclusive price, as is normal in the trade. How is the supply taxed?","options":["As a mixed supply taxed at the highest rate among the three","Each element is taxed separately at its own applicable rate","As a composite supply taxed at the rate of the goods","Transport is exempt and only the goods are taxed"],"answer":2,"explanation":"Goods, transport and insurance supplied together in the ordinary course of business, with the goods as the principal supply, form a composite supply (Section 2(30)), taxed at the rate of the principal supply.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-377","question":"Which of these must register under GST even if its aggregate turnover is below the threshold?","options":["A casual taxable person making taxable supplies","A trader making only intra-state exempt supplies","An agriculturist supplying produce from his own cultivation","A person making only supplies not liable to tax"],"answer":0,"explanation":"Section 24 requires compulsory registration, irrespective of threshold, for persons such as casual taxable persons, those liable under reverse charge, non-resident taxable persons and certain e-commerce suppliers. Persons making only exempt or non-taxable supplies, and agriculturists for their own produce, need not register.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-378","question":"A company runs a canteen for workers in its factory because the Factories Act obliges it to. It hires an outside caterer for this. Is input tax credit on the catering service available, assuming the company recovers nothing from the workers?","options":["No; credit on food and beverages is always blocked","Yes, but only half the credit, as the benefit is shared","No, unless the workers pay at least part of the cost","Yes; the block lifts where a law obliges the employer"],"answer":3,"explanation":"The proviso to Section 17(5)(b) allows credit on goods or services that an employer is obliged to provide to its employees under any law in force, which covers a statutory canteen.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-379","question":"The karta of a Hindu undivided family lives in Dubai and takes most decisions there, but some important decisions about the family's affairs are taken by family members in India. What is the HUF's residential status (assume the usual rule for HUFs)?","options":["Non-resident, because the karta lives abroad","Resident only if the karta stays in India for 182 days","Non-resident, because most decisions are taken abroad","Resident, as control is not wholly outside India"],"answer":3,"explanation":"An HUF (like a firm) is resident unless the control and management of its affairs is situated wholly outside India. Even partial control in India makes it resident; the karta's own stay matters only for deciding whether a resident HUF is ordinarily resident.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-380","question":"Assume: an individual who is resident is 'not ordinarily resident' (RNOR) if he was non-resident in 9 of the 10 preceding years. Mr K returns to India after 12 years abroad and is resident this year. His income: (1) salary for work done in India; (2) profits of a business in London controlled from London; (3) fees from a profession set up in India but carried on abroad; (4) rent from a flat in Singapore, received in Singapore. Which are taxable in India?","options":["(1) only","(1) and (3) only","(1), (2) and (3) only","All four"],"answer":1,"explanation":"An RNOR is taxed on income received or accruing in India, plus foreign income from a business controlled in, or a profession set up in, India. The London business is controlled abroad and the Singapore rent is foreign income received abroad, so both escape.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-381","question":"Assume that arrears of rent are taxed in the year of receipt after a deduction of 30%, whether or not the assessee still owns the property. Mr P sold his let-out house last year. This year he receives ₹1,00,000 of rent arrears for the period when he owned it. How much is taxable this year?","options":["₹70,000 under 'Income from house property'","Nil, because he no longer owns the property","₹1,00,000 under 'Income from other sources'","₹70,000 under 'Income from other sources'"],"answer":0,"explanation":"Arrears of rent are deemed income from house property in the year of receipt, even if the assessee is no longer the owner, after the stated 30% deduction: ₹1,00,000 × 70% = ₹70,000. The usual ownership condition is relaxed for arrears.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-382","question":"Mr R lets out a furnished flat under one agreement but at separately stated rents: ₹20,000 a month for the flat and ₹5,000 a month for the furniture, and the tenant could have rented the flat without the furniture. How is the rent taxed?","options":["The whole ₹25,000 under 'House property'","The whole ₹25,000 under 'Other sources'","Flat under 'House property', furniture under 'Other sources'","The whole ₹25,000 under 'Profits and gains of business or profession'"],"answer":2,"explanation":"When the building and other assets are let together but the lettings are separable, rent for the building is house-property income and rent for the other assets is taxed under 'Other sources' (or business). Only an inseparable composite letting is taxed wholly as other sources or business.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-383","question":"A trader owns a building and uses it as the shop for his own business. How is the building treated for income-tax purposes?","options":["Its notional annual value is taxed under 'House property'","Its fair rent is added to his business income","Its annual value is taxed under 'Other sources'","No house-property income, as it is used for his business"],"answer":3,"explanation":"House-property income excludes property occupied by the owner for his own business or profession whose profits are taxable. No notional rent is taxed; the use is reflected through business expenses such as depreciation and repairs.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-384","question":"Employer X allots shares to employee Y under an ESOP at ₹100 each; the fair market value on the date of exercise is ₹400. Y sells them two years later at ₹650. Per share, how much is taxed as a perquisite and how much as capital gain?","options":["Perquisite ₹550; capital gain nil","Perquisite ₹300; capital gain ₹250","Perquisite nil; capital gain ₹550","Perquisite ₹300; capital gain ₹550"],"answer":1,"explanation":"The perquisite is FMV on exercise minus the amount paid: 400 − 100 = ₹300, taxed as salary. For capital gains, the cost is that FMV (₹400), so the gain is 650 − 400 = ₹250. Using ₹100 as the cost would tax ₹300 twice.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-385","question":"Salary for April of the next financial year is paid to an employee in advance, in March of the current financial year. In which year is it taxed?","options":["In the current year, as salary is taxed on due or receipt, if earlier","In the next year, when the April salary actually falls due for payment","Half in each year, spread over the two years equally","In whichever year the employee chooses in his return"],"answer":0,"explanation":"Salary is charged on the earlier of the due basis and the receipt basis. Advance salary is taxed when received, and it is not taxed again when it falls due.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-386","question":"An employee receives ₹5 lakh from his employer as compensation for the premature termination of his employment, which is not covered by any specific exemption. How is it taxed?","options":["As a capital receipt, not taxable at all","Under 'Income from other sources' as a casual windfall","As 'profits in lieu of salary', under 'Salaries'","As a short-term capital gain on the job"],"answer":2,"explanation":"Compensation received from an employer on termination of employment, or on modification of its terms, is 'profits in lieu of salary' and taxed under 'Salaries', unless a specific exemption applies.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-387","question":"A business wrote off a bad debt of ₹80,000 two years ago and was allowed a deduction for it. This year it unexpectedly recovers ₹50,000 of that debt. How is the recovery treated?","options":["Nothing is taxable because it is a capital receipt","₹50,000 is taxable as business income this year","₹80,000 is taxable because the earlier deduction is reversed","Only ₹30,000 is taxable"],"answer":1,"explanation":"When a bad debt allowed earlier is recovered, the amount recovered (to the extent of the deduction allowed) is deemed business income in the year of recovery, even if the business is no longer carried on.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-388","question":"Assume the block-of-assets rules: if the sale proceeds of assets sold in a year exceed the opening WDV of the block plus additions, the excess is a short-term capital gain. A block has an opening WDV of ₹5 lakh, and an asset costing ₹2 lakh was added this year. One old asset is sold for ₹9 lakh; other assets remain in the block. What follows?","options":["STCG of ₹2 lakh, and no depreciation on the block this year","No capital gain, because the block still has other assets left in it","STCG of ₹4 lakh, being sale price less opening WDV","LTCG of ₹2 lakh, because the asset sold was old"],"answer":0,"explanation":"Proceeds (9) exceed opening WDV + additions (5 + 2 = 7) by ₹2 lakh, which is deemed a short-term capital gain whatever the holding period. The block's WDV becomes nil, so no depreciation arises even though assets remain; forgetting the ₹2 lakh addition gives the tempting ₹4 lakh.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-389","question":"A trader converts land held as a capital asset into stock-in-trade when its fair market value is ₹80 lakh (cost ₹30 lakh). He sells the land as stock two years later for ₹1 crore. Assume the usual rules for conversion of a capital asset into stock-in-trade. What is taxed, and when?","options":["Capital gain of ₹70 lakh in the year of conversion","Business profit of ₹70 lakh in the year of sale","Capital gain on ₹80 lakh as full value, and business profit of ₹20 lakh, both taxed in the year of sale","Capital gain on ₹80 lakh as full value in the year of conversion, and business profit of ₹20 lakh in the year of sale"],"answer":2,"explanation":"Conversion is a transfer, with the FMV on conversion as the full value of consideration, but the gain is taxed in the year the stock is sold. The business profit is sale price minus that FMV: 100 − 80 = ₹20 lakh, also in the year of sale.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-390","question":"Which of these is a capital asset for an individual who is not a dealer in it?","options":["A motor car held for personal use","Furniture held for personal use at home","Designer clothes held for personal use","Gold jewellery held for personal use"],"answer":3,"explanation":"Movable property held for personal use is excluded from 'capital asset', but jewellery, archaeological collections, drawings, paintings, sculptures and works of art are expressly kept within it.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-391","question":"A person wins ₹5,00,000 in a lottery after buying tickets worth ₹20,000 over the year. Assume the special rules for winnings. How much is taxable under 'Other sources'?","options":["₹4,80,000, after deducting the cost of tickets","₹5,00,000, as no expense is deductible from winnings","Nil, because lottery winnings are casual receipts exempt from tax","₹4,80,000, but taxed at normal slab rates"],"answer":1,"explanation":"Winnings from lotteries, crossword puzzles and similar games are taxed at a special flat rate on the gross amount; no expenditure, allowance or basic exemption is set off against them, so the ticket cost is ignored.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-392","question":"Mr S holds 40% of the shares of a company. His wife, who has no technical or professional qualification, is employed there and gets a salary of ₹6 lakh. Assume the clubbing rule for a spouse's remuneration from a concern in which the individual has a substantial interest. In whose hands is the salary taxed?","options":["In Mr S's hands","In his wife's hands","Half in each person's hands","In the company's hands"],"answer":0,"explanation":"The remuneration of a spouse from a concern in which the individual has a substantial interest is clubbed with the individual's income, unless it is solely attributable to the spouse's technical or professional knowledge and experience.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-393","question":"Mr F transfers a house to his son's wife without adequate consideration. She lets it out and earns rent. Assume the clubbing provisions. Whose income is the rent?","options":["His son's","His daughter-in-law's","Mr F's","The family's, as an HUF"],"answer":2,"explanation":"Income from assets transferred without adequate consideration to the son's wife is clubbed in the transferor's (father-in-law's) hands, just as with transfers to one's own spouse.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-394","question":"An individual files his income-tax return after the due date (a belated return). He has a business loss and a loss from house property for the year. Which loss can he carry forward to later years?","options":["Only the business loss","Both losses, without any limit","Neither loss, as the return is late","Only the house-property loss"],"answer":3,"explanation":"A business loss (and a capital loss) can be carried forward only if the return is filed within the due date. A house-property loss and unabsorbed depreciation are not subject to this condition.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-395","question":"Why is agricultural income, though exempt, considered when computing the tax of an individual who also has non-agricultural income above the exemption limit?","options":["Because it is taxed at a flat rate in such cases","Because its exemption lapses once the total income crosses the basic limit","To fix the tax rate on non-agricultural income (partial integration)","Because it is added to business income and taxed with it"],"answer":2,"explanation":"Under partial integration, net agricultural income is added only to fix the rate slab for non-agricultural income; the tax on agricultural income itself is then removed, so it stays exempt but pushes other income into higher slabs.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-396","question":"A 12-year-old child earns ₹60,000 from paintings he creates and sells himself. Assume the minor-clubbing rules. Is this income clubbed with his parent's income?","options":["Yes; all income of a minor child is clubbed","Yes, but only the part above ₹1,500","No, but only if the parent's own income is the lower of the two","No; income from a minor's own talent is not clubbed"],"answer":3,"explanation":"A minor's income is clubbed with the parent's income except income from manual work done by him or from any activity involving his skill, talent, specialised knowledge or experience.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-397","question":"A partner receives his share of the firm's profit plus salary and interest from the firm, as authorised by the partnership deed. How are these treated in his hands, assuming the firm is assessed as such?","options":["Profit share exempt; salary and interest taxed as business income","All three are taxed as his business income","All three are exempt in his hands, as the firm has already paid tax","Salary is taxed as 'Salaries' and the rest is exempt"],"answer":0,"explanation":"A partner's share of profit is exempt because the firm itself is taxed on it. Salary, bonus, commission and interest received from the firm are taxable as profits and gains of business or profession (to the extent the firm was allowed a deduction).","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-398","question":"Rent is received from letting out a vacant plot of land on which there is no building and which is not attached to any building. Under which head is it taxed (assume the landowner is not in the business of letting)?","options":["Income from house property","Income from other sources","Profits and gains of business","Capital gains"],"answer":1,"explanation":"House-property income covers buildings and land appurtenant to them. Rent from vacant land is not house-property income; unless it arises in a business, it falls under 'Other sources'.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-399","question":"A lender advances money to a trading firm on the terms that he will receive a share of its profits instead of fixed interest. He has no say in the business. Is he a partner?","options":["Yes; anyone who shares the profits of a business is a partner","Yes, but only for the purpose of liability to outsiders","No; sharing profits alone does not prove partnership","No, because a lender can never lawfully share in profits"],"answer":2,"explanation":"Section 6 of the Partnership Act and Cox v Hickman: receiving a share of profits, for example as a lender, does not by itself make a person a partner. The real test is whether the business is carried on by all or any of them acting for all.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-400","question":"A firm's partnership deed is silent on interest. Partner A has contributed ₹5 lakh as capital and has also advanced ₹2 lakh to the firm as a loan. What interest is A entitled to under the Partnership Act?","options":["6% a year on ₹7 lakh","6% a year on the ₹2 lakh advance; nothing on capital","Nothing on either amount","Interest at the bank rate on the ₹2 lakh advance only"],"answer":1,"explanation":"Section 13: in the absence of agreement, no interest is payable on capital, but a partner who makes an advance beyond his agreed capital is entitled to interest at 6% a year on it.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-401","question":"In a five-partner firm, three partners want to (i) change the firm's bankers and (ii) change the nature of the business from textile trading to real estate. The other two object. What is the legal position, absent any contrary agreement?","options":["Both can be decided by the majority of partners","Both need the consent of all the partners","(i) needs all partners; (ii) can be decided by majority","(i) by majority; (ii) needs all partners' consent"],"answer":3,"explanation":"Section 12(c): differences over ordinary matters connected with the business may be decided by a majority, but no change in the nature of the business may be made without the consent of all partners.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-402","question":"Partner X retires. The remaining partners continue the business using the firm's assets without settling his accounts. In the absence of any contract, what is X entitled to besides his share in the firm's property?","options":["At his option, profits attributable to his share or 6% interest on it","Only interest at the prevailing bank rate on his share","A share of all the future profits for as long as the business continues","Nothing more until the firm is formally dissolved"],"answer":0,"explanation":"Section 37: an outgoing partner (or his estate) is entitled, at his option, to the share of profits made since he ceased to be a partner that is attributable to the use of his share of the firm's property, or to interest at 6% a year on that share.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-403","question":"On dissolution, a firm's assets realise ₹1,00,000. Outside creditors are owed ₹60,000, and partner A has given the firm a loan of ₹20,000. Capitals are A ₹30,000 and B ₹10,000; profits and losses are shared equally, and both partners are solvent. How much does A receive in all?","options":["₹35,000","₹50,000","₹40,000","₹30,000"],"answer":2,"explanation":"Pay creditors 60,000, then A's loan 20,000, leaving 20,000 against capitals of 40,000: a capital loss of 20,000 shared equally. A bears 10,000 and gets 30,000 − 10,000 = 20,000 on capital; B bears 10,000 and gets nothing. A's total = 20,000 loan + 20,000 = ₹40,000.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-404","question":"Which of these is NOT a ground on which a court may order dissolution of a firm under Section 44 of the Partnership Act?","options":["The death of a partner","A partner has become permanently incapable of performing his duties","The business can be carried on only at a loss","A partner persistently breaches the partnership agreement"],"answer":0,"explanation":"Death of a partner dissolves a firm automatically under Section 42, subject to contract; it is not a ground for dissolution by the court. The other three are among the court's grounds under Section 44.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-405","question":"An LLP has two partners. One dies, and the survivor carries on the business alone for eight months, knowing he is the only partner. What is the position under the LLP Act, 2008?","options":["Nothing changes, because an LLP has perpetual succession","The LLP is automatically dissolved on the partner's death","The survivor becomes personally liable for all LLP debts since its formation","The survivor is personally liable for obligations after six months"],"answer":3,"explanation":"Section 6(2): if an LLP carries on business with fewer than two partners for more than six months, the person who is the only partner and knows it is personally liable for obligations incurred during that period.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-406","question":"A husband promises his wife a monthly allowance while he works abroad. Later he stops paying, and she sues on the promise. What is the likely result?","options":["She fails; spouses' domestic promises are presumed not legally binding","She succeeds, as her staying at home was consideration for the promise","She succeeds, because any promise made in writing is binding","She fails, because spouses cannot contract with each other at all"],"answer":0,"explanation":"In social and domestic agreements the law presumes no intention to create legal obligations (Balfour v Balfour), so no enforceable contract arises unless that presumption is rebutted. Spouses can, however, make binding contracts when they intend to.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-407","question":"A railway invites tenders, and S's tender to supply coal 'as and when ordered, up to 5,000 tonnes over a year' is accepted. After supplying three orders, S refuses to supply any more. Which statement is correct?","options":["A binding contract for the full 5,000 tonnes arose on acceptance of the tender","No contract ever arose, so S need not fulfil even the orders already placed","S cannot revoke because the railway itself invited the tenders","Standing offer: S must meet orders placed but may revoke for the future"],"answer":3,"explanation":"A tender to supply goods as and when required is a standing offer. Each order made under it is an acceptance creating a separate contract (Great Northern Railway v Witham). The offer can be withdrawn for the future, but orders already placed are binding.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-408","question":"A writes to B offering to sell his car for ₹4 lakh. On the same day, without knowing of A's letter, B writes to A offering to buy the same car for ₹4 lakh. The letters cross in the post. Is there a contract?","options":["Yes, because the parties agree on all the terms","No; cross offers are two offers, neither accepting the other","Yes, once the second letter is received by A","No, because the price was never negotiated or agreed between them"],"answer":1,"explanation":"Acceptance must be made in response to an offer with knowledge of it. Cross offers, even identical ones, are two offers, not offer and acceptance (Tinn v Hoffman). Either party could now accept the other's offer.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-409","question":"The managers of a school decide to appoint P as headmaster but do not tell him. One manager, acting without the board's authority, privately informs P. The board later changes its mind. Can P enforce the appointment?","options":["Yes; P learnt of the decision from a manager himself","Yes; the board's resolution itself was the acceptance of the offer","No; acceptance was not communicated by anyone authorised","No, because an appointment can never be a contract"],"answer":2,"explanation":"In Powell v Lee, information given by an unauthorised person was held not to be communication of acceptance. A mere internal decision does not conclude a contract.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-410","question":"A, of full age and free will, agrees to sell a house worth ₹80 lakh to B for ₹10 lakh. Later A says the agreement is void for inadequate consideration. Is he right?","options":["Yes; consideration must be roughly equal in value to what is given","No; inadequacy alone does not void it, though it bears on free consent","Yes; the agreement is voidable because the price is grossly unfair","No, but the court will raise the price to the house's fair market value"],"answer":1,"explanation":"Explanation 2 to Section 25: an agreement to which consent is freely given is not void merely because the consideration is inadequate; the inadequacy may be considered in deciding whether consent was freely given.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-411","question":"A rogue, posing as a reputable firm R & Co by mimicking its name in letters, orders goods from S by post; S sends them, believing he is dealing with R & Co. In another case, a rogue in S's shop falsely says he is a famous person and S, dealing face to face, lets him take goods on credit. What is the status of the two contracts?","options":["Postal one void for mistake as to identity; face-to-face one voidable","Both are void for mistake as to the identity of the buyer","Both are voidable for fraud at S's option","The postal one voidable for fraud; the face-to-face one void for mistake"],"answer":0,"explanation":"Where the identity of the other party is vital and the seller intends to deal only with the named firm, there is no agreement (Cundy v Lindsay). Face to face, the seller is presumed to intend to deal with the person in front of him, so the contract is only voidable for fraud (Phillips v Brooks).","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-412","question":"A lends money to B so that B can pay off a debt that B lost on a wager. B refuses to repay A. In most of India, can A recover the loan?","options":["No; any loan connected with a wager is itself void","No; the loan itself is illegal and A is guilty of abetting the wager","Yes; wagers are void but not illegal, so the loan stands","Yes, but only if B had won the wager"],"answer":2,"explanation":"A wagering agreement is void under Section 30 but not illegal (except where a State law makes it so, as in Maharashtra and Gujarat). Collateral transactions, such as a loan to pay a wagering debt, are therefore enforceable (Gherulal Parakh v Mahadeodas).","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-413","question":"A promises to pay B ₹1 lakh if a certain ship returns within a year. The ship returns after 14 months. What is the status of the promise?","options":["It is enforceable now that the ship has returned","It is enforceable for a proportionate amount","It becomes void only if the ship never returns","It is void, as the event did not occur in time"],"answer":3,"explanation":"Section 35: a contingent contract to do something if an event happens within a fixed time becomes void if, when that time expires, the event has not happened. The later return does not revive it.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-414","question":"A owes B ₹10,000 under a contract. On the due date, A brings exactly ₹10,000 in cash to B's office at the agreed time, but B refuses to accept it. What is the effect?","options":["The debt is extinguished entirely, because B refused a valid tender of it","A is not liable for non-performance, but the debt itself survives","A becomes liable to pay interest for the delay","B can sue A immediately for breach of contract"],"answer":1,"explanation":"Section 38: a valid offer of performance that is refused means the promisor is not responsible for non-performance and does not lose his rights. For a money debt the obligation to pay remains, but no interest or damages for delay run against A.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-415","question":"A agrees to paint a portrait of B for ₹50,000, and C agrees to pay D ₹50,000 for a used car on delivery. Both A and C die before performing. What is the position?","options":["A's contract ends as it needs his skill; C's heirs must pay for the car","Both contracts end automatically on the death of the promisor","Both promises bind the legal representatives of A and C alike","A's representatives must finish the portrait by engaging another painter"],"answer":0,"explanation":"Section 37 binds the promisor's representatives on his death unless a contrary intention appears from the contract. A portrait involves personal skill, so it ends with the painter (Section 40); paying money does not.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-416","question":"A owes B ₹50,000. C, without A's request, pays B the full amount, and B accepts it in full satisfaction. Later B sues A for the debt. What is the result?","options":["B succeeds, because C was a stranger to the contract","B succeeds, but must refund C the ₹50,000","B fails only if A later ratifies C's payment","B fails, as he accepted performance from C"],"answer":3,"explanation":"Section 41: when a promisee accepts performance of the promise from a third person, he cannot afterwards enforce it against the promisor.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-417","question":"A, B and C jointly promise to pay D ₹3 lakh. D releases A from the promise by an agreement with him alone. What is the effect on B and C?","options":["They are discharged because the joint promise has been broken up","They are each liable only for ₹1 lakh, their own share","Not discharged; and A still owes contribution to B and C","They are discharged unless they consented to the release"],"answer":2,"explanation":"Section 44: where one of joint promisors is released by the promisee, the others are not discharged, and the released promisor is not freed from responsibility to the other joint promisors.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-418","question":"A agrees to whitewash B's house for ₹20,000. B keeps the house locked and refuses to let A in. What is A's position?","options":["A must keep tendering performance until B allows access","A has no remedy because the work was never done","Voidable at A's option, with compensation for his loss","The contract is void for supervening impossibility"],"answer":2,"explanation":"Section 53: when one party prevents the other from performing a reciprocal promise, the contract becomes voidable at the option of the party prevented, who can recover compensation for any loss caused.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-419","question":"A shipping company had five trawlers but licences for only three. It chose to allot the licences to three other trawlers, leaving the chartered one unlicensed, and then claimed that the charter was frustrated. Is it right?","options":["Yes; the licensing rule made performance impossible","Yes; any supervening government restriction frustrates a contract","No; frustration can never arise from government action","No; the impossibility came from its own choice of vessels"],"answer":3,"explanation":"Self-induced impossibility is not frustration (Maritime National Fish v Ocean Trawlers). The company itself chose which vessels to license, so the impossibility was of its own making and it remained liable.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-420","question":"A builder contracts to construct a hall for a fixed price. Because of sharp increases in cement and steel prices, the project now costs 40% more than expected. Can the builder treat the contract as frustrated?","options":["No; mere rise in cost or hardship does not make it impossible","Yes; any unforeseen event making it costlier frustrates the contract","Yes, if the cost increase exceeds 25% of the contract price","No, but the court must raise the contract price to cover it"],"answer":0,"explanation":"Section 56 covers performance becoming impossible or unlawful, or the commercial purpose being destroyed. Mere hardship, increased expense or market changes do not discharge a contract (e.g. Satyabrata Ghose v Mugneeram Bangur).","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-421","question":"A owes B ₹5,000. B accepts ₹2,000 at A's request in full satisfaction of the whole debt, and nothing else is given. Can B later sue for the remaining ₹3,000?","options":["Yes; part payment can never discharge a larger debt","No; under Section 63 B may accept any satisfaction he likes","Yes, because there was no fresh consideration for the ₹3,000","No, but only if the settlement was in writing and registered"],"answer":1,"explanation":"Section 63 allows the promisee to remit wholly or partly the performance, or to accept any satisfaction he thinks fit. Illustration (b) to the section is exactly this case; Indian law does not follow the English rule in Pinnel's case.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-422","question":"B rescinds a contract with A because A obtained his consent by fraud. B had earlier received ₹1 lakh from A under that contract. What must B do?","options":["Keep the ₹1 lakh as damages for the fraud","Restore the ₹1 lakh (the benefit received) to A","Keep the ₹1 lakh because fraud makes the contract void from the start","Pay A double the amount as a penalty"],"answer":1,"explanation":"Section 64: when a person at whose option a contract is voidable rescinds it, he must restore any benefit received under it to the person from whom it was received. B may separately claim compensation for loss caused by the fraud.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-423","question":"A agrees to sing at B's theatre on two nights each week for three months and also agrees not to sing at any other theatre during that period. She breaks both promises. What remedy will a court most likely grant B?","options":["Injunction against singing elsewhere, plus damages; no order to sing","Specific performance compelling her to sing for B as agreed","Only nominal damages, because personal service can never be enforced at all","A mandatory injunction compelling her to sing for B"],"answer":0,"explanation":"Courts will not order specific performance of personal services, but they may enforce an express negative covenant by injunction (Lumley v Wagner), leaving B also free to claim damages.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-424","question":"A seller agrees to sell a horse 'at a price to be fixed by valuer X'. X refuses to value it, and the horse has not been delivered. What is the legal position?","options":["The court will fix a reasonable price itself and enforce the sale","The seller may choose any other valuer to fix the price","Avoided; a buyer who had taken the horse would pay a fair price","The buyer must pay the market price immediately"],"answer":2,"explanation":"Section 10 of the Sale of Goods Act: if the third party cannot or does not fix the price, the agreement is avoided, but a buyer who has received and appropriated the goods must pay a reasonable price for them.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-425","question":"A buyer bought a machine described as 'new, 2025 model'. It turns out to be a reconditioned 2023 model, though it works well. Which statement is correct?","options":["No breach, because the machine is of merchantable quality","Only a breach of warranty, so the buyer can only claim damages","Caveat emptor applies, so the buyer has no remedy at all","Breach of the condition of correspondence with description"],"answer":3,"explanation":"Section 15: where goods are sold by description, there is an implied condition that they correspond with the description. Words such as 'new, 2025 model' identify the goods, so a reconditioned older model breaches a condition, whatever its working order.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-426","question":"A buyer examines a second-hand car before buying it from a dealer but overlooks an obvious large dent in the door. Later she claims the car was not of merchantable quality because of the dent. Will she succeed?","options":["Yes; a dealer always guarantees merchantable quality","Yes; examination does not affect implied conditions","No; the condition excludes defects examination should reveal","No; second-hand goods carry no implied conditions of any kind at all"],"answer":2,"explanation":"The proviso to Section 16(2) says that if the buyer has examined the goods, there is no implied condition as to defects that such examination ought to have revealed. Hidden defects would still be covered.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-427","question":"A contract of sale says nothing about delivery. The goods are ready at the seller's warehouse, and the buyer has not asked for them. What does the Sale of Goods Act say about the seller's duty?","options":["The seller must send the goods to the buyer's place at his own cost","The seller must deliver within seven days of the contract","The seller is discharged if the buyer does not collect within a month","The seller need not deliver until the buyer applies for delivery"],"answer":3,"explanation":"Section 35: apart from any express contract, the seller of goods is not bound to deliver them until the buyer applies for delivery. Section 36 adds that, absent agreement, the place of delivery is where the goods are at the time of sale.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-428","question":"A buyer finds that the goods breach a condition of the contract but decides to keep them. What may he do?","options":["Keep the goods and refuse to pay any part of the price","Waive it, or treat it as a breach of warranty and claim damages","Keep the goods and also rescind the contract for the breach","Nothing, because a breach of condition must always lead to rejection"],"answer":1,"explanation":"Section 13(1): where a contract is subject to a condition to be fulfilled by the seller, the buyer may waive the condition or elect to treat the breach as a breach of warranty, which gives a claim for damages rather than rejection.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-429","question":"A makes a promissory note in favour of B without any consideration, purely as a favour, so that B can raise money. B endorses it for value to C, who knows that it was an accommodation note. Can C recover from A at maturity?","options":["Yes; lack of consideration between A and B is no defence against C","No; the note has no consideration and creates no obligation","No; C knew that A received nothing and so took the note with notice","Yes, but only for the amount C actually paid B for it"],"answer":0,"explanation":"Section 43 makes a note without consideration unenforceable between the original parties, but if it is negotiated to a holder for consideration, he may recover from any prior party. The accommodation party lends his name and is liable to the holder for value.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-430","question":"A bill of exchange payable '30 days after sight' is presented and accepted on 1 March. Allowing three days of grace and assuming no holidays intervene, on what date is it payable?","options":["31 March","4 April","3 April","2 April"],"answer":2,"explanation":"In counting days after sight, the day of sight is excluded (Section 23), so 30 days runs to 31 March. Adding three days of grace (Section 22) gives 3 April. Instruments payable on demand or at sight get no grace.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-431","question":"A minor endorses a bill of exchange to C for value. The bill is dishonoured at maturity. Against whom can C proceed?","options":["Against no one, because the minor's endorsement is void","Against all parties to the bill other than the minor","Only against the minor","Only against the drawee"],"answer":1,"explanation":"Section 26: a minor may draw, endorse, deliver and negotiate an instrument so as to bind all parties except himself. The minor's endorsement passes title, so the other parties remain liable to C.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-432","question":"A foreign bill of exchange is dishonoured by non-payment. Which step is legally required for it?","options":["It needs no notice of dishonour at all because it is a foreign bill","Only noting is required; protest is never needed","It must be re-drawn and presented as an inland bill","Protest, if the law of the place where drawn requires it"],"answer":3,"explanation":"Section 104 requires foreign bills of exchange to be protested for dishonour when such protest is required by the law of the place where they are drawn. For inland instruments, noting and protest are optional.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-433","question":"A bill drawn by A on B in favour of C is dishonoured by non-payment. To whom must C give notice of dishonour in order to make them liable?","options":["All parties he wants to hold liable, but not the acceptor B","Only the acceptor B, who is primarily liable","Only the drawer A, who created the bill","Nobody; dishonour itself automatically makes every prior party liable"],"answer":0,"explanation":"Section 93: notice of dishonour must be given to all other parties whom the holder seeks to make liable. The acceptor is primarily liable and needs no notice; a party not given notice is discharged (subject to Section 98).","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-434","question":"A seller paints over cracks in a ship's hull before a prospective buyer inspects it. The buyer, seeing no defect, buys the ship. What is the status of the contract?","options":["Voidable at the buyer's option, as active concealment is fraud","Valid, because the buyer inspected the ship and caveat emptor applies","Void for mutual mistake as to the condition of the hull","Voidable only if the seller also made a false oral statement"],"answer":0,"explanation":"Section 17 includes the active concealment of a fact by one having knowledge or belief of it. Hiding defects so that inspection cannot reveal them is fraud, so caveat emptor gives the seller no protection.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-435","question":"A sends a letter offering to sell goods 'subject to a formal contract to be signed by both of us'. B replies 'I accept'. Before any formal contract is signed, A withdraws. Can B enforce the deal?","options":["Yes; B's unconditional acceptance concluded the contract","Yes, because A's withdrawal came after B's acceptance","No; they did not intend to be bound before the formal contract","No, but B can recover damages for his wasted expenses as of right"],"answer":2,"explanation":"Where an agreement is expressly 'subject to contract', the courts generally treat it as not binding until the formal contract is executed, because the parties have shown they do not intend to be bound before that.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-436","question":"A dealer sells a new laptop whose open market value is ₹50,000. The customer pays ₹40,000 in cash and hands over his old laptop, valued at ₹10,000, in exchange. The buyer is not related to the dealer. What is the value of supply of the new laptop for GST?","options":["₹40,000","₹50,000","₹60,000","₹30,000"],"answer":1,"explanation":"Where consideration is partly non-monetary, the value is the open market value, or else money plus the money value of the non-monetary part: ₹40,000 + ₹10,000 = ₹50,000. Taking only the cash (₹40,000) ignores the exchanged goods.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-437","question":"A supplier's invoice for goods worth ₹2,00,000 is paid late, and it charges the buyer ₹2,000 as interest for delayed payment. GST on the goods is 18% (assume). What is the GST position of the interest?","options":["The interest is a financial service exempt from GST","The interest is outside GST, being compensation, not consideration","It is added to the value of supply, so GST of ₹360 is payable","GST is payable on it at the rate for financial services, not 18%"],"answer":2,"explanation":"Section 15(2)(d) includes interest, late fee or penalty for delayed payment of consideration in the value of supply, so it takes the rate of the main supply: 18% × 2,000 = ₹360.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-438","question":"A retailer runs a 'buy one shirt, get one shirt free' offer and charges ₹1,000 for the pair. Which statement reflects the GST position?","options":["Tax on ₹1,000 for both shirts; not a free supply, so ITC is not blocked","The free shirt is a gift, so the input tax credit on it must be reversed","GST is payable on ₹2,000, the full value of both shirts","The free shirt is a deemed supply taxable at its open market value"],"answer":0,"explanation":"The government has clarified that a 'buy one get one free' offer is not an individual free supply: the price paid is for both items, so tax is on ₹1,000 and credit on the inputs remains available.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-439","question":"A supplier of goods (not under the composition scheme) receives an advance of ₹1,00,000 in June for goods to be supplied and invoiced in August. When is GST payable on the advance?","options":["On the advance in June, adjusted against the August invoice","Half in June on the advance and half in August on the invoice","Only when the balance payment is received after delivery","Not on the advance; GST arises on the August invoice"],"answer":3,"explanation":"For goods, payment is no longer a trigger for the time of supply for normal taxpayers, as notified by the government; tax arises on the invoice (or the due date for issuing it). For services, an advance does attract GST.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-440","question":"A manufacturer registered in Gujarat sends a machine to a repairer registered in Maharashtra; the repairer fixes it in its Pune workshop and returns it. The manufacturer is the recipient. What is the place of supply of the repair service and which tax applies?","options":["Gujarat, the registered recipient's location; IGST","Maharashtra, where the repair is performed; CGST + SGST","Maharashtra, where the machine was physically available; IGST","Gujarat, because the machine belongs there; CGST + SGST of Gujarat"],"answer":0,"explanation":"For domestic supplies, Section 12 of the IGST Act has no 'performance on goods' rule; repair services to a registered person fall under the general rule – the recipient's location. The repairer is in Maharashtra and the recipient in Gujarat, so IGST applies.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-441","question":"A company has units registered in three states under one PAN. Its head office in Mumbai receives invoices for audit and advertising services that benefit all units. How can the credit of the tax on these common services reach the other units?","options":["The Mumbai unit simply transfers its electronic credit ledger balance","Each unit claims credit directly on the head office's invoices","Through an Input Service Distributor that distributes it to the units","It cannot; the credit stays with the Mumbai unit that was billed"],"answer":2,"explanation":"An Input Service Distributor receives invoices for input services used by distinct persons with the same PAN and distributes the credit to them by issuing ISD invoices. Credit ledger balances cannot simply be transferred between GSTINs.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-442","question":"A manufacturer sends inputs directly from its supplier's premises to a job worker for processing, without first bringing them into its own factory. Can it take input tax credit on these inputs?","options":["No; inputs must first be received in the principal's factory","Yes; credit is allowed even if inputs go straight to the job worker","Only after the processed goods come back from the job worker to the factory","Only the job worker can take the credit on such inputs"],"answer":1,"explanation":"Under the job-work provisions, the principal may take credit on inputs sent to a job worker, including inputs supplied directly to the job worker without coming to the principal's premises, subject to the return conditions.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-443","question":"A refinery lays a pipeline outside its factory premises to bring crude from a nearby port. Is input tax credit available on goods and services used for constructing this pipeline?","options":["Yes; pipelines are always treated as plant and machinery","Yes, because the pipeline is used wholly for the business of the refinery","Only 50% of the credit is available on such civil works","No; pipelines outside the factory are not plant, so ITC is blocked"],"answer":3,"explanation":"The Explanation to Section 17 defines plant and machinery to exclude land, buildings, civil structures, telecommunication towers and pipelines laid outside the factory premises. Construction of such immovable property is blocked under Section 17(5)(c)/(d).","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-444","question":"Mr N is a non-resident this year. His UK employer pays his salary for work done in the UK by crediting it directly to his savings account in a bank in India. Is the salary taxable in India?","options":["No; a non-resident is taxed only on income earned in India","Yes; income received in India is taxable even for a non-resident","No; salary for services rendered abroad is never taxable in India","Yes, but only the part that exceeds his UK tax-free allowance"],"answer":1,"explanation":"A non-resident is taxed on income that is received (or deemed received) in India, or that accrues or arises (or is deemed to) in India. Salary first received in an Indian bank account is received in India, wherever the work was done.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-445","question":"Ms D, now resident and ordinarily resident, remits to India this year the savings from salary she earned and spent abroad over several earlier years when she was non-resident (that salary was not taxable in India then). Is the remittance taxable this year?","options":["Yes; all money received in India by a resident is taxable","Yes, because she is now resident and ordinarily resident","No; a mere remittance of past income is not income this year","Only the part remitted through formal banking channels is taxable"],"answer":2,"explanation":"Income is taxed in the year it is earned or first received. Transferring past savings into India is a remittance of capital, not a fresh receipt of income, so it is not taxed again.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-446","question":"Under the current income-tax rules, can a business claim depreciation on goodwill that it acquired when it bought another business?","options":["Yes, as part of the block of intangible assets","Yes, but only on the price actually paid for it","Only if the goodwill was acquired from a related party","No; goodwill of a business is not a depreciable asset"],"answer":3,"explanation":"Goodwill of a business or profession has been excluded from depreciable intangible assets, so no depreciation is allowed on it, though its cost is relevant when it is later transferred.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-447","question":"A company borrows money specifically to buy a new machine. Interest for the period before the machine is first put to use is ₹2 lakh. How is it treated?","options":["Capitalised in the machine's cost and recovered through depreciation","It is fully deductible under Section 36 as interest in the year it is paid","It is disallowed altogether, being pre-operative interest","It is deductible in five equal annual instalments"],"answer":0,"explanation":"Interest on capital borrowed for acquiring an asset, for any period before the asset is first put to use, is not allowed as a revenue deduction and is capitalised in the asset's actual cost. Interest after it is put to use is deductible.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-448","question":"A trader sells listed shares held for 8 months (assume the gain is short-term) for ₹5,00,000 and pays 1% brokerage on the sale. He bought them for ₹3,00,000, with brokerage of ₹3,000 on purchase. What is the short-term capital gain?","options":["₹1,92,000","₹2,00,000","₹1,95,000","₹1,97,000"],"answer":0,"explanation":"Full value ₹5,00,000 − transfer expenses ₹5,000 − cost of acquisition ₹3,03,000 (purchase brokerage forms part of cost) = ₹1,92,000. Ignoring both brokerages gives ₹2,00,000; ignoring only the purchase brokerage gives ₹1,95,000.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-449","question":"Assume clubbing rules apply to income from assets transferred to a spouse without adequate consideration, but not to income from the accretion of such income. Mr X gifts ₹20 lakh to his wife; she earns ₹1.6 lakh interest on it this year and reinvests that interest, earning ₹10,000 more. How much is clubbed in Mr X's income?","options":["₹1,70,000","₹10,000","Nil","₹1,60,000"],"answer":3,"explanation":"Income from the transferred asset itself (₹1,60,000) is clubbed with the transferor's income. Income earned on the reinvested interest is income from an accretion, which belongs to the wife.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-450","question":"Which of these is a revenue expenditure allowed as a business deduction (assuming it is laid out wholly for the business)?","options":["Buying a new machine to expand production capacity","Replacing worn-out parts to restore a machine to working order","Paying income tax assessed on the year's business profits of the firm","Paying a penalty for breaking a pollution-control law"],"answer":1,"explanation":"Current repairs that restore an asset without creating a new one are revenue in nature. A new machine is capital expenditure (depreciation only); income tax is not a business expense; penalties for infringing the law are expressly disallowed.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-451","question":"A company's directors, acting within the company's objects but beyond the powers given to them by the articles, buy a building. What can be done about the transaction?","options":["Nothing; it is void and can never be ratified","Only the Tribunal can validate it on petition","Members in general meeting can ratify it, as it is intra vires","The company is bound only if all its creditors consent to the purchase"],"answer":2,"explanation":"An act ultra vires the directors but intra vires the company can be ratified by the members. Only acts beyond the company's own objects are incapable of ratification (Ashbury Railway Carriage v Riche).","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-452","question":"Which of these may a company issue at a discount to its face value under the Companies Act, 2013?","options":["Equity shares in a public issue","Bonus shares","Sweat equity shares","Preference shares in a rights issue"],"answer":2,"explanation":"Section 53 prohibits issuing shares at a discount except sweat equity shares issued under Section 54 (and certain shares issued to creditors on conversion of debt under a statutory scheme). Bonus shares are fully paid without any payment, not 'at a discount'.","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-453","question":"A company makes a private placement of shares. Which statement is correct?","options":["It must not advertise or use marketing channels to tell the public","It may advertise the offer in national newspapers, just like a public issue","It may invite applications from anyone who responds to it","It needs no special resolution or offer letter of any kind"],"answer":0,"explanation":"Section 42 requires private placement to be made through a private placement offer letter to identified persons, approved by special resolution; the company must not release public advertisements or use media or marketing channels to inform the public of the offer.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-454","question":"A listed company's remuneration committee proposes to grant stock options to all its directors, including its independent directors. Is this permitted?","options":["Yes, with a special resolution of the members","Yes, if the options are capped at 1% of share capital","No; no director can ever receive stock options","No; an independent director cannot get stock options"],"answer":3,"explanation":"Section 149(9) says an independent director shall not be entitled to any stock option. He may receive sitting fees, reimbursement of expenses and profit-related commission as approved by members. Executive directors can receive options.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-455","question":"Which of these is a 'related party' of Company X under the Companies Act, 2013?","options":["A partnership firm in which a director of Company X is a partner","A customer that buys more than 20% of Company X's output","Company X's largest unsecured creditor","An unrelated firm that supplies goods to Company X at market prices"],"answer":0,"explanation":"Section 2(76) lists, among others, a director or KMP and their relatives, a firm in which a director, manager or his relative is a partner, and certain companies with common directors or members. Economic dependence alone, such as a large customer or creditor, does not create a related party.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-456","question":"Which listed company must have at least one woman director on its board under the Companies Act, 2013?","options":["Only listed companies with paid-up capital above ₹1,000 crore","Every listed company","Only government companies","None; it is only a recommendation"],"answer":1,"explanation":"The second proviso to Section 149(1) requires such class of companies as may be prescribed to have at least one woman director, and the rules prescribe every listed company (and certain large public companies).","difficulty":"moderate","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-457","question":"A manufacturer took input tax credit of ₹1,00,000 on a machine. After 10 quarters of use it sells the machine for ₹2,00,000 plus GST at 18% (assume). Assume the rule that on removal of used capital goods the supplier pays the higher of (a) the credit taken reduced by 5 percentage points per quarter of use and (b) the tax on the transaction value. How much must it pay?","options":["₹36,000","₹86,000","₹50,000","₹64,000"],"answer":2,"explanation":"(a) Credit reduced by 5% × 10 quarters = 50%: ₹1,00,000 × 50% = ₹50,000. (b) Tax on transaction value = 18% × 2,00,000 = ₹36,000. The higher, ₹50,000, is payable. Adding the two (₹86,000) double-counts.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-458","question":"Which of these supplies is outside the levy of GST altogether under the Constitution and the GST laws, not merely exempt by notification?","options":["Fresh vegetables sold unbranded","Healthcare services by a hospital","Education services by a school","Alcoholic liquor for human use"],"answer":3,"explanation":"Article 366(12A) defines GST to exclude the supply of alcoholic liquor for human consumption, so States continue to tax it under their own laws. Fresh vegetables, healthcare and school education are within GST but exempted by notification.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-459","question":"For petroleum crude, high-speed diesel, motor spirit (petrol), natural gas and aviation turbine fuel, what is the constitutional and statutory position under GST?","options":["Within GST, but levied only from a date notified on Council advice","They are permanently outside GST under the Constitution, like alcohol","They are taxed under GST at a special demerit rate","They are exempt from all central and State taxes"],"answer":0,"explanation":"The Constitution and Section 9(2) of the CGST Act keep these five products within GST's scope but defer the levy to a date the government notifies on the Council's recommendation. Meanwhile, central excise and State VAT apply.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-460","question":"GST is described as a destination-based consumption tax. On an inter-state sale of goods from Gujarat to a consumer in Punjab, which State ultimately gets the State share of the tax?","options":["Gujarat, the producing and supplying State","Punjab, the consuming State, via IGST settlement","Both States equally, half each of the State share","Neither; inter-state tax goes wholly to the Centre"],"answer":1,"explanation":"IGST is levied by the Centre on inter-state supplies, and the State share is apportioned to the State where the goods are consumed (the place of supply). This is the destination principle.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-461","question":"A coaching firm registered in Delhi sells an online course to an unregistered individual whose address is not on its records. What is the place of supply under the general rule?","options":["Delhi, the location of the supplier","The location of the server hosting the course","The State where the student is physically present while studying","Wherever the payment is made from"],"answer":0,"explanation":"Under Section 12(2) of the IGST Act, for services to an unregistered person, the place of supply is the recipient's location if the address is on record, and otherwise the supplier's location. So the supply is intra-state in Delhi.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-462","question":"Assume an individual may treat at most two house properties as self-occupied (annual value nil), and any other house he occupies is 'deemed let out' at its expected rent. Mr A owns four houses, all used by his family and none let out. How is his house-property income computed?","options":["All four houses have nil annual value, as none is let out","Only one house can be self-occupied; three are deemed let out","Two of his choice are self-occupied; two are taxed on expected rent","All four are taxed on expected rent, because he owns more than two houses"],"answer":2,"explanation":"Under the stated rule, he chooses two houses as self-occupied (nil annual value). The remaining two are deemed let out and taxed on their annual value, even though no rent is received. He would choose so as to minimise tax.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-463","question":"Which of these is deductible as 'interest on borrowed capital' when computing income from a let-out house, assuming the loan was taken to buy the house?","options":["Interest on interest that was unpaid and added to the loan","Interest payable on the housing loan for the year","Brokerage paid to arrange the loan","Principal repayment of the loan"],"answer":1,"explanation":"Only interest on capital borrowed for acquiring, constructing or repairing the property is deductible. Interest on unpaid interest, brokerage or commission for arranging the loan, and principal repayments are not deductible under this head.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-464","question":"Mr B's land was compulsorily acquired by the government three years ago, but he received the compensation only this year. In which year is the capital gain taxable?","options":["The year of acquisition, when the transfer occurred","Spread equally over the three years in between","It is exempt because the transfer was compulsory","This year, when compensation is first received"],"answer":3,"explanation":"For compulsory acquisition, the capital gain is charged in the year in which the compensation, or part of it, is first received. Enhanced compensation is taxed in the year it is received.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-465","question":"A partner introduces his land into his firm as his capital contribution. Its market value is ₹90 lakh, but the firm records it in its books at ₹60 lakh. Assume the special rule for transfer of capital assets by a partner to a firm. What is the full value of consideration for computing the partner's capital gain?","options":["₹90 lakh, the market value on the date of transfer","Nil, because no money is received by the partner","The average of ₹60 lakh and ₹90 lakh, i.e. ₹75 lakh","₹60 lakh, the amount recorded in the firm's books"],"answer":3,"explanation":"When a partner transfers a capital asset to a firm by way of capital contribution, the amount recorded in the firm's books is deemed to be the full value of the consideration. Market value is not substituted under this specific rule.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-466","question":"A taxpayer receives a refund of excess income tax paid along with interest on the refund. How are the two treated?","options":["Both are taxable under 'Income from other sources'","Refund is not income; the interest on it is 'Other sources'","Neither is taxable, as both arise from tax that was paid earlier","Both are taxable as business income of the year"],"answer":1,"explanation":"A refund merely returns tax paid out of income that was already taxed, so it is not income. Interest received on the refund is a fresh receipt and is taxed under 'Other sources'.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-467","question":"An individual's gross total income consists only of a short-term capital gain on listed equity shares taxed at a special rate and winnings from a lottery. He has made investments that would normally qualify for deductions from gross total income. Assume the usual rule on such deductions. What is the position?","options":["The deductions reduce the capital gain but not the lottery winnings","The deductions reduce both incomes in proportion to their amounts","They cannot be set against these special-rate incomes and are lost","The unused deductions are carried forward to the next year"],"answer":2,"explanation":"The usual deductions from gross total income are not allowed against specified special-rate incomes such as short-term gains on listed equity taxed at the special rate, long-term capital gains and casual winnings. Unused deductions are not carried forward.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-468","question":"A partnership firm pays salary to a partner who does not work in the business (a 'sleeping partner'), as the partnership deed provides. Assume the usual rules for firms. Can the firm deduct it?","options":["No; only deed-authorised pay to working partners, within limits, is allowed","Yes, because the partnership deed expressly authorises paying salary to him","Yes, but only half of it, being the share of a sleeping partner","No, and the partner need not pay tax on it either"],"answer":0,"explanation":"A firm can deduct salary, bonus or commission only if paid to a working partner, authorised by the deed and within the prescribed limits. Remuneration to a non-working partner is disallowed in the firm's hands.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-469","question":"A company raised money from the public through a prospectus, and some of it is still unutilised. It now wants to change the objects for which the money was raised. What does the Companies Act, 2013 require?","options":["Only a board resolution, with a later intimation filed with the Registrar","An ordinary resolution at the next AGM, after notice","Special resolution by postal ballot, publicity and exit offer","Approval of the Tribunal only, on the company's petition"],"answer":2,"explanation":"Section 13(8) (and Section 27 for prospectus terms) requires a special resolution by postal ballot, publication of the justification, and an exit opportunity for dissenting shareholders as per SEBI rules when unutilised issue money is to be used for changed objects.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-470","question":"A newly registered company's name closely resembles that of an existing company. On the earlier company's application, what can the Central Government do?","options":["Strike the new company off the register immediately","Direct the new company to change its name in time","Order the two companies to merge under one name","Nothing, once the certificate of incorporation is issued"],"answer":1,"explanation":"Section 16 empowers the Central Government (on its own or on application) to direct a company registered with a name identical with or too nearly resembling an existing company's name to rectify its name, and the company must change it by ordinary resolution.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-471","question":"Which statement about the audit committee of a listed company under Section 177 of the Companies Act, 2013 is correct?","options":["At least three directors, with independent directors in majority","It must consist only of whole-time executive directors","It must be chaired by the managing director of the company","Only two members are needed, both of whom may be non-independent"],"answer":0,"explanation":"Section 177(2) requires a minimum of three directors with independent directors forming a majority, and a majority of members, including the chairperson, must be able to read and understand financial statements.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-472","question":"A director sends his resignation to the company on 10 June, stating that it is effective from 30 June. The company receives it on 12 June. From when is the resignation effective?","options":["10 June, the date written on the letter","12 June, the date on which the company received it","Only after the board formally accepts it","30 June, the later of receipt and stated date"],"answer":3,"explanation":"Section 168(2): a resignation takes effect from the date on which the notice is received by the company or the date, if any, specified by the director in the notice, whichever is later. Board acceptance is not needed.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-473","question":"In a public company, a director appointed by the general meeting dies in the middle of his term. How is the casual vacancy filled, assuming the articles do not provide otherwise?","options":["Only by the general meeting, at the next AGM","By the board, only for the rest of the original term","By the Tribunal on application by the company","By the board, for a fresh full term of five years of office"],"answer":1,"explanation":"Section 161(4): a casual vacancy in the office of a director appointed by the general meeting of a public company may be filled by the board at a board meeting, and the person appointed holds office only up to the date the original director would have held office.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-474","question":"A company incorporated two years ago wants to contribute to a political party. Is it allowed under the Companies Act, 2013?","options":["No; a company under three financial years old cannot contribute","Yes, if the board approves it by resolution at a duly convened meeting","Yes, up to any amount with the shareholders' approval","No; no company may ever make political contributions"],"answer":0,"explanation":"Section 182 bars a government company and any other company that has been in existence for less than three financial years from making political contributions. Other companies may contribute within the conditions set by the section.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-475","question":"A principal dies. Before learning of the death, his agent sells the principal's goods to a buyer who also knows nothing of the death. Is the sale binding on the principal's estate?","options":["No; an agency ends automatically at the moment of the principal's death","Yes, but only if the principal's legal heirs later ratify it","No, but the agent is personally liable to the buyer for the goods","Yes; termination binds agent and third parties only once known"],"answer":3,"explanation":"Section 208: termination of the agent's authority does not take effect as regards the agent before it becomes known to him, or as regards third persons before it becomes known to them. Both acted in ignorance, so the sale binds the estate.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-476","question":"A friend keeps B's bicycle for free while B is away. Through his carelessness – leaving it unlocked on the street – it is stolen. Is the friend liable to B under the Indian Contract Act?","options":["No; a gratuitous bailee is liable only for gross negligence","No; there is no contract because no consideration passed","Yes; every bailee, paid or not, owes ordinary prudent care","Yes, but only for half the bicycle's value, as it was free"],"answer":2,"explanation":"Section 151 sets one standard of care for all bailees, whether or not they are paid: the care a man of ordinary prudence would take of his own goods of the same kind. Leaving the bicycle unlocked falls short of that standard.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-477","question":"An agent appointed to sell a client's property delegates the whole task, without the client's knowledge, to another person, who sells it badly. Trade custom does not permit such delegation. What is the legal position?","options":["The delegate becomes the principal's own agent and alone is liable","The agent may not delegate; he answers for the delegate's acts","Delegation is always permitted when the agent is busy elsewhere","The principal must bear the loss because he chose the agent"],"answer":1,"explanation":"Section 190: an agent cannot lawfully employ another to perform acts he has expressly or impliedly undertaken to perform personally, unless custom or the nature of the agency allows it. Under Section 193, an agent who improperly appoints a sub-agent is responsible for his acts.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-478","question":"A landlord lets a house that had been vacant. Rent for one month, which had earlier been shown as unrealised and not taxed, is recovered from the old tenant this year. Assume the rule that unrealised rent recovered later is taxed in the year of recovery. How is it treated?","options":["It is taxed in the earlier year to which the unrealised rent relates","It is never taxed, because it was excluded earlier","It is taxed under 'Other sources' as a casual receipt","House-property income of the year of recovery, owner or not"],"answer":3,"explanation":"Unrealised rent that was excluded from the annual value and is later realised is deemed income from house property of the year of receipt, even if the assessee no longer owns the property.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-479","question":"A business pays its director's brother ₹1,20,000 a month as a consultant, while comparable consultants are paid ₹70,000 for the same work. Assume the rule allowing the tax officer to disallow excessive payments to relatives. How much may be disallowed for the year?","options":["₹14,40,000","₹8,40,000","₹6,00,000","Nil"],"answer":2,"explanation":"The excess over the reasonable market rate may be disallowed: (₹1,20,000 − ₹70,000) × 12 = ₹6,00,000. The reasonable part (₹8,40,000) stays deductible; disallowing the whole ₹14,40,000 goes too far.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-480","question":"Assertion (A): An agreement entered into by a minor is void from the beginning.\nReason (R): Under Section 11 of the Indian Contract Act, a person who has not attained the age of majority is not competent to contract.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Mohori Bibee v Dharmodas Ghose held a minor's agreement void ab initio precisely because Section 11 makes a minor incompetent to contract, so R explains A.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-481","question":"Assertion (A): An unregistered partnership firm cannot file a suit against a third party to enforce a right arising from a contract.\nReason (R): Registration of every partnership firm is compulsory under the Indian Partnership Act, 1932.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Section 69 bars suits by an unregistered firm against third parties on contractual rights, so A is true. But registration is not compulsory under the 1932 Act; non-registration merely brings these disabilities, so R is false.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-482","question":"Assertion (A): A registered person cannot use its CGST credit to pay its SGST liability.\nReason (R): CGST is levied and collected by the Centre and SGST by the State, so the credit of one government's tax cannot settle a liability owed to the other.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"Section 49 bars cross-utilisation between CGST and SGST. The reason is that they are separate levies of different governments; IGST, which is settled between them, is the only bridge.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-483","question":"Assertion (A): In a contract of sale of specific goods in a deliverable state, the property usually passes to the buyer when the contract is made.\nReason (R): The time of payment and the time of delivery decide when property passes in every sale.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":2,"explanation":"Section 20 says property in specific goods in a deliverable state passes when the contract is made, even if payment or delivery or both are postponed. So A is true and R is false: payment and delivery do not decide it.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-484","question":"Assertion (A): Rent from a vacant plot of land, not appurtenant to any building, is not taxed as income from house property.\nReason (R): Income from house property is charged on the annual value of buildings and lands appurtenant to them.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":0,"explanation":"The house-property head covers buildings or lands appurtenant thereto. A bare plot falls outside it, so its rent is taxed under 'Other sources' (or business). R gives the reason for A.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-485","question":"Assertion (A): A contract to do an act that is impossible in itself is void.\nReason (R): A promisor who knew, or with reasonable diligence could have known, that the act was impossible must compensate a promisee who did not know.","options":["Both A and R are true, and R is the correct explanation of A","Both A and R are true, but R is not the correct explanation of A","A is true, but R is false","A is false, but R is true"],"answer":1,"explanation":"Both are parts of Section 56: the first paragraph voids agreements to do impossible acts; the last paragraph imposes liability for compensation on a promisor who knew of the impossibility. The second does not explain the first.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-486","question":"Which of these conditions must be satisfied for a person to be a holder in due course of a cheque?\n1. He obtained it for consideration.\n2. He became its holder before the amount was due (for a cheque, before it became stale or was dishonoured).\n3. He had no sufficient cause to believe that there was a defect in the title of the transferor.\n4. He must be the payee named on the cheque.","options":["1, 2 and 3 only","1, 3 and 4 only","1, 2, 3 and 4","2 and 4 only"],"answer":0,"explanation":"Section 9: a holder in due course takes for consideration, before maturity, and without sufficient cause to believe in a defect of title. He need not be the payee; most holders in due course are endorsees.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-487","question":"Which statements comparing an LLP with a general partnership firm in India are correct?\n1. Registration of an LLP is compulsory, while registration of a partnership firm is optional.\n2. A body corporate can be a partner of an LLP.\n3. A partnership firm is a legal person separate from its partners.\n4. In an LLP, a partner is not personally liable for another partner's wrongful act.","options":["1 and 2 only","1, 2, 3 and 4","2, 3 and 4 only","1, 2 and 4 only"],"answer":3,"explanation":"An LLP comes into existence only on incorporation, can have bodies corporate as partners, and shields partners from each other's wrongful acts. A partnership firm is merely a collective name for its partners, not a separate legal person.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-488","question":"Which statements about GST are correct?\n1. Exports of goods and services are zero-rated.\n2. A registered person must reverse input tax credit attributable to exempt supplies.\n3. Nil-rated supplies are treated as exempt supplies for input tax credit purposes.\n4. A person making only wholly exempt supplies must register once its turnover crosses the threshold.","options":["1 and 2 only","1, 2 and 3 only","1, 2, 3 and 4","2, 3 and 4 only"],"answer":1,"explanation":"Exports are zero-rated (Section 16, IGST Act). 'Exempt supply' includes nil-rated and non-taxable supplies, and credit attributable to them is not available. Section 23 frees a person engaged exclusively in wholly exempt or non-taxable supplies from registration.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-489","question":"An agreement provides that A will indemnify B against all liability arising from a transaction B enters into at A's request. B incurs a liability that has become absolute, but he has not yet paid anything. Can B require A to meet it?","options":["No; an indemnity holder can claim only after he has actually paid","No; only damages for breach of contract are available","Yes; he can make A discharge an absolute liability before paying","Yes, but only after a court decree is passed against B"],"answer":2,"explanation":"In Gajanan Moreshwar v Moreshwar Madan, the Bombay High Court held that an indemnity holder whose liability has become absolute can call upon the indemnifier to save him from it, without first paying. 'Indemnity is not necessarily given by repayment after payment.'","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-490","question":"A borrows a car from B, who did not own it but had borrowed it from its true owner C without authority to lend. C recovers the car from A, and A suffers loss on a pre-booked trip. Against whom does A have a claim under the bailment provisions?","options":["Against B, who is liable as he was not entitled to bail the car","Against C, the true owner who took the car back","Against nobody, because the bailment was purely gratuitous and informal","Against both B and C jointly and severally"],"answer":0,"explanation":"Section 164: the bailor is responsible to the bailee for any loss the bailee may sustain because the bailor was not entitled to make the bailment, or to receive back the goods, or to give directions about them.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-491","question":"A buyer contracts to buy a specific antique painting, which the seller then refuses to deliver. Damages would not compensate the buyer because the painting is unique. What remedy can the court give under the Sale of Goods Act?","options":["Only damages measured by the market price","Only a refund of any price already paid","Specific performance, ordering delivery","A declaration that the contract is void"],"answer":2,"explanation":"Section 58 lets the court, in a suit for breach of contract to deliver specific or ascertained goods, direct that the contract be performed specifically. Unique goods are the classic case where damages are inadequate.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-492","question":"A cheque crossed generally is presented at the counter of the drawee bank, which pays cash across the counter to the person presenting it. The person was not entitled to it. What is the bank's position?","options":["The bank is protected because it paid the bearer","The bank is protected if it checked the presenter's identity","Only the drawer bears the loss, as he issued the cheque","Liable to the true owner, as it must pay only a banker"],"answer":3,"explanation":"Under Sections 126 and 129, a cheque crossed generally may be paid only to a banker. A paying bank that pays otherwise is liable to the true owner for any loss suffered as a result.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-493","question":"Under Section 10 of the Negotiable Instruments Act, which element is NOT part of 'payment in due course'?","options":["The payment is made in accordance with the apparent tenor of the instrument","The payment is made on the due date or after it in all cases, whatever the instrument's tenor","The payment is made in good faith and without negligence","The payment is made to a person in possession under circumstances not giving reasonable grounds to believe he is not entitled"],"answer":1,"explanation":"Payment in due course means payment in accordance with the apparent tenor of the instrument, in good faith and without negligence, to any person in possession of it in circumstances that do not afford a reasonable ground for believing he is not entitled to receive it.","difficulty":"moderate","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-494","question":"A bill of exchange is drawn in Delhi on a merchant who lives in London, and it is made payable in Mumbai. Under the Negotiable Instruments Act, is it an inland instrument?","options":["Yes; it is drawn in India and made payable in India","No; it is drawn on a person resident outside India","No; it is a foreign instrument because the acceptor is abroad","It is inland only if accepted in India"],"answer":0,"explanation":"Section 11: an instrument drawn or made in India and either made payable in India or drawn on a person resident in India is inland. Being drawn in India and payable in India is enough, even though the drawee lives abroad.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-495","question":"Under Section 271 of the Companies Act, 2013 as it now stands, which of these is NOT a ground on which the Tribunal may wind up a company?","options":["The company has resolved by special resolution to be wound up by the Tribunal","The company is unable to pay its debts","The company has defaulted in filing its financial statements or annual returns for five consecutive financial years","The Tribunal is of the opinion that it is just and equitable to wind up the company"],"answer":1,"explanation":"Since the Insolvency and Bankruptcy Code came in, inability to pay debts has been removed from Section 271; insolvency is dealt with under the IBC. The other three remain grounds for winding up by the Tribunal.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-496","question":"A non-resident company receives royalty from an Indian company for the use of a patent in the Indian company's business carried on in India. Is the royalty taxable in India in the non-resident's hands?","options":["No; a non-resident is never taxed on royalty","No, unless the royalty is received in India","Yes, but only if the non-resident has an office in India","Yes; such royalty is deemed to accrue or arise in India"],"answer":3,"explanation":"Royalty payable by a resident for rights used in a business carried on in India is deemed to accrue or arise in India, so it is taxable in the non-resident's hands (subject to any tax treaty), wherever it is paid.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-497","question":"Which statements about income tax are correct? (Assume the usual rules.)\n1. Agricultural income from land in India is exempt.\n2. A partner's share of profit from a firm assessed as a firm is exempt in his hands.\n3. Salary received by a partner from his firm is taxed under the head 'Salaries'.\n4. A casual winning from a lottery is taxed under 'Income from other sources'.","options":["1 and 2 only","1, 2, 3 and 4","1, 2 and 4 only","2, 3 and 4 only"],"answer":2,"explanation":"Agricultural income is exempt; a partner's profit share is exempt because the firm pays tax on it; casual winnings are 'other sources'. A partner is not an employee, so his salary from the firm is business income, not 'Salaries'.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-498","question":"A sells his shop's stock to B for ₹3 lakh, with B agreeing to pay A's creditor C directly. B fails to pay. Can C sue B?","options":["Yes; the contract was made expressly for C's benefit","No; C is a stranger to it, but can still sue A on the debt","Yes; consideration moved from A for C's benefit","No; and C also loses his original claim against A for the debt"],"answer":1,"explanation":"Under the doctrine of privity, only a party to a contract can sue on it, even if it benefits a third person. C is not a party (no trust, family arrangement, acknowledgment or estoppel exception applies), so he must recover from A, his debtor.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-499","question":"A surety's guarantee states that his liability shall not exceed ₹2 lakh, though the loan to the principal debtor is ₹5 lakh. The debtor defaults on the full amount. How much can the creditor recover from the surety?","options":["₹5 lakh","₹3 lakh","Nothing until the creditor exhausts remedies against the debtor","₹2 lakh"],"answer":3,"explanation":"Section 128 makes the surety's liability co-extensive with the principal debtor's 'unless it is otherwise provided by the contract'. A surety may limit his liability; here it is capped at ₹2 lakh. The creditor need not first sue the debtor.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-500","question":"At an auction of goods in lots, the auctioneer knocks down Lot 7 to B. Before B pays, the seller wants to withdraw Lot 7 because a higher private offer has come in. What is the legal position?","options":["The seller may withdraw it, as property passes only when B pays","The sale is complete only when every lot in the auction is sold","The sale of Lot 7 was complete at the fall of the hammer","The seller may withdraw it if he compensates B for lost bargain"],"answer":2,"explanation":"Section 64: where goods are put up in lots, each lot is the subject of a separate contract of sale, and the sale is complete when the auctioneer announces its completion by the fall of the hammer. Until then, a bid may be withdrawn.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-501","question":"A company wants to accept deposits from its members. Which statement best reflects the Companies Act, 2013?","options":["Yes, after a general-meeting resolution, circular, repayment reserve and ROC filing","Yes, freely and without conditions, because deposits from members are outside the deposit rules","No; only banking companies and NBFCs may accept any kind of deposit","Yes, by a board resolution alone, as members are not the general public for this purpose"],"answer":0,"explanation":"Section 73(2) allows a company to accept deposits from members only by passing a resolution in general meeting and complying with conditions such as issuing a circular, filing it with the Registrar, depositing a prescribed amount in a deposit repayment reserve and, where required, giving security or insurance.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-502","question":"How does a contract of guarantee differ from a contract of indemnity under the Indian Contract Act?","options":["A guarantee has two parties and an indemnity three, so a surety is never primarily liable","In both, the promisor's liability is secondary and arises only on another's default","A guarantee must be in writing, while an indemnity may be oral under the Act","A guarantee has three parties with secondary liability; an indemnity two with primary"],"answer":3,"explanation":"In a guarantee, the surety answers for the principal debtor's default to the creditor, so his liability is collateral. In an indemnity, the indemnifier promises the indemnity-holder directly to save him from loss, an original and primary liability. Both may be oral or written.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-503","question":"A witness who has been summoned by a court to give evidence is promised ₹10,000 by a party if he attends and testifies. He attends and testifies. Can he enforce the promise?","options":["No; doing what he was already legally bound to do is not consideration","Yes; attending court was an act done at the promisor's desire","Yes; any promise made for a lawful act is enforceable by the promisee","No; a promise to pay a witness must be in writing and registered"],"answer":0,"explanation":"Performing a pre-existing public duty imposed by law is not good consideration for a fresh promise (as in Collins v Godefroy). The witness gave nothing beyond what the summons already required.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-504","question":"B, an adult, agrees with A that in return for ₹5 lakh she will not marry anyone for ten years. Later she marries and A sues to recover the money. What is the status of the agreement?","options":["Valid, because B received consideration and was an adult when she agreed","Void, as an agreement in restraint of the marriage of an adult","Voidable at A's option, since B herself committed the breach first","Valid, because the restraint was only partial and for a limited time"],"answer":1,"explanation":"Section 26 makes every agreement in restraint of the marriage of any person other than a minor void. Unlike the exception in Section 27 for trade, there is no exception for partial or reasonable restraints.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-505","question":"A partnership deed says that, while the partnership lasts, no partner will carry on any business other than that of the firm. One partner argues that this clause is void under Section 27 of the Contract Act. Is he right?","options":["Yes; every agreement in restraint of trade is void in India, without exception","Yes, unless the restraint is limited to the same city as the firm's business","No; the Partnership Act lets partners agree not to run any rival business","No, but only if the firm is registered with the Registrar of Firms"],"answer":2,"explanation":"Section 11(2) of the Partnership Act saves such a covenant despite Section 27 of the Contract Act. Similar statutory exceptions allow reasonable restraints on outgoing partners and on the sale of goodwill.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-506","question":"A loan agreement says interest is 12% a year, but if the borrower defaults, interest on the whole loan will be 24% from the date of the loan. How will an Indian court treat the 24% clause?","options":["As liquidated damages, recoverable in full since both parties agreed the rate","As a penalty, so the lender gets only reasonable compensation up to that sum","As void in its entirety, so even the agreed 12% interest is lost","As valid and enforceable, because the borrower consented to it in writing"],"answer":1,"explanation":"The Explanation to Section 74 says a stipulation for increased interest from the date of default may be a stipulation by way of penalty. Here the increase even applies backwards from the date of the loan, so the court awards only reasonable compensation not exceeding the stated sum.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-507","question":"A lets his manager B regularly buy goods on credit from C in A's name, and A always pays. A then dismisses B but tells no one. B buys more goods from C in A's name and disappears. Is A liable to C?","options":["No; B's authority ended with his dismissal, whatever C knew","No, unless A later ratifies B's purchase from C","Yes; A's conduct made C believe B still had authority","Yes, but only for half the price, as both A and C were careless"],"answer":2,"explanation":"Section 237 binds a principal who, by words or conduct, has induced third persons to believe that acts were within the agent's authority. A's earlier course of dealing and silence about the dismissal create such an apparent authority.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-508","question":"A carrier transporting fruit for a trader finds that the fruit will rot within hours because of an unexpected road closure, and it cannot reach the trader for instructions. It sells the fruit at the best price available nearby. What is the legal position?","options":["The carrier acted as an agent of necessity and the sale binds the owner","The carrier is liable for conversion because it had no authority to sell","The sale is void and the buyer must return the fruit","The carrier must pay the full contract value of the fruit"],"answer":0,"explanation":"Section 189 gives an agent authority, in an emergency, to do all acts to protect his principal from loss that a person of ordinary prudence would do in his own case. Genuine emergency, inability to communicate and good faith make the sale binding.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-509","question":"Which of these is NOT 'goods' under the Sale of Goods Act, 1930?","options":["Growing crops agreed to be severed before sale","Shares in a company","Goodwill of a business","A debt owed to the seller by a third person"],"answer":3,"explanation":"Section 2(7) defines goods as every kind of movable property other than actionable claims and money, and includes stocks and shares, growing crops and things attached to the land agreed to be severed. A debt is an actionable claim; goodwill is treated as goods.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-510","question":"A farmer contracts in March to sell to B the wheat he expects to harvest in May from his field. What is the nature of the contract in March?","options":["A sale, because the wheat from an identified field is specific goods","Void, because a contract cannot be made for goods that do not yet exist","An agreement to sell, because property in future goods cannot pass yet","A contingent sale that becomes complete only when B pays the price"],"answer":2,"explanation":"Section 6(3): where by a contract of sale the seller purports to effect a present sale of future goods, the contract operates as an agreement to sell. Property passes later, when the goods are produced and appropriated.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-511","question":"A contract of sale fixes payment within 30 days. The buyer pays on day 35. Can the seller treat the contract as at an end and refuse delivery, the contract being silent about the importance of the payment date?","options":["No; unless a different intention appears, time of payment is not of the essence","Yes; any delay in payment allows the unpaid seller to rescind at once","Yes, if the delay exceeds 10% of the credit period agreed between the parties in the contract","No, because the seller must deliver before receiving payment in every case"],"answer":0,"explanation":"Section 11: unless a different intention appears from the contract, stipulations as to time of payment are not deemed to be of the essence of a contract of sale. The seller may claim interest or damages, but cannot rescind merely for late payment.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-512","question":"Goods sold to B are lying in a warehouse. The seller gives B a delivery order, and the warehouse keeper acknowledges to B that he now holds the goods on B's behalf. The goods are not moved. Has delivery taken place?","options":["No; delivery requires physical transfer","No, until B removes the goods","Yes, but only symbolic delivery, which passes no rights","Yes; this is constructive delivery by attornment"],"answer":3,"explanation":"Delivery may be actual, symbolic or constructive. When a third person in possession acknowledges to the buyer that he holds the goods on the buyer's behalf, there is constructive delivery (attornment), even though nothing is moved.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-513","question":"A seller fails to deliver 1,000 units contracted at ₹50 each. On the delivery date the market price is ₹58. The buyer has not paid anything. What damages can the buyer ordinarily recover for non-delivery?","options":["₹58,000","₹8,000","₹50,000","₹4,000"],"answer":1,"explanation":"Under Section 57 the usual measure is the difference between the contract price and the market price on the date fixed for delivery: (58 − 50) × 1,000 = ₹8,000, which lets the buyer buy substitutes at no extra cost.","difficulty":"moderate","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-514","question":"A cheque dated 30 April is handed to the payee on 10 April. What is its legal status?","options":["It is void, because a cheque must bear the date on which it is issued","It is valid, but the bank may pay it only on or after 30 April","It is payable immediately on 10 April, as the date is merely descriptive","It operates as a promissory note until 30 April and a cheque thereafter"],"answer":1,"explanation":"A post-dated cheque is a valid cheque payable on or after its date; until then it is in effect a bill of exchange not yet due. It can be negotiated, and the statutory period for presentment runs from the date it bears.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-515","question":"A cheque payable to 'Ravi or order' is endorsed by Ravi 'Pay Sunil only' and signed. What is the effect?","options":["Restrictive: Sunil can receive payment but cannot negotiate it further","Blank: Ravi's signature alone converts the cheque into one payable to bearer","Conditional: the word 'only' imposes a condition, so it is void","Full: Sunil becomes a holder in due course and can negotiate freely"],"answer":0,"explanation":"Section 50: an endorsement may restrict further negotiation by express words, such as 'Pay to C only'. The endorsee gets the right to receive payment, but the instrument is no longer negotiable.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-516","question":"An endorser writes 'Notice of dishonour waived' above his signature while endorsing a bill. What does this mean?","options":["He will not be liable at all if the bill is later dishonoured","The bill cannot be negotiated beyond the next endorsee","He is liable on dishonour only if a formal protest is made","He stays liable on dishonour even without notice of it"],"answer":3,"explanation":"This is a facultative endorsement: the endorser gives up a right that the law gives him (notice of dishonour). Section 98 also says no notice of dishonour is needed when the party entitled to it has waived it.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-517","question":"A drawer issues a cheque and then closes his bank account before it is presented. The cheque is returned 'account closed'. Can the payee prosecute under Section 138 of the Negotiable Instruments Act, if the other conditions are met?","options":["No; Section 138 covers only returns marked 'funds insufficient'","No; the drawer is excused because the account no longer exists","Yes; 'account closed' is treated as a species of insufficient funds","Yes, but only if the account was closed after the cheque was presented"],"answer":2,"explanation":"The Supreme Court has held (NEPC Micon v Magma Leasing) that closing the account before presentment is a species of the drawer's account being insufficient, so a dishonour with 'account closed' attracts Section 138.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-518","question":"A bearer cheque and an order cheque are each handed over by their holders to new transferees. What does negotiation require in each case?","options":["Bearer cheque: delivery alone; order cheque: endorsement and delivery","Both need endorsement and delivery","Both need delivery alone","Bearer cheque: endorsement and delivery; order cheque: delivery alone"],"answer":0,"explanation":"Section 47: an instrument payable to bearer is negotiated by mere delivery. Section 48: an instrument payable to order is negotiated by the holder's endorsement and delivery.","difficulty":"moderate","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-519","question":"A shareholder of a public company wants to sell his shares to an outsider; the directors dislike the buyer. Under the Companies Act, 2013, what is the general position on transfer?","options":["The board may refuse any transfer at its discretion, and there is no appeal","Any transfer to an outsider needs the consent of all existing members","Shares are freely transferable; a refusal can be appealed to the NCLT","Public company shares can be transferred only to existing members"],"answer":2,"explanation":"Section 58: the securities of a public company are freely transferable (contracts between specific persons may still be enforced). If a company refuses or fails to register a transfer without sufficient cause, the transferee may appeal to the Tribunal.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-520","question":"In a company limited by guarantee, what is the liability of a member?","options":["Up to the amount unpaid on his shares, as in a company limited by shares","Unlimited, like a partner, since there is no share capital to limit it","Nothing, because a guarantee company's creditors look only to its assets","Up to the sum he undertook in the memorandum to contribute on winding up"],"answer":3,"explanation":"Section 2(21): in a company limited by guarantee, members' liability is limited to the amount each undertakes in the memorandum to contribute in the event of winding up. If it also has share capital, the unpaid amount on shares is payable too.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-521","question":"A subsidiary wants to buy shares in its own holding company as an investment. Is this allowed under the Companies Act, 2013?","options":["Yes, with a board resolution and approval of the holding company's board","No; save as legal representative, trustee or similar cases, it is barred","Yes, up to 10% of the holding company's paid-up capital","Yes, provided the shares are bought through a recognised stock exchange"],"answer":1,"explanation":"Section 19 prohibits a company from holding shares in its holding company and the holding company from allotting or transferring its shares to its subsidiary, subject to exceptions such as holding as a legal representative of a deceased member or as a trustee.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-522","question":"Which of these powers can the board of a company exercise only by a resolution passed at a board meeting, not by circulation?","options":["Approving the company's annual holiday list for all its offices","Approving a routine purchase order within an approved budget","Approving the appointment of a junior accountant at a branch","Making calls on shareholders for money unpaid on shares"],"answer":3,"explanation":"Section 179(3) lists powers to be exercised only by resolutions at board meetings, including making calls, authorising buy-back, issuing securities, borrowing, investing funds, granting loans, approving financial statements and approving mergers or takeovers.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-523","question":"A member of a Hindu undivided family receives ₹2 lakh from the HUF out of its income. Assume the usual rules. Is it taxable in the member's hands?","options":["No; a sum a member receives out of HUF income is exempt in his hands","Yes, as income from other sources in the member's own hands","Yes, as a sum received without consideration from a non-relative above ₹50,000","Only the part of the receipt above ₹50,000 is taxable in his hands"],"answer":0,"explanation":"Amounts received by an individual as a member of an HUF out of the family's income (or out of the income of an impartible estate) are exempt, because the HUF is itself taxed on that income.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-524","question":"A dealer in shares sells shares held as stock-in-trade at a profit. Assume the usual definitions. Under which head is the profit taxed?","options":["Capital gains, short-term or long-term depending on the holding period","Business or profession, as stock-in-trade is not a capital asset","Income from other sources, as profit on a financial asset","Exempt, because profits on listed shares have already borne STT"],"answer":1,"explanation":"Stock-in-trade is excluded from the definition of 'capital asset', so its sale gives business income. The same shares held as investments by the same person would give capital gains.","difficulty":"moderate","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-525","question":"Assume unlisted shares are long-term capital assets only if held for more than 24 months. An investor received bonus shares in an unlisted company 20 months ago on original shares bought 5 years ago, and sells the bonus shares now. How is the gain classified?","options":["Long-term, because the original shares were held for 5 years","Long-term, because bonus shares are treated as acquired with the original shares","Short-term, because the holding period of bonus shares runs from their allotment","It is not a capital gain at all, because bonus shares cost nothing"],"answer":2,"explanation":"Bonus shares are a separate asset whose holding period starts on the date of allotment, with cost generally taken as nil. Held for 20 months, they are short-term under the stated rule.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-526","question":"A trader buys and sells listed shares on the same day without taking delivery (intra-day trading). Assume the usual rules. How is the result treated?","options":["As short-term capital gain or loss, since shares are capital assets","As speculative business income or loss, kept apart from other business","As income from other sources, since no delivery was ever taken","As ordinary non-speculative business income, like delivery trades"],"answer":1,"explanation":"A transaction in shares that is settled otherwise than by actual delivery is speculative. Speculation profit is business income, and speculation losses can be set off only against speculation profits.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-527","question":"A business is set up on 10 October and starts trading at once. Under the income-tax rules, what is the period of its first year (previous year / tax year) for computing income?","options":["The full year from 1 April to the next 31 March","Twelve months running from 10 October","From 10 October to 31 December only","From 10 October to the following 31 March"],"answer":3,"explanation":"For a newly set-up business or a new source of income, the first year begins on the date of setting up (or the date the new source comes into existence) and ends on the next 31 March.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-528","question":"A supplier dispatches goods on 5 May but issues the tax invoice only on 12 May. Under the CGST Act, when should the invoice for a supply of goods involving movement normally have been issued?","options":["At or before removal of the goods, i.e. by 5 May","Within 30 days of removal, as allowed for all supplies","Within 7 days of removal, under the invoice rules","Only on receipt of payment for the goods supplied"],"answer":0,"explanation":"Section 31(1) requires a tax invoice for goods to be issued before or at the time of removal of goods for supply where supply involves movement, or of delivery in other cases. The 30-day window applies to services.","difficulty":"moderate","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-529","question":"A registered person buys a machine that it will use exclusively to make goods that are fully exempt from GST. Can it take input tax credit on the machine?","options":["Yes, because capital goods always carry full credit","Yes, but only 50% of the tax","No; credit is not available on capital goods used exclusively for exempt supplies","Yes, if it later starts taxable supplies within a year, without any reversal rules"],"answer":2,"explanation":"Section 17(2) restricts credit to the extent of use for taxable supplies (including zero-rated). Capital goods used exclusively for exempt supplies carry no credit; those used for both are apportioned under the rules.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-530","question":"Under the Consumer Protection Act, 2019, a person buys a machine to run a small tailoring business that he operates himself to earn his livelihood by self-employment. Is he a 'consumer'?","options":["Yes; goods bought only to earn a livelihood by self-employment are not commercial","No; anything bought for running a business is for a commercial purpose","Yes, but only if the machine's price is below the ₹1 lakh threshold","No; only individuals buying goods for personal or household use can be consumers under the Act"],"answer":0,"explanation":"The definition excludes a person who obtains goods for resale or a commercial purpose, but the Explanation says 'commercial purpose' does not include use by a person of goods bought exclusively to earn his livelihood by self-employment.","difficulty":"hard","source":"CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-531","question":"A singer contracts to sing at B's theatre on two nights a week for two months. She deliberately skips one night. B lets her sing on later nights without objecting, and then wants to end the contract because of the missed night. What is the position?","options":["B can end the contract at any time, since her refusal to sing was deliberate","B can neither end the contract nor claim any compensation for the night","B, having acquiesced, cannot end it now but can claim compensation","The contract became void the moment she failed to sing on the first night"],"answer":2,"explanation":"Section 39 lets the promisee put an end to the contract when the promisor refuses to perform in its entirety, unless he has signified, by words or conduct, his acquiescence in its continuance. The illustration to the section covers exactly this; compensation remains available.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-532","question":"A pays B ₹1 lakh, for which B promises to deliver later either 100 bags of rice or a quantity of smuggled goods, at A's option. What is the legal position?","options":["The whole agreement is void because one of the alternatives is illegal","A may insist on the smuggled goods because he has already paid the price","B may choose which alternative to perform, since the option is a mere formality","A valid contract to deliver the rice; the smuggled-goods branch is void"],"answer":3,"explanation":"Section 58: in an alternative promise where one branch is legal and the other illegal, only the legal branch can be enforced. The illegality of one alternative does not taint the other.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-533","question":"B contracts to build a boat for C, with C paying in instalments as stages are completed; A is surety to C for B's due performance. Without A's knowledge, C pays B the last two instalments in advance. B abandons the work. Is A liable?","options":["No; prepayment impaired the surety's eventual remedy, so A is discharged","Yes; a prepayment is a private matter between the creditor C and the debtor B","Yes, but only for the instalments that C had not paid in advance","No, but only if A had expressly forbidden C to make any prepayment"],"answer":0,"explanation":"Section 139: if the creditor does any act inconsistent with the surety's rights, or omits to do an act his duty requires, and the surety's eventual remedy against the debtor is impaired, the surety is discharged. Prepayment removed B's incentive to finish.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-534","question":"B borrows A's car for a weekend and promises to return it by Sunday evening. B keeps it until Tuesday; on Monday, through no fault of B, it is damaged in a sudden flood. Who bears the loss?","options":["A, because the flood was an act of God for which no bailee is liable","B, since a bailee keeping goods past the agreed time bears any loss","A and B equally, since neither of them caused the flood damage","A, because the bailment was gratuitous and B owed only slight care"],"answer":1,"explanation":"Section 161: if, by the bailee's default, the goods are not returned at the proper time, he is responsible to the bailor for any loss, destruction or deterioration from that time, regardless of care or fault.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-535","question":"A buyer receives goods and neither tells the seller that he rejects them nor returns them. Four months later, after reselling part of them, he complains that they were not as ordered. What is the position under the Sale of Goods Act?","options":["He is deemed to have accepted them; he may claim damages but not reject","He may still reject them because he never signed an acceptance note","He may reject the unsold part and keep only what he has resold","He has no remedy at all, because reselling waived every breach"],"answer":0,"explanation":"Section 42: the buyer is deemed to have accepted goods when he intimates acceptance, does an act inconsistent with the seller's ownership (such as reselling), or retains them beyond a reasonable time without intimating rejection. After acceptance, a breach of condition can be treated only as a breach of warranty.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-536","question":"Goods are sold on three months' credit. The buyer has not taken them away, and before the credit period ends the buyer becomes insolvent. Can the unpaid seller, still in possession, refuse delivery?","options":["No; the lien stays suspended until the agreed credit period ends","Yes; the buyer's insolvency revives the lien during the credit period","Yes, but only once the three-month credit period has run out","No; property has already passed to the buyer, so the seller must deliver"],"answer":1,"explanation":"Section 47(1): an unpaid seller in possession has a lien where goods are sold without credit, where sold on credit and the term has expired, or where the buyer becomes insolvent. Insolvency revives the lien during the credit period.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-537","question":"A cheque is presented for payment much later than a reasonable time after its issue. Before presentment, the drawee bank fails, and the payee receives only part of the amount. Under the Negotiable Instruments Act, what happens to the drawer's liability?","options":["The drawer is fully discharged, because the cheque was presented late","The drawer remains fully liable, because the bank's failure is not his fault","The drawer is discharged only to the extent of the damage the delay caused","The drawer is discharged only if the cheque had been crossed 'account payee'"],"answer":2,"explanation":"Section 84: where a cheque is not presented within a reasonable time and the drawer suffers actual damage through the delay (such as the bank's failure), he is discharged to the extent of that damage. The holder becomes a creditor of the bank for the remainder.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-538","question":"A company's paid-up equity capital is ₹50 crore and its free reserves are ₹30 crore. Up to what amount can it buy back its shares on the authority of a board resolution alone, without a special resolution of members?","options":["₹20 crore","₹5 crore","₹12.5 crore","₹8 crore"],"answer":3,"explanation":"Section 68: buy-back up to 25% of paid-up capital and free reserves (here ₹20 crore) needs a special resolution, but up to 10% of total paid-up equity capital and free reserves may be authorised by a board resolution: 10% × 80 = ₹8 crore.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-539","question":"A shareholder asks to inspect the minutes of the company's board meetings. Is the company obliged to allow this?","options":["Yes; members may inspect the minutes of all board and general meetings","No; members may inspect general-meeting minutes but not board minutes","Yes, if the shareholder holds at least 10% of the paid-up share capital","No; even the minutes of general meetings are confidential to members"],"answer":1,"explanation":"Section 119 gives members the right to inspect, and get copies of, minutes of general meetings. Board minutes are kept at the registered office but are not open to members' inspection (directors and auditors may see them).","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-540","question":"A company repaints its office building and repairs its plumbing, charging the cost to the profit and loss account as routine maintenance. Is input tax credit available on the tax paid on these services?","options":["No; all credit on goods or services relating to a building is blocked","No, unless the building is used wholly for making exempt supplies","Only 50% of the credit is available, the rest being an expense","Yes; repairs are blocked only to the extent they are capitalised"],"answer":3,"explanation":"The Explanation to Section 17(5) defines 'construction' to include reconstruction, renovation, additions, alterations or repairs to the extent of capitalisation to the immovable property. Revenue repairs written off are not blocked.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-541","question":"A trader under the GST composition scheme receives legal services from an advocate, on which tax is payable under reverse charge. What is its position?","options":["It is exempt from reverse charge because it is a composition dealer","It pays the reverse-charge tax at its own composition rate","It pays the reverse charge at normal rates and gets no credit","It pays the tax and may use it as input tax credit later"],"answer":2,"explanation":"A composition taxpayer must still pay tax on inward supplies liable to reverse charge, at the applicable normal rates and not at the composition rate, and it cannot take input tax credit, so the tax becomes a cost.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-542","question":"A farmer also runs a shop. This year his agricultural operations (income from which is exempt) show a loss of ₹1 lakh and his shop earns ₹4 lakh. Assume the usual rules. Can he set off the agricultural loss against the shop income?","options":["No; a loss from a source whose income is exempt cannot be set off","Yes, under inter-head set-off against the shop's business income","Yes, but only half of it, as agriculture is partly integrated","No, but it can be carried forward and set off against future shop profits"],"answer":0,"explanation":"Set-off is allowed only for losses from sources whose income would be taxable. Agricultural income is exempt, so its losses are ignored for computing taxable income (they matter only in the rate-computation for partial integration).","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-543","question":"A business has unabsorbed depreciation from earlier years. Assume the usual rules for unabsorbed depreciation. Which statement is correct?","options":["It can be set off only against business income and lapses after 8 assessment years, like business losses","It can be set off against any head except salaries and carried forward indefinitely","It can be set off against salary income as well, like any other loss","It lapses entirely if the return of income for the loss year is filed late"],"answer":1,"explanation":"Unabsorbed depreciation is added to the next year's depreciation allowance, so it can be set off against any head except 'Salaries' and carried forward indefinitely. Unlike business losses, it is not lost for a belated return.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-544","question":"A creditor of a partnership firm is owed ₹10 lakh. Partner X is wealthy; the other partners have little. Can the creditor recover the whole ₹10 lakh from X alone?","options":["No; X is liable only for his share in the profit-sharing ratio of the firm","No; the creditor must first exhaust the firm's assets and then sue all partners together","Yes, but only if X personally signed the contract with the creditor","Yes; each partner is liable jointly and severally for the firm's acts"],"answer":3,"explanation":"Section 25 of the Partnership Act makes every partner liable, jointly with all the other partners and also severally, for all acts of the firm done while he is a partner. X may then claim contribution from the others.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-545","question":"A partner, while handling a client's matter in the ordinary course of the firm's business, negligently causes the client a loss of ₹5 lakh. Who is liable to the client?","options":["The firm, and so every partner, to the same extent as the negligent one","Only the negligent partner, as negligence is a personal wrong","Only the firm's assets, not the partners in their personal capacity","The partners in proportion to the capital each has contributed to the firm"],"answer":0,"explanation":"Section 26: where a partner's wrongful act or omission in the ordinary course of business causes loss to a third party, the firm is liable to the same extent as the partner. Under Section 25 that liability is joint and several among all partners.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-546","question":"Partner P transfers his whole interest in a firm to T, an outsider. The other partners continue the business. Which rights does T get while the firm continues?","options":["All the rights of a partner, including a say in managing the business","No rights at all until the firm is dissolved and its assets are distributed","P's share of profits as agreed, but no say in management or accounts","The right to inspect the books and demand accounts, but no share of profits"],"answer":2,"explanation":"Section 29: a transferee of a partner's interest is entitled to receive the transferor's share of profits and must accept the account of profits agreed by the partners; he cannot interfere in the conduct of business, require accounts or inspect the books. On dissolution he gets the transferor's share of assets.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-547","question":"Which statement about voidable and void contracts is correct?","options":["A voidable contract is void from the start but may later be ratified by the party who was misled","A voidable contract is valid until avoided, and a good-faith buyer before then gets title","A void contract binds both parties until a court formally declares it void","Third parties can never get good title to goods held under a voidable contract"],"answer":1,"explanation":"A voidable contract is enforceable at the option of one party and remains valid until he rescinds it. Section 29 of the Sale of Goods Act protects a good-faith buyer who acquires goods from a person holding them under a voidable contract before it is rescinded.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-548","question":"A contract becomes void because of a supervening law. Before that, A had paid B ₹50,000 in advance under it, and B had received it. What must B do?","options":["Keep it, because the contract was valid when the money was paid","Keep half and return half, as the loss is shared by both parties","Restore the ₹50,000 or compensate for it, as an advantage received under it","Return it only if A shows that B was at fault for the contract becoming void"],"answer":2,"explanation":"Section 65: when an agreement is discovered to be void, or a contract becomes void, any person who has received any advantage under it must restore it, or compensate for it, to the person from whom he received it.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-549","question":"B buys a business after A knowingly lies about its profits. B wants both to rescind the contract and to claim damages for expenses wasted. How does fraud differ from innocent misrepresentation here?","options":["In both cases B may only rescind; damages are never available for a false statement","In both cases B may claim damages but must affirm the contract, not rescind it","For fraud B may claim damages only; for misrepresentation he may rescind only","Fraud allows rescission and damages; innocent misrepresentation, rescission only"],"answer":3,"explanation":"Both make the contract voidable (Section 19). Fraud is also a civil wrong (deceit), so damages are available, and Section 19 lets the defrauded party insist on being put in the position he would have been in. Innocent misrepresentation gives rescission without damages.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-550","question":"A company publicly announces a cash prize for anyone who uses its smoke ball as directed and still catches influenza. X does so, catches influenza and claims the prize without ever having told the company she accepted. Is the company liable?","options":["No; acceptance must always be communicated to the offeror before it binds","No; an advertisement to the public is only an invitation to treat","Yes; in a general offer, performing the conditions is itself acceptance","Yes, but only if X bought the smoke ball directly from the company"],"answer":2,"explanation":"A general offer to the world can be accepted by anyone who performs its conditions with knowledge of it (Carlill v Carbolic Smoke Ball Co.; Section 8). The offeror impliedly dispenses with notice of acceptance.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-551","question":"A offers to sell his shares to B on 1 June, stating no time limit. B replies accepting on 1 December, by which time the share price has risen sharply. Is there a contract?","options":["Probably not; an offer with no time limit lapses after a reasonable time","Yes; an offer without a time limit stays open until it is expressly revoked","Yes, because A never communicated any revocation of the offer to B","No, because every acceptance must be given within seven days of the offer"],"answer":0,"explanation":"Section 6(2) says a proposal is revoked by the lapse of the time prescribed for acceptance or, if none is prescribed, by the lapse of a reasonable time without communication of acceptance. What is reasonable depends on the subject matter; for shares it is short.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-552","question":"A retailer emails a wholesaler an order for 100 cartons at the list price. Without replying, the wholesaler dispatches the 100 cartons the next day. When was the order accepted?","options":["Only when the retailer receives the goods at its premises","When the wholesaler dispatched the goods, by conduct","Never, because the wholesaler sent no written reply","Only when the retailer pays the wholesaler's invoice"],"answer":1,"explanation":"Section 8: performance of the conditions of a proposal, or the acceptance of any consideration offered with it, is acceptance. Dispatching the goods in response to an order is acceptance by conduct.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-553","question":"A finds a valuable but perishable consignment of fruit and cannot trace the owner despite reasonable search. What does the Indian Contract Act allow him to do?","options":["Sell them, as they may perish and the owner cannot be found despite diligence","Nothing; he must keep the goods safely until the owner comes to claim them","Keep the goods as his own once a week has passed without the owner appearing","Sell them, but only after first obtaining a magistrate's or a civil court's permission"],"answer":0,"explanation":"Section 169 lets a finder sell the goods when the owner cannot be found with reasonable diligence (or refuses lawful charges) and the goods are in danger of perishing or losing most of their value, or the finder's lawful charges amount to two-thirds of their value.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-554","question":"An estate agent is engaged to sell a house for a commission of 2% 'on completion of the sale'. He finds a buyer, but the buyer backs out before completion through no fault of the owner. Is the agent entitled to commission?","options":["Yes; producing a willing buyer earns the commission","No; commission is due only on completing the sale","Yes, half the commission for the work already done","No, and he must also refund the expenses advanced"],"answer":1,"explanation":"Section 219: in the absence of any special contract, payment for the performance of any act is not due to the agent until the completion of that act. Here the contract itself ties commission to completion of the sale.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-555","question":"Must a contract of guarantee be in writing to be enforceable under the Indian Contract Act?","options":["Yes; an oral guarantee is void","Yes, and it must also be registered","Only guarantees above ₹1 lakh must be written","No; a guarantee may be either oral or written"],"answer":3,"explanation":"Section 126 says a guarantee may be either oral or written. (English law, by contrast, requires written evidence of a guarantee under the Statute of Frauds.)","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-556","question":"Under a hire-purchase agreement, a consumer takes a car, pays a deposit and agrees to pay 24 monthly instalments, with an option to buy for a nominal sum at the end. When does ownership pass?","options":["On delivery of the car, as in any sale on instalments basis","When half of the 24 instalments have been paid","When all instalments are paid and the option exercised","When the hire-purchase agreement is signed by both"],"answer":2,"explanation":"In hire purchase the hirer is a bailee until all instalments are paid and the option is exercised; only then does property pass. In a sale on instalments, by contrast, property passes at once.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-557","question":"A contract of sale says nothing about the order of performance. The buyer refuses to pay until the goods are delivered, and the seller refuses to deliver until he is paid. What does the Sale of Goods Act provide?","options":["The seller must always deliver first and then sue for the price","Delivery and payment are concurrent conditions, unless otherwise agreed","The buyer must always pay first, as the price is the essence of every sale","The contract is void for uncertainty about the order of performance"],"answer":1,"explanation":"Section 32: unless otherwise agreed, delivery of the goods and payment of the price are concurrent conditions: the seller must be ready and willing to give possession in exchange for the price, and the buyer to pay in exchange for possession.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-558","question":"A gives his nephew a cheque for ₹50,000 as a birthday gift. It is dishonoured for insufficient funds. Can the nephew prosecute A under Section 138 of the Negotiable Instruments Act?","options":["No; Section 138 needs a cheque given for a legally enforceable debt","Yes; every cheque dishonoured for insufficient funds attracts Section 138","Yes, provided he sends a demand notice within 30 days of dishonour","No, because cheques exchanged between close relatives are void"],"answer":0,"explanation":"Section 138 requires the cheque to have been drawn for the discharge, wholly or partly, of a legally enforceable debt or other liability. A gift cheque discharges no liability, so the offence is not made out.","difficulty":"hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-559","question":"A promoter buys land for ₹1 crore and, without disclosing this, sells it to the company he is forming for ₹1.5 crore. The company later discovers the facts. What can it do?","options":["Nothing, because the company did not exist when the promoter bought the land","Only sue for the difference if the land turns out to be worth less than ₹1 crore","Nothing, because promoters owe the company duties only after incorporation","Rescind or recover the ₹50 lakh secret profit, as the promoter is a fiduciary"],"answer":3,"explanation":"A promoter owes fiduciary duties to the company he forms and must not make a secret profit. If he does not make full disclosure to an independent board or the members, the company may rescind the contract or recover the profit.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-560","question":"What is the legal effect of a share certificate issued under the company's common seal (or as authorised by the articles)?","options":["It is conclusive proof of title that no one can challenge","It is itself a negotiable instrument passing by delivery","It is prima facie evidence of the holder's title to shares","It has no legal effect, as only the register of members matters"],"answer":2,"explanation":"Section 46(1): a share certificate issued under the common seal, if any, or signed as specified, is prima facie evidence of the title of the person named in it to the shares. It can be rebutted, but the company may be estopped from denying it against a good-faith purchaser.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-561","question":"The board wants to make a call of ₹3 per share on some shareholders of a class but ₹5 per share on others of the same class, all holding identical partly paid shares. Is this valid?","options":["Yes, if the board approves the different amounts","No; calls must be uniform on all shares of a class","Yes, if an ordinary resolution of members approves","Yes, if the shareholders asked to pay more consent"],"answer":1,"explanation":"Section 49 requires calls on shares of the same class to be made on a uniform basis on all such shares; shares of the same nominal value with different amounts paid up are treated as a different class for this purpose.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-562","question":"A director is a partner in a firm with which the company proposes to enter into a contract. At the board meeting considering the contract, what must the director do?","options":["Vote freely, provided he has disclosed his interest beforehand","Nothing, because the contract is with the firm and not with him","Disclose his interest and take no part in discussion or voting","Resign from the board before the meeting considers the contract"],"answer":2,"explanation":"Section 184(2): a director who is concerned or interested in a contract with a firm or other entity in which he is a partner, owner or member must disclose the nature of his interest and shall not participate in that meeting's discussion of it.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-563","question":"Which right does a company's statutory auditor have under the Companies Act, 2013?","options":["A right to vote at general meetings on the adoption of accounts","A right to approve the financial statements before the board signs","A right to appoint and remove the company's internal auditor","A right of access at all times to the books and vouchers"],"answer":3,"explanation":"Section 143(1) gives the auditor a right of access at all times to the books of account and vouchers, whether kept at the registered office or elsewhere, and to require information and explanations. He may attend and be heard at general meetings but has no vote.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-564","question":"A director learns, through his position, of a business opportunity that the company would want and takes it for himself without the board's approval. Which duty has he breached?","options":["The duty to avoid conflicts of interest and not make an undue gain","The duty to attend board meetings and participate in deliberations","The duty to maintain statutory registers at the registered office","No duty, because a business opportunity belongs to whoever finds it"],"answer":0,"explanation":"Section 166 requires a director to act in good faith in the company's interests, avoid situations of conflict of interest, and not achieve or attempt any undue gain or advantage; a director who does so is liable to pay the gain to the company.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-565","question":"A manufacturer replaces a defective part free of charge under the product's warranty, without charging the customer anything. What is the GST position, as clarified by the government?","options":["GST is payable on the open market value of the replaced part","No GST on the replacement, and no reversal of credit on the part","No GST is payable, but credit on the part must be reversed as a free supply","The customer must pay GST on the part under the reverse charge mechanism"],"answer":1,"explanation":"The value of the original supply already covers the warranty obligation, so a replacement under warranty is not a separate taxable supply, and credit on the replacement part is not treated as a free sample to be reversed.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-566","question":"A principal sends goods to its commission agent, who sells them in his own name on the principal's behalf. No consideration passes when the goods move from principal to agent. Is that movement a supply?","options":["Yes; Schedule I treats it as a supply even without consideration","No; without consideration there is no supply under Section 7 at all","No; the principal still owns the goods, so nothing is supplied","No; there is a supply only when the agent sells to a customer"],"answer":0,"explanation":"Schedule I treats supply of goods by a principal to his agent, where the agent undertakes to supply them on behalf of the principal (invoicing in his own name), as a supply even without consideration.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-567","question":"A registered company collects GST from customers on supplies that are actually exempt, and keeps the money. What does the CGST Act require?","options":["It may keep the money, because no tax was legally payable on exempt supplies","It must refund the customers but owes nothing to the government","It need do nothing unless a customer complains to the authorities","It must pay the amount collected as tax to the government"],"answer":3,"explanation":"Section 76: any person who collects an amount from another as tax but does not pay it to the government must pay it, whatever the reason, whether or not the supplies are taxable.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-568","question":"A registered company pays IGST under reverse charge on consultancy services imported from abroad and used for its taxable business. Can it take credit of that IGST?","options":["No; tax paid under reverse charge is always a cost to the recipient","Only after the foreign supplier obtains GST registration in India","Yes; reverse-charge tax used in business is eligible input tax credit","Only half the credit is allowed for imported services of this kind"],"answer":2,"explanation":"Tax paid by the recipient under reverse charge, including IGST on imported services, is input tax credit like any other, subject to the usual conditions. It must be paid in cash first; it then enters the credit ledger.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-569","question":"An Indian citizen working for the Government of India is posted at the Indian embassy in Paris and paid by the Government. Assume the usual rules on deemed accrual. Where is the salary deemed to accrue?","options":["In France, where the services are actually rendered","Nowhere; diplomatic salaries are fully exempt from tax","In India, as Government salary to a citizen abroad","In India only if the salary is credited to an Indian bank account"],"answer":2,"explanation":"Income from salaries payable by the Government to a citizen of India for services rendered outside India is deemed to accrue or arise in India (though specific allowances for service abroad may be exempt).","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-570","question":"Mr H transfers a flat to his wife under an agreement to live apart. She lets it out and earns rent. Assume the clubbing provisions. Whose income is the rent?","options":["Mr H's, because the flat was transferred to his spouse","The wife's, as a transfer to live apart is not clubbed","Half each, since both have an interest in the flat","Mr H's, unless the wife paid adequate consideration"],"answer":1,"explanation":"Income from assets transferred to a spouse without adequate consideration is clubbed, but transfers made in connection with an agreement to live apart are expressly excluded.","difficulty":"very-hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-571","question":"A business makes a provision for doubtful debts of ₹2 lakh and also writes off ₹1 lakh of specific debts as irrecoverable in its accounts. Assume the usual rules. How much is deductible as bad debts?","options":["₹1 lakh – only debts actually written off as irrecoverable","₹3 lakh – the write-off plus the provision for doubtful debts","₹2 lakh – the provision, as it is the larger estimated loss","Nil, until the debtor is declared insolvent by a court"],"answer":0,"explanation":"A bad debt is deductible when it is written off as irrecoverable in the accounts (having earlier been taken into income). A mere provision for doubtful debts is not a write-off, so it is not deductible.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-572","question":"Mr G receives listed shares as a gift from his father, who bought them 3 years ago for ₹2 lakh. G sells them 4 months after the gift for ₹5 lakh. Assume the usual capital-gains rules for gifted assets. What are the cost and the holding period?","options":["Cost nil because it was a gift, and the gain is short-term","Cost equal to market value on the date of gift; short-term","Cost ₹2 lakh, short-term because G held them for 4 months","Cost ₹2 lakh, and the father's holding counts, so long-term"],"answer":3,"explanation":"For assets acquired by gift, the cost is the previous owner's cost and the holding period includes the previous owner's holding. So G's gain is ₹3 lakh, long-term.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-573","question":"Which statement about the composition scheme under GST is correct?","options":["It can make inter-state supplies of goods freely, like any registered person","It issues a tax invoice and charges GST separately to its customers","It cannot collect tax from customers or take input tax credit","It can take input tax credit on capital goods, but not on inputs"],"answer":2,"explanation":"A composition taxpayer pays tax at a concessional rate on turnover, issues a bill of supply, cannot charge tax to customers, cannot take input tax credit and is barred from inter-state outward supplies of goods.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-574","question":"A buyer obtains a car from a seller by paying with a cheque that he knows will bounce. Before the seller rescinds the contract, the buyer sells the car to C, who pays in full and knows nothing of the fraud. Can the seller recover the car from C?","options":["No; C bought in good faith before the voidable contract was rescinded","Yes; a fraudster acquires no title, so he could pass none to C","Yes, provided the seller refunds C the full price that C paid","No, but only if C has already registered the car in his name"],"answer":0,"explanation":"Section 29 of the Sale of Goods Act: where a seller has obtained possession under a contract voidable for fraud but not yet rescinded, a buyer in good faith without notice gets good title. The original seller's remedy is against the fraudster.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-575","question":"A buyer inspects oats offered by a farmer and buys them, wrongly believing they are old oats; the farmer knows they are new oats and of the buyer's mistake but says nothing and made no statement about age. Can the buyer avoid the contract?","options":["Yes; the farmer's silence amounted to fraud in every such case","No; a unilateral mistake about quality alone does not vitiate it","Yes; any mistake of fact by either party makes the contract void","No, but the court must reduce the price to the value of new oats"],"answer":1,"explanation":"Section 22: a contract is not voidable merely because one party was under a mistake as to a matter of fact. Without a duty to speak or a misrepresentation, the seller need not correct the buyer's private belief about quality (Smith v Hughes).","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-576","question":"A guarantees the honesty of C, a cashier employed by B at a fixed salary. Later, without A's consent, B changes C's terms so that C's pay depends on the cash he handles, giving him more temptation. C then embezzles money, both before and after the change. For which losses is A liable?","options":["For all the losses, since C's honesty was guaranteed throughout","For none, because the variance cancels the guarantee from the start","Only those after the variance, because the risk then increased","Only those before the variance, which discharged him thereafter"],"answer":3,"explanation":"Section 133: any variance made without the surety's consent in the terms of the contract between the principal debtor and the creditor discharges the surety as to transactions subsequent to the variance. His liability for earlier defaults remains.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-577","question":"An agent in Mumbai contracts in his own name to buy goods for a merchant resident abroad. Which statement reflects the Indian Contract Act?","options":["The agent is presumed personally liable, as the principal resides abroad","The agent is never personally liable when acting for a disclosed principal","Only the foreign principal can be sued, never the agent who signed","The contract is void because the principal is outside India's jurisdiction"],"answer":0,"explanation":"Section 230 sets out cases where a contract to the contrary is presumed, so the agent is personally liable, including where he contracts for the sale or purchase of goods for a merchant resident abroad, where the principal is undisclosed, and where the principal cannot be sued.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-578","question":"A company that has defaulted in repaying deposits accepted by it, and the default subsists, wants to reduce its share capital under Section 66. What is the position?","options":["A reduction is allowed if the Tribunal confirms it in the usual way","A reduction is allowed by a special resolution alone, without the Tribunal","No reduction can be made while the deposit default continues","A reduction is allowed if depositors are repaid within one year"],"answer":2,"explanation":"The proviso to Section 66(1) says no reduction of share capital shall be made if the company is in arrears in repayment of deposits accepted by it, before or after the Act, or of interest payable on them.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-579","question":"A company proposes to hold its AGM on a national holiday at 7 p.m. at a hotel in the same city as its registered office. Which of these requirements of Section 96 does it break?","options":["Only the place, because the AGM must be held at the registered office itself","Only the time, because AGMs may be held on national holidays","Both the day and the time: no national holiday, and 9 a.m. to 6 p.m.","None, because the board may fix any time, day and place for the AGM"],"answer":2,"explanation":"Section 96(2): an AGM must be called during business hours (9 a.m. to 6 p.m.) on a day that is not a national holiday, at the registered office or another place in the same city, town or village. A hotel in the same city is a valid place, so only the day and the time are wrong.","difficulty":"hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-580","question":"A company is incorporated on 1 December 2025 and its first financial year ends on 31 March 2026. By when must it hold its first annual general meeting, and must it hold one in the calendar year of incorporation?","options":["By 31 December 2026; none is needed in the year of incorporation","By 30 September 2026; an AGM is also needed before 31 December 2025","By 31 March 2027; no AGM is needed before then","By 30 June 2026; an AGM is also needed in calendar year 2025"],"answer":0,"explanation":"Section 96(1): the first AGM must be held within nine months from the close of the first financial year (31 March 2026 + 9 months = 31 December 2026), and it need not be held in the year of incorporation.","difficulty":"very-hard","source":"CA Inter · CS Executive · Big 4"},
  {"id":"mgmt-tax-law-581","question":"A pharma company distributes free samples of a medicine to unrelated doctors for promotion. What is the GST position?","options":["A deemed supply under Schedule I, valued at their open market price","A taxable supply, but credit on the samples is fully allowed","Exempt supplies, so credit is reversed only proportionately","Not a supply at all, and credit on the samples is blocked"],"answer":3,"explanation":"Without consideration, a supply is taxable only if listed in Schedule I (related persons, distinct persons, agents, business assets with credit). Free samples to unrelated persons are not covered, and Section 17(5)(h) blocks credit on free samples.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-582","question":"A company sells goods to its wholly owned subsidiary at an unusually low price, and the price is not the sole consideration because the parties are related. The subsidiary makes mainly exempt supplies. How is the value of supply determined?","options":["Always the invoice price, because both parties freely agreed on that price","Under the related-person valuation rules, generally open market value","The cost of production plus a fixed 5% margin in every such case","Nil, because supplies between group companies are outside GST"],"answer":1,"explanation":"Section 15 accepts transaction value only where the parties are not related and price is the sole consideration. Between related persons, the valuation rules apply: open market value, then like-kind value, then cost-based or residual methods. The invoice-value relief applies only where the recipient can take full credit.","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-583","question":"A company takes out a keyman insurance policy on its managing director's life and claims the premiums as a business expense. Later it receives ₹1 crore on maturity. Assume the usual rules. How is the sum treated?","options":["It is exempt, like any other life-insurance maturity payout","It is a capital receipt, taxed only as capital gains","It is taxable only in the director's hands as salary","It is taxable as business income in the company's hands"],"answer":3,"explanation":"Sums received under a keyman insurance policy, including bonus, are taxable: as business income for the employer, and as salary or other sources in other cases. The usual life-insurance exemption does not cover keyman policies.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-584","question":"A Hindu undivided family is totally partitioned and its land is distributed among the members. Assume the usual capital-gains rules. Is a capital gain charged on the HUF or the members at the time of partition?","options":["Yes; the HUF is taxed on the market value of the land distributed","Yes; each member is taxed on the value of the land he receives","No; distribution of assets on an HUF partition is not a transfer","Only if a member sells his share of land within three years"],"answer":2,"explanation":"Distribution of capital assets on partition of an HUF is excluded from 'transfer' for capital gains. When a member later sells, the cost is the HUF's cost and the HUF's holding period is included.","difficulty":"hard","source":"Big 4 direct tax · CA Inter"},
  {"id":"mgmt-tax-law-585","question":"A flood threatens a partnership firm's stock at night. One partner, unable to reach the others, hires trucks at a premium to move the goods to safety. Is the firm bound by the hire contract?","options":["No; hiring trucks at a premium was beyond his implied authority","Yes; in an emergency a partner may act as a prudent person would","No, unless all the other partners ratify the hire contract later","Only the partner who hired the trucks is bound, personally"],"answer":1,"explanation":"Section 21 of the Partnership Act gives a partner authority, in an emergency, to do all acts for protecting the firm from loss that would be done by a person of ordinary prudence in his own case, acting in similar circumstances; such acts bind the firm.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-586","question":"A debtor's authorised agent writes and signs, on the debtor's behalf, a promise to pay a creditor a debt that has become time-barred. The debtor later refuses to pay. Is the promise enforceable?","options":["Yes; a written promise signed by the debtor's authorised agent is valid","No; only a promise signed personally by the debtor himself is valid","No; a debt that is time-barred can never be revived by any promise","Yes, but only if the creditor gives fresh consideration for the promise"],"answer":0,"explanation":"Section 25(3) validates a written promise, signed by the person to be charged or by his agent generally or specially authorised in that behalf, to pay wholly or in part a debt that the creditor could have enforced but for the law of limitation.","difficulty":"very-hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-587","question":"A wholesaler sells grain by sample. When the bulk arrives, the buyer is given no chance to compare it with the sample before being asked to accept it. Which implied condition protects him?","options":["That the bulk matches the seller's general trade description","That he has a reasonable chance to compare bulk with sample","That the seller has the right to sell the grain to him","That the grain is fit for a purpose made known only later"],"answer":1,"explanation":"Section 17(2) implies three conditions in a sale by sample: the bulk corresponds with the sample in quality, the buyer has a reasonable opportunity of comparing them, and the goods are free from hidden defects rendering them unmerchantable.","difficulty":"hard","source":"CA Inter · Big 4 · MBA placement"},
  {"id":"mgmt-tax-law-588","question":"An order cheque is stolen; the thief forges the payee's endorsement and cashes it at the drawee bank, which pays in due course without negligence and in good faith. Can the drawer make the bank re-credit his account?","options":["Yes; a forged endorsement means the bank never had a mandate to pay","Yes, unless the drawer had crossed the cheque 'account payee'","No, but the drawer can recover the amount from the named payee","No; payment in due course on an apparent endorsement discharges it"],"answer":3,"explanation":"Section 85(1) protects the drawee: where a cheque payable to order purports to be endorsed by or on behalf of the payee, the banker is discharged by payment in due course. The true owner's remedy lies against the thief and later holders.","difficulty":"very-hard","source":"Bank MT · CA Inter"},
  {"id":"mgmt-tax-law-589","question":"Goods imported into India are sold by the importer to a buyer while they are still in a customs-bonded area, before they cross the customs frontier. How is this supply classified under GST law?","options":["As an intra-state supply in the state where the port is located","As an export of goods, so it is zero-rated like any other export from India","As an inter-state supply, until the goods cross the customs frontier","As neither a supply of goods nor of services, in every case"],"answer":2,"explanation":"Section 7(2) of the IGST Act treats the supply of goods imported into India, till they cross the customs frontiers of India, as a supply in the course of inter-state trade or commerce. (Specific transactions such as warehoused-goods sales have their own Schedule III treatment.)","difficulty":"very-hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-590","question":"A small manufacturer sends samples of its new product to a prospective distributor in another state for testing, without charging anything; the distributor is unrelated. Which document should normally accompany the goods?","options":["A delivery challan, as the movement is not a supply","A tax invoice charging IGST on the samples' full value","A bill of supply, since no tax is being charged","A debit note raised on the prospective distributor"],"answer":0,"explanation":"Goods moved for purposes other than supply – such as samples for testing, job work or approval – travel under a delivery challan rather than a tax invoice. There is no consideration and no Schedule I case, so there is no supply.","difficulty":"hard","source":"Big 4 indirect tax · CA Inter"},
  {"id":"mgmt-tax-law-591","question":"A registered used-car dealer opts to pay GST on the margin for second-hand goods on which no input tax credit was taken. Car X was bought from an individual for ₹4,00,000 and sold for ₹4,60,000; Car Y was bought for ₹3,00,000 and sold for ₹2,80,000. Assume GST at 18% is charged on top of the taxable value. What is the total GST payable on the two sales?","options":["₹10,800","₹7,200","₹82,800","₹9,153"],"answer":0,"explanation":"Under the margin scheme the value is selling price − purchase price: ₹60,000 on X, so tax = ₹10,800. A negative margin (Y: −₹20,000) is ignored, not set off, so netting to ₹40,000 (₹7,200) is wrong. ₹82,800 taxes the full price of X, and ₹9,153 treats the margin as tax-inclusive.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-592","question":"Goods with an assessable value of ₹10,00,000 are imported. Assume basic customs duty at 10%, a social welfare surcharge of 10% of the basic customs duty, and IGST at 18%. How much IGST is payable on import?","options":["₹1,80,000","₹1,99,800","₹1,98,000","₹3,09,800"],"answer":1,"explanation":"IGST on imports is levied on assessable value plus customs duties: 10,00,000 + 1,00,000 (BCD) + 10,000 (SWS) = 11,10,000; 18% = ₹1,99,800. ₹1,80,000 ignores the duties, ₹1,98,000 leaves out the surcharge, and ₹3,09,800 is the total of all three levies.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-593","question":"A registered person files a GST return 73 days late. Its tax liability for the month was ₹1,00,000, of which ₹70,000 was paid by using input tax credit and ₹30,000 in cash. Assume interest at 18% a year and that no proceedings have been started. How much interest is payable?","options":["₹3,600","₹2,520","₹1,080","₹5,400"],"answer":2,"explanation":"For a late return, interest is charged only on the part of tax paid in cash: ₹30,000 × 18% × 73/365 = ₹1,080. Charging it on the gross liability gives ₹3,600 and on the credit portion ₹2,520; ₹5,400 is a full year's interest.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-594","question":"A manufacturer buys inputs taxed at 18% GST and sells its finished product at a 5% rate, so unused input tax credit keeps piling up in its credit ledger. What remedy does GST law provide in principle?","options":["The unused credit lapses at the end of each financial year","It can be transferred to any other registered taxpayer for value","It can be used to pay the company's income-tax liability instead","A refund of the credit built up by the inverted duty structure"],"answer":3,"explanation":"Section 54(3) allows a refund of unutilised ITC in two cases: zero-rated supplies without tax, and an inverted duty structure. GST credit cannot be used for income tax, and it does not lapse each year.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-595","question":"A company charged and paid CGST and SGST on a supply, treating it as intra-state. A year later the authorities correctly hold that it was an inter-state supply. What is the position under GST law?","options":["It must pay IGST, without interest, and claim a refund of the CGST and SGST paid","The CGST and SGST already paid are simply adjusted against IGST","It must pay IGST with interest from the original due date, and the CGST and SGST are forfeited","No action is needed, since the total tax paid is the same"],"answer":0,"explanation":"Section 77 of the CGST Act and section 19 of the IGST Act say the taxpayer pays the correct IGST, owes no interest on it, and gets a refund of the CGST and SGST paid by mistake. There is no automatic adjustment between the two levies.","difficulty":"very-hard","source":"Big 4 tax · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-596","question":"Under Schedule III of the CGST Act, which of these is treated as neither a supply of goods nor a supply of services?","options":["Sale of lottery tickets by an authorised distributor","Assignment of a book debt to a factoring company","Entry to a casino on payment of an entry fee","Betting on horse races through a licensed bookmaker"],"answer":1,"explanation":"Actionable claims are outside GST except 'specified actionable claims': betting, casinos, gambling, horse racing, lottery and online money gaming. Assigning an ordinary receivable is therefore not a supply, while the other three are taxable.","difficulty":"hard","source":"Big 4 tax · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-597","question":"A business's year-end figures include: bonus to employees ₹5 lakh, paid after the due date of filing the return; employer's provident fund contribution ₹2 lakh, paid before that due date; bank loan interest ₹3 lakh, which the bank converted into a new loan; and leave encashment ₹1 lakh, paid during the year. Under section 43B, how much is deductible this year?","options":["₹6 lakh","₹8 lakh","₹3 lakh","₹11 lakh"],"answer":2,"explanation":"43B allows these items only on actual payment, by the due date of the return for the year-end dues. PF (₹2 lakh) and leave encashment (₹1 lakh) qualify. Bonus paid after the due date is deductible next year, and interest converted into a loan is not 'actually paid'.","difficulty":"very-hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-598","question":"A company sells one of its undertakings as a going concern for a lump sum of ₹5 crore (assume this equals fair value), without assigning values to individual assets. The undertaking's depreciable assets have a tax written-down value of ₹2 crore (book value ₹2.5 crore), land a book value of ₹1 crore and debtors ₹0.8 crore; its liabilities are ₹0.6 crore. What is the capital gain under the slump-sale rules?","options":["₹1.3 crore","₹1.2 crore","₹2.6 crore","₹1.8 crore"],"answer":3,"explanation":"Net worth = WDV of depreciable assets (₹2 crore, not book value) + other assets at book value (₹1 + ₹0.8 crore) − liabilities (₹0.6 crore) = ₹3.2 crore. Gain = 5 − 3.2 = ₹1.8 crore. Using book value for depreciable assets gives ₹1.3 crore, and ignoring liabilities gives ₹1.2 crore.","difficulty":"very-hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-599","question":"An Indian company earns income in a country with which India has a tax treaty, and also in a country with which it has none. How did the Income-tax Act, 1961 relieve double taxation?","options":["Section 90 applies the treaty or the Act, whichever is more beneficial; section 91 gives unilateral relief","Only the treaty country's income gets relief; none is available for tax paid in the non-treaty country","Treaty provisions always override the Act, even where the Act is more favourable to the taxpayer","Foreign income of a resident company is exempt in India, so no double taxation arises at all"],"answer":0,"explanation":"Under section 90, a treaty applies, but the Act prevails where it is more beneficial to the taxpayer. Section 91 gives unilateral relief, a deduction for tax paid in a non-treaty country, at the lower of the Indian and foreign rate.","difficulty":"hard","source":"Big 4 tax · MBA placement"},
  {"id":"mgmt-tax-law-600","question":"An individual buys a flat for ₹40 lakh. Assume the rule that if the stamp duty value exceeds the consideration by more than the higher of ₹50,000 and 10% of the consideration, the whole difference is taxed as income from other sources. What is taxable if the stamp duty value is (a) ₹46 lakh, and (b) ₹43 lakh?","options":["(a) ₹6 lakh; (b) ₹3 lakh","(a) ₹6 lakh; (b) nil","(a) ₹2 lakh; (b) nil","(a) nil; (b) nil"],"answer":1,"explanation":"The tolerance is the higher of ₹50,000 and 10% of ₹40 lakh = ₹4 lakh. In (a) the gap of ₹6 lakh exceeds it, so the whole ₹6 lakh (not just the excess of ₹2 lakh) is taxed. In (b) the gap of ₹3 lakh is within the tolerance, so nothing is taxed.","difficulty":"very-hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-601","question":"An Indian subsidiary sells 10,000 units to its foreign parent at ₹800 each, ex-works. It sells the same product to an unrelated buyer at ₹950, but that price includes ₹50 of freight that the subsidiary bears. Using the comparable uncontrolled price method, by how much should the subsidiary's income be adjusted?","options":["₹15 lakh","Nil","₹10 lakh","₹5 lakh"],"answer":2,"explanation":"The comparable price is adjusted for differences: ₹950 − ₹50 freight = ₹900 ex-works. Adjustment = (900 − 800) × 10,000 = ₹10 lakh. Leaving out the freight adjustment overstates it at ₹15 lakh.","difficulty":"hard","source":"Big 4 tax · transfer pricing · MBA placement"},
  {"id":"mgmt-tax-law-602","question":"A trader has a loss of ₹2 lakh from intraday (speculative) share trading and a profit of ₹5 lakh from his regular textile business in the same year. Under the set-off rules, what is correct?","options":["The speculative loss is set off against the textile profit, leaving ₹3 lakh taxable","The speculative loss can be set off against salary income but not against business","The speculative loss lapses at once and cannot be carried forward to any year","It is set off only against speculation income, so it is carried forward instead"],"answer":3,"explanation":"Section 73 ring-fences speculation losses: they can be set off only against speculation income, now or in the next four years. The rule is one-way; an ordinary business loss can be set off against speculation profit.","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-603","question":"A company's books show a ₹25 lakh 'loan' from a person whose identity it cannot establish and who has no visible means to lend. What is the tax consequence under section 68 of the Income-tax Act, 1961?","options":["It may be taxed as its income, as the company must prove identity, creditworthiness and genuineness","It is a liability shown in the balance sheet, so it can never be taxed as the income of the company","It is taxed only in the lender's hands, as he is the one whose source of funds is unexplained","It is treated as share capital and is exempt, since a company's capital receipts are not income"],"answer":0,"explanation":"For unexplained cash credits the burden is on the assessee to establish identity, creditworthiness and genuineness. If it cannot, the credit is deemed income (taxed at a special high rate), even though it is recorded as a loan.","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-604","question":"A logistics company pays (i) a ₹2 lakh penalty for overloading trucks in breach of the Motor Vehicles Act and (ii) ₹3 lakh of damages to a customer for late delivery under a contract. Which can it deduct as a business expense?","options":["Both, as each was paid in the course of running the business","Only the damages; spending for an unlawful purpose is barred","Only the penalty, as it is fixed by statute and unavoidable","Neither, since both payments are punitive in nature"],"answer":1,"explanation":"Explanation 1 to section 37(1) disallows expenditure incurred for any purpose that is an offence or prohibited by law, so the penalty is out. Compensation for breach of a business contract is an ordinary trading loss and is deductible.","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-605","question":"A farmer-trader has a loss of ₹1.5 lakh from agriculture and taxable income of ₹6 lakh from his shop. Can he set off the agricultural loss against the shop income?","options":["Yes, under inter-head set-off against the shop income","Yes, but only half of it, under partial integration","No; a loss from an exempt source cannot be set off","No, but he can carry it forward against future shop income"],"answer":2,"explanation":"Set-off rules apply only to losses from taxable sources. Agricultural income is exempt, so its loss cannot reduce taxable income or be carried forward against it (agricultural income matters only in working out the rate under partial integration).","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-606","question":"A company spends ₹50 lakh on its mandatory CSR obligation under the Companies Act, on rural education projects. How is this treated in computing its business income under the Income-tax Act, 1961?","options":["Fully deductible as a business expense, being a statutory obligation","Deductible only if the projects are near its factories or plants","Deductible at 50%, the rest being treated as a charitable donation","Not deductible; an explanation to section 37(1) expressly bars it"],"answer":3,"explanation":"Explanation 2 to section 37(1) states that CSR expenditure under section 135 of the Companies Act is not incurred for business purposes. Some CSR spends may separately qualify for other deductions (such as certain donations), but not under section 37.","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-607","question":"A shareholder holding 1,000 shares receives a 1-for-2 rights offer and, instead of subscribing, sells (renounces) his 500 rights entitlements for ₹30 each. How is this taxed?","options":["Short-term gain of ₹15,000; the entitlement's cost is nil and held briefly","Long-term capital gain, since the original shares were held for many years","Not taxable, since a rights entitlement is not a capital asset at all","A gain of ₹15,000 less a proportionate part of the original shares' cost"],"answer":0,"explanation":"The cost of a renounced rights entitlement is taken as nil, so the whole ₹15,000 is the gain. Its holding period runs from the offer date to renunciation, making it short-term. The cost of the original shares is not split.","difficulty":"very-hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-608","question":"A retiring businessman receives ₹1 crore from a buyer of his products under an agreement not to set up a competing business for five years (not linked to any transfer of a manufacturing right or licence). How is the sum taxed?","options":["As a capital receipt, not taxable, since it compensates for giving up a source","As business income, under the specific provision for non-compete receipts","As income from other sources, taxed at a flat special rate","As a long-term capital gain, with the benefit of indexation"],"answer":1,"explanation":"Section 28(va) taxes sums received for not carrying out any activity in relation to a business or profession as business income. The exception (taxed as capital gain) covers sums received for transferring a right to manufacture or carry on business.","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-609","question":"A company with a large brought-forward loss decides not to claim depreciation on its machinery this year, hoping to save it for later years. What is the tax position?","options":["It can choose not to claim it and defer the depreciation to a later year","It may claim depreciation only in a year in which it actually has profits","Depreciation is deemed allowed even if unclaimed, so WDV falls anyway","It loses that year's depreciation permanently but keeps the original cost"],"answer":2,"explanation":"Explanation 5 to section 32 makes depreciation compulsory: it is allowed whether or not the assessee claims it, and the WDV falls accordingly. Unabsorbed depreciation then carries forward under its own rules.","difficulty":"hard","source":"Big 4 tax · CA Inter · MBA placement"},
  {"id":"mgmt-tax-law-610","question":"A resident individual aged 68 has pension and interest income only, with tax payable of ₹90,000 after TDS. Is she required to pay advance tax?","options":["Yes, in four instalments, like every other taxpayer","Yes, but in a single instalment by 15 March","Only if her net tax payable for the year exceeds ₹1 lakh","No; a resident senior with no business income is exempt"],"answer":3,"explanation":"Section 207(2) exempts resident individuals aged 60 or more who have no income under the head 'profits and gains of business or profession' from advance tax; they pay the balance as self-assessment tax.","difficulty":"moderate","source":"Big 4 tax · MBA placement"},
  {"id":"mgmt-tax-law-611","question":"Consider these statements under the Competition Act, 2002:\nI. A price-fixing agreement between competing cement makers is presumed to have an appreciable adverse effect on competition.\nII. A manufacturer's resale price maintenance agreement with its dealers is judged on whether it actually causes an appreciable adverse effect.\nIII. Every exclusive distribution agreement is void per se.\nWhich are correct?","options":["I and II only","I and III only","II and III only","I, II and III"],"answer":0,"explanation":"Horizontal agreements among competitors (price fixing, output limits, market sharing, bid rigging) carry a presumption of AAEC under section 3(3). Vertical agreements such as RPM and exclusive distribution (section 3(4)) are anti-competitive only if they cause AAEC, judged on the facts.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-612","question":"Four contractors bidding for a state road project agree that each will take turns submitting the lowest bid, while the others quote higher 'cover' prices. Under the Competition Act, this is:","options":["Lawful, since each still bids separately","Bid rigging, a horizontal agreement presumed to harm competition","Abuse of dominance, which needs proof that one bidder is dominant","A combination needing prior approval"],"answer":1,"explanation":"Bid rotation with cover bids is a classic form of collusive bidding, listed under section 3(3)(d) and presumed to have an appreciable adverse effect on competition. Dominance and merger control are irrelevant.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-613","question":"A company holds 70% of the Indian market for a medical device. Which statement is correct under the Competition Act?","options":["A 70% share is illegal in itself, so the company must reduce it","Any price cut by a dominant company is automatically predatory","Dominance is not prohibited; only abuse of the dominant position is","Only government companies can legally hold a dominant position"],"answer":2,"explanation":"Section 4 targets abuse of dominance, not dominance itself, which a firm may earn through superior products. Predatory pricing must be below cost with intent to reduce competition, not just any price cut.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-614","question":"A member of a cartel is the first to come forward to the Competition Commission with full, genuine evidence of the cartel before the Commission has enough evidence of its own, and it cooperates throughout. What can it expect?","options":["Immunity from all civil compensation claims by customers","Automatic dismissal of the case against every cartel member","A doubled penalty, for having taken part in the cartel","Up to 100% reduction in penalty under the leniency rules"],"answer":3,"explanation":"Section 46 and the lesser-penalty regulations reward the first applicant with up to a full reduction in penalty, with smaller reductions for later applicants. The cartel itself is still prosecuted against the others.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-615","question":"Two large firms sign an agreement to merge, and the combination crosses the thresholds requiring notice to the Competition Commission. Before approval, they plan to integrate operations and appoint common management. What is the legal position?","options":["It cannot take effect before approval or the waiting period ends; early integration is a violation","Notice can be filed after closing, so integrating operations first is permitted under the Act","Merger control in India applies only to cross-border transactions","Integration is allowed if the two firms operate in different industries and markets"],"answer":0,"explanation":"India's merger control is suspensory: a notifiable combination must not be consummated (even partly, by 'gun-jumping') before approval or the expiry of the waiting period. Penalties apply for early implementation.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-616","question":"A drug company licenses its patented process to a manufacturer on condition that the licensee keeps the process secret and uses it only for the licensed product. Under the Competition Act, are these restrictions anti-competitive?","options":["Yes, every restriction in a patent licence is anti-competitive","No; reasonable conditions needed to protect IP rights are allowed","Yes, unless the Commission approves the licence in advance","No, because patents are outside the Competition Act entirely, whatever the terms"],"answer":1,"explanation":"Section 3(5) saves reasonable conditions needed to protect IP rights. Unreasonable conditions, such as tie-ins or price-fixing beyond what the IP requires, can still be challenged, and abuse of dominance by an IP holder is not excused.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-617","question":"Under FEMA, which of these transactions by a person resident in India is a capital account transaction?","options":["Paying for imported raw material","Remitting money for a child's tuition abroad","Buying a flat in Dubai","Paying interest on a foreign loan"],"answer":2,"explanation":"A capital account transaction changes a resident's assets or liabilities outside India (or a non-resident's in India), such as buying property abroad. Trade payments, education remittances and interest payments are current account transactions.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-618","question":"How are contraventions of the Foreign Exchange Management Act, 1999 generally treated, compared with its predecessor FERA?","options":["As criminal offences, with arrest permitted on mere suspicion","As cognisable offences tried by judicial magistrates","As tax evasion, prosecuted under the Income-tax Act","As civil contraventions attracting monetary penalties"],"answer":3,"explanation":"FEMA moved from FERA's criminal approach to a civil one: contraventions attract penalties and adjudication, and detention is used only to recover unpaid penalties. Money laundering is handled separately under the PMLA.","difficulty":"moderate","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-619","question":"A supply contract contains an arbitration clause. The buyer argues the whole contract is void because it was procured by misrepresentation, so the arbitration clause falls with it. How does the Arbitration and Conciliation Act treat this?","options":["The clause is separable and the tribunal rules on its own jurisdiction","The clause is void if the contract is void, so only courts can decide","The buyer can go to court at any stage to stop the arbitration proceedings","The seller must first prove the contract valid in a civil suit"],"answer":0,"explanation":"Section 16 embodies separability and kompetenz-kompetenz: the arbitration clause is independent of the main contract, and the tribunal may rule on its own jurisdiction, including objections about the contract's validity.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-620","question":"A company sues a vendor in a civil court despite an arbitration clause in their contract. The vendor files its written statement on the merits and only months later applies to refer the dispute to arbitration. What is the likely outcome?","options":["The court must refer the dispute to arbitration at any stage of the suit","It may refuse, as the request had to come by the first statement on merits","The court must stay the suit and leave the dispute to be decided later on","The arbitration clause became void automatically when the suit was filed"],"answer":1,"explanation":"Section 8 obliges a court to refer parties to arbitration only if a party applies not later than when it submits its first statement on the substance of the dispute. By pleading on the merits first, the vendor is taken to have waived arbitration.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-621","question":"A losing party challenges a domestic arbitral award under section 34, arguing only that the arbitrator weighed the evidence wrongly and should have believed its witnesses. What is the court likely to do?","options":["Re-hear the evidence and substitute its own view of the facts","Send the case back to the same arbitrator for a fresh hearing","Refuse; section 34 does not permit re-appreciating evidence","Set aside the award, since any error of fact is a ground"],"answer":2,"explanation":"After the 2015 amendment, section 34 expressly bars review on the merits and re-appreciation of evidence. Courts intervene only on the listed grounds, keeping arbitration final.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-622","question":"After the 2018 amendment to the Specific Relief Act, how do courts treat a suit for specific performance of a valid contract to sell commercial land?","options":["Specific performance is purely discretionary and is rarely granted","Only damages are available, since land can always be valued","It is available only if damages cannot be measured in money","It is to be enforced as a rule, subject to the Act's exceptions"],"answer":3,"explanation":"The amendment changed section 10 so that specific performance 'shall be enforced', removing the old discretion that made damages the norm. The statutory bars (personal service, continuous supervision, determinable contracts and so on) remain.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-623","question":"A contractor abandons a half-built warehouse. The owner gives the contractor written notice and then hires another builder to finish it, under the substituted-performance provision of the Specific Relief Act. What can the owner do afterwards?","options":["Recover the substitution costs, but not also seek specific performance","Seek specific performance against the original contractor as well","Recover nothing, since he chose to engage another builder himself","Recover the costs only if the second builder was cheaper than the first"],"answer":0,"explanation":"Section 20 lets the affected party get the contract performed by a third party after at least 30 days' written notice and recover the expense from the defaulter, but having done so it cannot also claim specific performance.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-624","question":"A customer accepts an online subscription contract by clicking 'I agree' and later argues it is unenforceable because nothing was signed on paper. Under the Information Technology Act, 2000, what is the position?","options":["It is unenforceable without a wet-ink signature on paper","It is not unenforceable merely because it was made electronically","It is valid only if it is stamped and registered like a deed","Only contracts signed with a digital signature certificate are valid"],"answer":1,"explanation":"Section 10A states that a contract formed by electronic communication of proposal and acceptance shall not be deemed unenforceable solely on that ground. The usual Contract Act requirements (free consent, lawful object and so on) still apply.","difficulty":"moderate","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-625","question":"A company collects employees' personal data and decides why and how it is used; it hires a payroll firm that only processes the data on its instructions. Under the Digital Personal Data Protection Act, 2023, what are the company and the payroll firm?","options":["Both are data fiduciaries","Data principal and data fiduciary respectively","Data fiduciary and data processor respectively","Data processor and data fiduciary respectively"],"answer":2,"explanation":"The data fiduciary determines the purpose and means of processing and carries primary obligations; the data processor processes on its behalf. The employees are the data principals.","difficulty":"moderate","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-626","question":"An agent in Mumbai contracts in his own name to buy machines for a merchant resident in Germany, without any express term about his personal liability. The seller is unpaid. Under the Indian Contract Act, can the seller sue the agent personally?","options":["No; an agent who signs for a known principal is never personally liable","No; the seller must sue the principal in a German court","Only if the agent was paid a commission on the purchase","Yes; personal liability is presumed for a principal resident abroad"],"answer":3,"explanation":"Section 230 normally keeps the agent out of the contract, but presumes personal liability where the agent acts for a merchant resident abroad, does not disclose the principal, or acts for a principal who cannot be sued.","difficulty":"very-hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-627","question":"A is appointed sole agent to sell B's tractors for a fixed term of three years. After one year, without any misconduct by A, B revokes the agency with immediate effect. What is A's remedy?","options":["Compensation for the early revocation and for want of reasonable notice","None, because a principal can always revoke an agency at will","Specific performance of the agency for the remaining two years of the term","Only the commission already earned to date, with nothing more"],"answer":0,"explanation":"Under sections 205 and 206, where an agency is for a fixed period, the principal must compensate the agent for revoking it early without sufficient cause, and reasonable notice must be given. The agency cannot be forced to continue.","difficulty":"hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-628","question":"An agent engaged to sell his principal's land secretly buys it himself through a nominee at the asking price, and resells it a month later at a large profit. What can the principal do?","options":["Nothing, since he received the full asking price for the land","Repudiate the sale or claim the agent's profit from the deal","Only dismiss the agent, as the sale itself cannot be undone","Sue the second buyer to recover the land from him"],"answer":1,"explanation":"Sections 215 and 216 forbid an agent dealing on his own account without the principal's informed consent. The principal may repudiate the transaction, or claim any benefit the agent obtained from it.","difficulty":"hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-629","question":"A contract for 12 monthly deliveries of steel, each paid for separately, receives one defective delivery in month 3. The buyer wants to cancel the whole contract. Under the Sale of Goods Act, what decides whether he can?","options":["He can always cancel the whole contract for any defective instalment","He can never cancel; only damages for that instalment are available","Whether the breach repudiates the whole contract on its terms and facts","The seller decides, by choosing whether to replace the defective instalment"],"answer":2,"explanation":"Section 38(2) leaves it to the contract terms and the circumstances, such as the ratio of the breach to the whole and the chance of it recurring. A single, isolated defect usually gives a right to damages for that instalment only.","difficulty":"hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-630","question":"A partnership deed is silent on expulsion. Three of four partners vote in good faith to expel the fourth for poor performance. Is the expulsion valid under the Indian Partnership Act?","options":["Yes; a majority acting in good faith can expel for any reason","Yes, provided they pay him his capital and share of profits","Yes, provided the firm is registered with the Registrar of Firms","No; expulsion needs a power conferred by the partners' contract"],"answer":3,"explanation":"Section 33 allows expulsion only in good faith, by a majority, and in exercise of a power conferred by the partners' contract. With no such power in the deed, even a good-faith majority cannot expel.","difficulty":"hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-631","question":"C joins an existing firm as a partner on 1 April. A supplier whose bill for goods bought in February is unpaid sues all the current partners, including C. Is C liable?","options":["No; an incoming partner is not liable for the firm's earlier acts","Yes; all current partners are liable for every debt of the firm","Yes, but only up to the amount of his own capital contribution","Only if the debt was already shown in the firm's books when he joined"],"answer":0,"explanation":"Section 31(2) protects an incoming partner from liability for acts done before he joined. He can, however, take on old debts by agreement with the creditor and the firm (novation).","difficulty":"hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-632","question":"A retiring partner, with no agreement restraining him, opens a competing business across the road. Which of these may he lawfully do under the Indian Partnership Act?","options":["Use the old firm's name for the new business","Advertise his new business","Approach the old firm's customers and persuade them to switch","Represent himself as still carrying on the old firm's business"],"answer":1,"explanation":"Section 36 lets an outgoing partner compete and advertise, but forbids using the firm name, representing that he carries on the firm's business, or soliciting the firm's existing customers, unless agreed otherwise.","difficulty":"hard","source":"Business law · CA Foundation · MBA placement"},
  {"id":"mgmt-tax-law-633","question":"Directors who control the majority vote of a company divert a lucrative contract to their own firm and use their majority to ratify it. A minority shareholder sues. Why can he sue despite the rule that the company is the proper plaintiff?","options":["Any shareholder can sue for any wrong done to the company","The majority rule in Foss v Harbottle applies only to private companies","'Fraud on the minority' by those in control is a recognised exception","Directors cannot be sued at all once the majority has ratified the act"],"answer":2,"explanation":"Foss v Harbottle says the company is the proper plaintiff and the majority decides. Exceptions include ultra vires or illegal acts, fraud on the minority by wrongdoers in control, bypassing a special majority, and infringement of personal rights.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-634","question":"In the winding up of a company, it emerges that its managing director kept taking customer advances for orders he knew the company could never fulfil, to keep the business afloat. Under section 339 of the Companies Act, what can the Tribunal do?","options":["Nothing, since the members and officers of a company enjoy limited liability","Only order him to refund the salary he drew while the business was failing","Only impose a fine on the company, as the contracts were made in its name","Make him personally liable without limit for such debts as it directs"],"answer":3,"explanation":"Section 339 lifts the corporate veil for fraudulent conduct of business: persons knowingly party to it can be made personally liable without limit, besides facing criminal liability.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-635","question":"A listed company wants to reward its independent directors. Which of these may it give them under the Companies Act, 2013?","options":["Sitting fees and limited profit-linked commission, but no stock options","Stock options, on the same terms as executive and whole-time directors","A fixed monthly salary, as they are treated as employees of the company","Any remuneration the board approves, without needing the members' consent"],"answer":0,"explanation":"Sections 149(9) and 197(7) bar independent directors from stock options, to protect their independence, but allow sitting fees, reimbursement of expenses and profit-related commission approved by members.","difficulty":"moderate","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-636","question":"A consumer wants a District Consumer Commission to declare a clause in a builder's standard agreement 'unfair' and void. Under the Consumer Protection Act, 2019, what is the position?","options":["Any District Commission can declare such terms void if the value fits","Only the State or National Commission can declare unfair terms void","Only civil courts can rule on whether a contract term is unfair","Only the Central Consumer Protection Authority can strike such terms"],"answer":1,"explanation":"The 2019 Act gives the power to declare unfair contract terms null and void only to the State and National Commissions, depending on value; the District Commission has no such jurisdiction.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-637","question":"A film star endorses a hair oil that claims to 'stop hair fall in 7 days'. The claim is false and the Central Consumer Protection Authority acts. Can the star be penalised?","options":["No; only the manufacturer is liable for an advertisement's claims","Yes, strictly, whatever checks she made before endorsing it","Yes, unless she exercised due diligence to verify the claims","Only if she owns shares in, or is a director of, the company"],"answer":2,"explanation":"Section 21 lets the CCPA impose penalties on endorsers and bar them from endorsing for a period, but an endorser who has exercised due diligence to verify the claims is not liable.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-638","question":"A spice company's blend recipe is unpatented and known only to a few staff, who signed confidentiality agreements. A former employee leaks it to a rival. On what basis can the company act in India?","options":["Under the Patents Act, since the blend is a novel process","Under the Trade Marks Act, as the recipe identifies the brand","Under the Copyright Act, since a recipe is a literary work","Through the confidentiality contract and breach of confidence"],"answer":3,"explanation":"India protects trade secrets through contract and common-law breach of confidence (injunctions and damages). Patents require public disclosure, trademarks protect brand signs, and copyright protects expression, not the recipe itself.","difficulty":"hard","source":"Business law · IPR · MBA placement"},
  {"id":"mgmt-tax-law-639","question":"A furniture maker creates an original chair design that could be registered under the Designs Act but never registers it, relying on copyright. Assume the rule that copyright in such a design ceases once an article bearing it is reproduced more than 50 times by an industrial process. It has now made 5,000 chairs. What protection does it have?","options":["Copyright has ceased, and without registration the shape is unprotected","Full copyright in the design for the author's life plus 60 years","Design protection under the Designs Act arises automatically without registration","Patent protection, since the chair's design is novel and original"],"answer":0,"explanation":"Section 15(2) of the Copyright Act ends copyright in a registrable but unregistered design once it is industrially reproduced more than 50 times. Industrial designs are meant to be protected by registration under the Designs Act.","difficulty":"very-hard","source":"Business law · IPR · MBA placement"},
  {"id":"mgmt-tax-law-640","question":"A CFO mentions an unannounced merger to a friend at dinner. The friend buys the company's shares the next morning, before the announcement. Under SEBI's insider-trading regulations, who has violated them?","options":["Only the CFO, since the friend is not a person connected with the company","Both: the CFO for passing on UPSI, and the friend for trading on it","Only the friend, since the CFO did not himself deal in any shares","Neither, since the merger was certain to be publicly announced soon"],"answer":1,"explanation":"An 'insider' includes anyone in possession of unpublished price-sensitive information, not only connected persons. Communicating UPSI without a legitimate purpose and trading while in possession of it are both prohibited.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-641","question":"A state government announces a three-year sales-tax exemption for new industries. Relying on it, a company sets up a plant; the government then withdraws the exemption early without overriding public interest. On which principle can the company challenge this?","options":["Privity of contract, since the scheme formed a contract with each investor","Frustration, since the withdrawal made the plant's purpose impossible","Promissory estoppel, binding the State where the promisee relied on it","Quantum meruit, entitling it to the value of the investment made"],"answer":2,"explanation":"Indian courts (as in Motilal Padampat Sugar Mills) hold the government to its promises through promissory estoppel where the promisee acted on them, subject to statute and overriding public interest. No formal contract or consideration is needed.","difficulty":"hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-642","question":"A government corporation's standard employment contract lets it dismiss any permanent employee on three months' notice without reason. Employees had no real choice but to sign. How did the Supreme Court treat such a clause?","options":["As valid, because the employees signed it with full knowledge of its terms","As valid, but any dismissal under it attracts damages for lost wages","As a matter for labour courts only, outside the scope of the Contract Act","As unconscionable and void under section 23, being against public policy"],"answer":3,"explanation":"In Central Inland Water Transport v Brojo Nath Ganguly, the Court struck down such a clause as unconscionable, holding that unfair terms imposed by a party with overwhelming bargaining power can be void as opposed to public policy.","difficulty":"very-hard","source":"Business law · MBA placement"},
  {"id":"mgmt-tax-law-643","question":"B offers by post to sell goods to A. A posts his acceptance on 1 May; it reaches B on 3 May. On 2 May A sends a telegram revoking his acceptance, which reaches B on 2 May. Under the Indian Contract Act, what is the position?","options":["Revocation valid: it reached B before the acceptance came to B's knowledge","Revocation fails: the contract was concluded the moment A posted his letter","Revocation fails: a posted acceptance binds both parties from the posting date","Revocation valid only if B expressly consents to A withdrawing his acceptance"],"answer":0,"explanation":"Under Sections 4 and 5, an acceptance can be revoked at any time before its communication is complete as against the acceptor, i.e. before it comes to the proposer's knowledge. The posting binds only the proposer; A's revocation arriving first is effective.","difficulty":"very-hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-644","question":"Which statements about agreements with minors are correct under Indian law? I. A minor who lied about his age to obtain a loan can be made personally liable to repay it. II. A supplier of necessaries suited to a minor's condition in life is reimbursed from the minor's property. III. A minor can be a beneficiary, such as a promisee or payee.","options":["I and II only","I and III only","II and III only","I, II and III"],"answer":2,"explanation":"A minor's agreement is void, and there is no estoppel against a minor even if he misrepresented his age (I is wrong). Section 68 lets a supplier of necessaries recover from the minor's property, not from him personally, and a minor may take benefits under a contract.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-645","question":"A finds B's lost purse and returns it to him. Grateful, B later promises in writing to pay A ₹500 but then refuses. Can A enforce the promise?","options":["No, because A acted voluntarily and B never requested the service beforehand","No, because consideration that is already past is never valid under Indian law","Yes, under Section 25(2), as a promise to compensate a voluntary act","Yes, but only if B's written promise is registered under the Registration Act"],"answer":2,"explanation":"An agreement without consideration is void, but Section 25(2) excepts a promise to compensate, wholly or partly, a person who has voluntarily done something for the promisor. No registration is needed for this exception.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-646","question":"A sells the goodwill of his bakery in Jaipur to B and agrees not to run a bakery within Jaipur city for five years. Is the restraint valid under Section 27?","options":["Void, because Section 27 voids every agreement in restraint of trade without exception","Valid: a seller of goodwill may accept reasonable local limits","Valid only if B pays A a separate and adequate price for the restraint itself","Void, because a restraint of five years is longer than the law ever permits"],"answer":1,"explanation":"Section 27 voids agreements in restraint of trade but excepts the sale of goodwill: the seller may agree not to carry on a similar business within specified local limits while the buyer carries on business there, if the limits are reasonable.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-647","question":"By a bank error, ₹50,000 meant for X is credited to Y's account, and Y spends it. What is Y's legal position?","options":["Y need not repay, since he did not ask for the money","Y must repay it under Section 72, as money paid by mistake","Y must repay only if he acted dishonestly in spending it","Y must repay only half, sharing the loss equally with the bank"],"answer":1,"explanation":"Section 72 (a quasi-contract) requires a person to whom money is paid by mistake or under coercion to repay it. Good faith or having spent it is no defence.","difficulty":"moderate","source":"CA Foundation · bank SO"},
  {"id":"mgmt-tax-law-648","question":"A mill owner sends a broken crankshaft through a carrier to be copied. The carrier is not told that the mill is idle without it, and delays delivery. Can the owner recover the profit lost from the mill standing idle?","options":["Yes, because the idle-mill loss arose directly and naturally from the delay","No, since lost profits can never be claimed for any breach of contract","Yes, but only up to the amount of freight charged by the carrier","No: the special loss was never communicated, so it is too remote"],"answer":3,"explanation":"Under Section 73 (following Hadley v Baxendale), damages cover losses arising naturally from the breach or those both parties knew, when contracting, to be likely. Special loss from circumstances not communicated is too remote.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-649","question":"A contract states that the party in breach will pay ₹5 lakh. B breaches, and A proves an actual loss of ₹2 lakh. Under Section 74 of the Contract Act, what can A recover?","options":["The full ₹5 lakh, because a sum named in the contract is always payable","Nothing, because a clause naming a sum for breach is a void penalty","₹7 lakh: the sum named plus the actual loss proved by A","Reasonable compensation up to ₹5 lakh, here broadly the ₹2 lakh"],"answer":3,"explanation":"Section 74 does not distinguish penalty from liquidated damages: the court awards reasonable compensation up to the stipulated sum. Where actual loss can be proved, compensation is broadly that loss, not the full ₹5 lakh.","difficulty":"very-hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-650","question":"A agrees to sell B a specific car, in a deliverable state, for ₹5 lakh, with payment and delivery next week. Before delivery the car is destroyed in a fire at A's garage without A's fault. Who bears the loss?","options":["B: property passed at the contract and risk follows property","A, because risk stays with the seller until goods are physically delivered","A, because property in goods never passes until the full price is paid","Both equally, because the fire was the fault of neither party to the sale"],"answer":0,"explanation":"Under Section 20 of the Sale of Goods Act, property in specific goods in a deliverable state passes when the contract is made, even if payment and delivery are postponed; under Section 26, risk passes with property, so B bears the loss.","difficulty":"very-hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-651","question":"An owner leaves his car with a mercantile agent for repairs only. The agent, acting in the ordinary course of business as a car dealer, sells it to C, who buys in good faith without notice. Does C get good title?","options":["No, because nobody can pass a better title to goods than he himself has","No, because the owner handed over the car only for repairs and not for sale","Yes: a mercantile agent in possession with consent passes good title","Yes, but only if the owner later ratifies the sale made by the agent"],"answer":2,"explanation":"The proviso to Section 27 is an exception to nemo dat: a mercantile agent in possession of goods with the owner's consent, selling in the ordinary course of business, passes good title to a good-faith buyer without notice of his lack of authority.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-652","question":"A seller ships goods on credit to a buyer by rail. While the goods are in transit, the seller learns the buyer has become insolvent. Which right can the seller now exercise?","options":["Lien, since the goods are still unpaid for and he remains the seller","Stoppage in transit, resuming possession before the buyer gets them","Resale at once, without any notice, since the buyer is insolvent","No right, since delivery to the carrier is delivery to the buyer"],"answer":1,"explanation":"Lien depends on the seller keeping possession and is lost once goods are handed to a carrier for the buyer. But an unpaid seller can stop goods in transit if the buyer becomes insolvent, and then holds them as if in possession.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-653","question":"Goods are sold by sample as well as by description. The bulk matches the sample but not the description. Under the Sale of Goods Act, is the seller in breach?","options":["No: when goods are sold by sample, matching the sample is enough","No, because caveat emptor applies and the buyer should have checked","Yes: the bulk must match both the sample and the description","Yes, but only if the buyer had examined the sample before contracting"],"answer":2,"explanation":"Section 15 provides that where goods are sold by sample as well as by description, it is not enough that the bulk matches the sample; it must also correspond with the description.","difficulty":"moderate","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-654","question":"A bill of exchange dated 30 November 2022 is payable three months after date. Assuming no public holiday intervenes, on what date does it fall due for payment?","options":["2 March 2023","28 February 2023","5 March 2023","3 March 2023"],"answer":3,"explanation":"Three months after 30 November would be 30 February, which does not exist, so the last day of that month (28 February 2023) is taken; adding three days of grace gives 3 March 2023 under Sections 22–23 of the NI Act.","difficulty":"very-hard","source":"CA Foundation · bank SO"},
  {"id":"mgmt-tax-law-655","question":"Without any usage or contract to the contrary, which act falls within the IMPLIED authority of a partner of a trading firm?","options":["Buying, on credit, goods of the kind the firm deals in","Submitting a dispute of the firm to arbitration","Transferring immovable property that belongs to the firm","Opening a bank account for the firm in his own name"],"answer":0,"explanation":"Section 19(2) of the Partnership Act lists acts outside implied authority, including submitting to arbitration, opening an account in his own name and transferring the firm's immovable property. Buying the firm's usual goods on credit is an act done in the usual way of business.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-656","question":"An unregistered partnership firm supplies goods to a customer who refuses to pay. What can the firm do?","options":["It can sue, provided it gets registered at any time before the judgment","It cannot sue to enforce the contract, though the customer can sue it","It can sue, because registration of a firm is optional under the Act","It can sue only through one partner bringing the suit in his own name"],"answer":1,"explanation":"Under Section 69, an unregistered firm cannot sue a third party to enforce a contractual right; registration must exist when the suit is filed, and a partner cannot get around it by suing personally. Third parties can still sue the firm.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-657","question":"A minor is admitted to the benefits of a partnership. On attaining majority he gives no public notice either way for over six months. What is his position under Section 30?","options":["He ceases to have any share in the property or profits of the firm","He stays a beneficiary only, with no personal liability for firm debts","He becomes a partner, personally liable only for acts after majority","He becomes a partner, personally liable for acts since his admission"],"answer":3,"explanation":"If he does not elect within six months of majority (or of learning of his admission), he becomes a partner and is personally liable for all acts of the firm from the date he was first admitted to its benefits.","difficulty":"very-hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-658","question":"Under the Limited Liability Partnership Act, 2008, which requirement regarding designated partners is correct?","options":["At least two, with at least one of them resident in India","At least one, who must be a citizen of India and an individual","At least two, both of whom must be individuals resident in India","At least three, one of whom must be a body corporate registered in India"],"answer":0,"explanation":"Section 7 requires every LLP to have at least two designated partners who are individuals, at least one of whom is resident in India. They are responsible for compliance with the Act.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-659","question":"A company's articles allow the board to borrow with the shareholders' approval by resolution. A lender, acting in good faith, makes a loan without checking whether that resolution was passed. In which case can the company escape liability?","options":["If the resolution was in fact never passed","If the lender did not inspect the minute book","If the documents given to the lender were forgeries","If the loan exceeded the board's general borrowing limit"],"answer":2,"explanation":"Under the doctrine of indoor management, outsiders may assume internal formalities were complied with. The doctrine does not protect a person relying on a forged document, or one who knew or should have suspected the irregularity.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-660","question":"A company makes a contract wholly outside the objects in its memorandum. Afterwards every shareholder votes to ratify it. What is the contract's status?","options":["Valid from the date of ratification","Valid from the beginning, because of unanimous ratification","Voidable at the option of the other party","Void ab initio, and ratification cannot cure it"],"answer":3,"explanation":"An act ultra vires the company's memorandum is void from the start and cannot be ratified even by all the shareholders (Ashbury Railway Carriage v Riche). An act ultra vires only the directors, but within the company's powers, can be ratified.","difficulty":"very-hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-661","question":"Under the Companies Act, 2013, what are the minimum number of members and the maximum limit on members (excluding employee-members) of a private company?","options":["2 and 200","2 and 50","7 and 200","1 and 200"],"answer":0,"explanation":"A private company needs at least 2 members, and its articles must limit members to 200, excluding present and past employees who are members. One member is allowed only for a one person company, and 7 is the minimum for a public company.","difficulty":"moderate","source":"CA Foundation · bank SO"},
  {"id":"mgmt-tax-law-662","question":"A taxable supply of goods is invoiced at ₹1,00,000 (GST rate assumed 18%). The buyer pays three months late and the supplier collects ₹2,000 as interest for the delay. What total GST is payable on the supply, including the interest?","options":["₹18,000","₹360","₹18,360","₹18,720"],"answer":2,"explanation":"Under Section 15(2)(d) of the CGST Act, interest, late fee or penalty for delayed payment of consideration is included in the value of supply. GST = 18% × 1,02,000 = ₹18,360; ₹18,000 leaves the interest out.","difficulty":"hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-663","question":"A registered person's monthly liability is IGST ₹40,000, CGST ₹30,000 and SGST ₹30,000. Available credit: IGST ₹60,000, CGST ₹40,000, SGST ₹5,000. IGST credit must be used first, and its balance may be applied to CGST and SGST in any order. What is the MINIMUM cash payment?","options":["₹25,000","₹5,000","₹0","₹15,000"],"answer":1,"explanation":"IGST credit pays IGST 40,000 and its ₹20,000 balance goes to SGST; SGST credit pays 5,000 more, leaving ₹5,000 in cash. CGST is fully paid from CGST credit, which cannot pay SGST. Using the IGST balance against CGST instead leaves ₹25,000 of SGST to pay in cash.","difficulty":"very-hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-664","question":"A registered company is liable to pay GST under reverse charge on legal services from an advocate. Which statement is correct?","options":["It may set off the tax against its accumulated input tax credit balance","It must pay in cash, then may claim credit if the service is for business","No credit is ever allowed for any tax paid under reverse charge","The advocate must collect the tax from it and deposit it with the government"],"answer":1,"explanation":"Reverse-charge liability is an output liability of the recipient that must be discharged through the electronic cash ledger; once paid, the recipient can take input tax credit if the service is used in the course of business.","difficulty":"hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-665","question":"An Indian citizen stays in India from 1 April to 30 September of a previous year and leaves on 1 October to take up a job abroad for the first time. He did not visit India later that year. What is his residential status for that year (basic conditions only)?","options":["Non-resident, since a citizen leaving for employment is always non-resident that year","Non-resident, because the 60-day condition does not apply to him","Resident, because his stay is 182 days or more","Resident but not ordinarily resident, by default"],"answer":2,"explanation":"For a citizen leaving India for employment, the alternative 60-day test is replaced by 182 days, but the first test (182 days or more in the year) still applies. Stay from 1 April to 30 September is 183 days, so he is resident. Whether ordinarily resident depends on earlier years.","difficulty":"moderate","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-666","question":"In one assessment year an individual has short-term capital gains of ₹50,000, long-term capital gains of ₹80,000, a short-term capital loss of ₹30,000 and a long-term capital loss of ₹1,00,000. Applying the set-off rules optimally, what is carried forward?","options":["Long-term capital loss of ₹20,000","Nothing, as total losses are below total gains","Short-term capital loss of ₹10,000","Long-term capital loss of ₹50,000"],"answer":0,"explanation":"Long-term capital loss can be set off only against long-term gains: 1,00,000 − 80,000 leaves ₹20,000 to carry forward. Short-term loss of 30,000 is set off against short-term gains (20,000 of STCG remains taxable). LTCL cannot reduce STCG.","difficulty":"very-hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-667","question":"A let-out house has a municipal value of ₹3,00,000, fair rent of ₹3,60,000 and standard rent (under rent control law) of ₹3,40,000. Actual rent received for the year is ₹3,20,000 and there is no vacancy. What is its gross annual value?","options":["₹3,60,000","₹3,20,000","₹3,40,000","₹3,00,000"],"answer":2,"explanation":"Expected rent = higher of municipal value and fair rent (₹3,60,000), capped at standard rent: ₹3,40,000. GAV = higher of expected rent and actual rent = ₹3,40,000. Ignoring the standard-rent cap gives ₹3,60,000.","difficulty":"hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-668","question":"For a let-out house, GAV is ₹3,40,000, municipal taxes paid by the owner ₹40,000 and interest on the housing loan ₹1,20,000. Using the 30% standard deduction under Section 24(a), what is income from house property?","options":["₹1,18,000","₹90,000","₹2,10,000","₹78,000"],"answer":1,"explanation":"NAV = 3,40,000 − 40,000 = 3,00,000; standard deduction 30% of NAV = 90,000; less interest 1,20,000 gives ₹90,000. Taking 30% of GAV instead of NAV gives ₹78,000, and forgetting the municipal taxes gives ₹1,18,000.","difficulty":"very-hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-669","question":"A company provides for employee bonus for the year ended 31 March but actually pays it after the due date for filing that year's return. Under Section 43B, when is the bonus deductible?","options":["In the year it was provided for, as the business follows accrual accounting","Never, because it was not paid by the due date of the return","Half in the year provided for and half in the year of payment","In the year in which it is actually paid"],"answer":3,"explanation":"Section 43B allows certain sums, such as bonus, only on actual payment; payment by the return due date secures the deduction in the year of accrual. Paid later, the deduction moves to the year of payment rather than being lost.","difficulty":"hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-670","question":"A firm pays rent of ₹10,00,000 to a resident landlord on which tax was deductible at source, but it deducts no tax. Under Section 40(a)(ia), how much of the rent is disallowed for that year?","options":["₹3,00,000 (30% of the sum)","₹10,00,000 (the whole sum)","₹1,00,000 (10% of the sum)","Nothing, if the landlord pays his own tax"],"answer":0,"explanation":"For payments to residents, Section 40(a)(ia) disallows 30% of the sum on which TDS was not deducted or paid; it is allowed in the year the tax is later deducted and paid. The full disallowance applies to certain payments to non-residents under Section 40(a)(i).","difficulty":"hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-671","question":"A machine costing ₹10,00,000 (depreciation rate 15%, WDV block) is acquired and put to use for only 150 days in the previous year. Ignoring additional depreciation, what depreciation is allowed for that year?","options":["₹1,50,000","₹61,644","₹37,500","₹75,000"],"answer":3,"explanation":"Where an asset is put to use for less than 180 days in the year of acquisition, only half the normal rate is allowed: 10,00,000 × 15% × 50% = ₹75,000. The Act does not pro-rate by days (₹61,644).","difficulty":"very-hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-672","question":"An individual sells a residential house and makes a long-term capital gain of ₹80 lakh. Within the time allowed he buys another residential house in India for ₹60 lakh. How much of the gain is exempt under Section 54?","options":["₹80 lakh, as the gain was reinvested in a house","₹60 lakh, the cost of the new house","₹20 lakh, the gain not reinvested","₹45 lakh, in proportion to the amount reinvested"],"answer":1,"explanation":"Section 54 exempts the lower of the capital gain and the cost of the new residential house: ₹60 lakh is exempt and ₹20 lakh remains taxable. Unlike Section 54F, it is based on the gain, not the net sale consideration.","difficulty":"hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-673","question":"During the year an individual receives cash gifts of ₹30,000 from a friend and ₹25,000 from a colleague, neither a relative, on no special occasion. Under Section 56(2)(x), how much is taxable as income from other sources?","options":["₹5,000, the excess over ₹50,000","Nothing, since each gift is below ₹50,000","₹25,000, the smaller gift","₹55,000, the whole aggregate"],"answer":3,"explanation":"Money received without consideration from non-relatives is taxable in full once the aggregate for the year exceeds ₹50,000; the limit is not a deduction. Here 55,000 > 50,000, so all ₹55,000 is taxed.","difficulty":"hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-674","question":"An individual has salary income of ₹8 lakh, income from house property of ₹1 lakh and a loss from a non-speculative business of ₹3 lakh in the same year. How is the business loss treated under Section 71?","options":["Set off against salary first, leaving nothing to carry forward","Set off ₹1 lakh against house property; ₹2 lakh carried forward","Set off against salary and house property in proportion to income","Carried forward in full, as it cannot be set off this year"],"answer":1,"explanation":"Section 71(2A) bars setting off a business loss against salary income. It can be set off against other heads such as house property (₹1 lakh), and the balance of ₹2 lakh is carried forward against future business income.","difficulty":"very-hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-675","question":"Which of these may be carried forward under the Income-tax Act WITHOUT any limit on the number of years?","options":["Unabsorbed depreciation","Loss under the head house property","Speculation business loss","Non-speculative business loss"],"answer":0,"explanation":"Unabsorbed depreciation can be carried forward indefinitely. House property and normal business losses lapse after 8 assessment years and speculation losses after 4.","difficulty":"moderate","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-676","question":"A shop sells a Diwali hamper of sweets, chocolates, dry fruits and a fruit juice for a single price. Each item can be sold separately and attracts a different GST rate. How is the hamper taxed?","options":["As a composite supply, at the rate of its principal item","Each item at its own rate, by splitting the single price","As a mixed supply, at the highest rate among the items","At the lowest rate among the items, since sweets dominate"],"answer":2,"explanation":"Items that are not naturally bundled but sold together for one price form a mixed supply under Section 8, taxed at the rate of the item with the highest rate. A composite supply needs natural bundling with a principal supply.","difficulty":"hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-677","question":"An architect registered in Mumbai designs a hotel to be built in Goa for a client registered in Delhi. Under the IGST Act, what is the place of supply and which tax applies?","options":["Delhi, the recipient's location; IGST","Goa, the location of the property; IGST","Maharashtra, the supplier's location; CGST + SGST","Goa, the location of the property; CGST + SGST of Goa"],"answer":1,"explanation":"For services directly in relation to immovable property, including architects' services, the place of supply is where the property is located (Goa). The supplier is in Maharashtra, so it is an inter-state supply attracting IGST.","difficulty":"very-hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-678","question":"Which statements about a registered person under the GST composition scheme are correct? I. He cannot collect tax from his customers. II. He cannot claim input tax credit. III. He may make inter-state outward supplies of goods freely.","options":["I and III only","II and III only","I and II only","I, II and III"],"answer":2,"explanation":"A composition taxpayer pays tax on turnover out of his own pocket, may not charge tax on invoices, and gets no input tax credit. He is not eligible to make inter-state outward supplies of goods.","difficulty":"hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-679","question":"A manufacturer buys a machine for ₹10 lakh plus GST of ₹1.8 lakh and capitalises ₹11.8 lakh, claiming income-tax depreciation on the whole amount. Can it also claim input tax credit of ₹1.8 lakh?","options":["Yes, credit and depreciation are governed by different laws","Yes, but only half the credit in the first year","No, because credit on capital goods is never allowed","No, because depreciation was claimed on the tax component"],"answer":3,"explanation":"Section 16(3) of the CGST Act denies input tax credit where depreciation has been claimed on the tax component of the cost of capital goods. The firm must choose: credit, or depreciation on the tax.","difficulty":"very-hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-680","question":"Once a corporate insolvency resolution process is admitted under the IBC, which of these is barred by the moratorium under Section 14?","options":["Filing a new suit against the corporate debtor to recover money","Continuing the supply of essential goods such as electricity","Criminal prosecution of the company's directors for fraud","Paying current salaries to employees out of the company's funds"],"answer":0,"explanation":"The moratorium bars instituting or continuing suits against the corporate debtor, enforcing security and recovering property. Essential supplies continue, and personal criminal proceedings against directors are not covered.","difficulty":"hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-tax-law-681","question":"Under the Insolvency and Bankruptcy Code, what vote of the committee of creditors is needed to approve a resolution plan?","options":["At least 51% of the voting share of financial creditors","At least 66% of the voting share of financial creditors","At least 75% of the voting share of financial creditors","All financial creditors present and voting"],"answer":1,"explanation":"A resolution plan must be approved by at least 66% of the voting share of the committee of creditors, which consists of financial creditors. 51% suffices for routine decisions, and 75% was the earlier threshold before the 2018 amendment.","difficulty":"hard","source":"CA Intermediate · bank SO"},
  {"id":"mgmt-tax-law-682","question":"A contract has a valid arbitration clause. One party sues in court instead. Under Section 8 of the Arbitration and Conciliation Act, when must the court refer the parties to arbitration?","options":["Whenever it thinks arbitration would be faster than a trial","Only if both parties jointly apply after evidence is recorded","If a party applies by the time of its first statement on the substance","Only if the arbitration clause was registered with the court beforehand"],"answer":2,"explanation":"Section 8 obliges the judicial authority to refer the parties to arbitration if a party applies not later than when submitting its first statement on the substance of the dispute, unless it finds prima facie that no valid arbitration agreement exists.","difficulty":"very-hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-tax-law-683","question":"Under the Competition Act, 2002, how are a price-fixing agreement between competing cement makers and an exclusive-supply agreement between a cement maker and its dealer assessed?","options":["Both are void per se as anti-competitive agreements under the Act","Both are judged by the rule of reason, on their actual market effects","The dealer agreement is presumed harmful; the cartel is judged on effects","The cartel is presumed to cause harm; the dealer deal is judged on effects"],"answer":3,"explanation":"Horizontal agreements such as price fixing under Section 3(3) are presumed to cause an appreciable adverse effect on competition. Vertical agreements under Section 3(4), such as exclusive supply, are illegal only if they actually cause such an effect.","difficulty":"very-hard","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-tax-law-684","question":"Match each Indian IPR with its term of protection. (p) Copyright in a published novel; (q) a patent; (r) a registered trade mark.","options":["p: author's life + 60 years; q: 20 years; r: 10 years, renewable","p: author's life + 70 years; q: 20 years; r: 10 years, renewable","p: author's life + 60 years; q: 15 years; r: 20 years, renewable","p: 60 years from publication; q: 20 years; r: 15 years, renewable"],"answer":0,"explanation":"In India, copyright in a literary work lasts for the author's life plus 60 years, a patent 20 years from filing, and a trade mark registration 10 years, renewable indefinitely for 10 years at a time. Life + 70 is the term in the EU and the US.","difficulty":"moderate","source":"CA Intermediate · UGC NET Commerce"},
  {"id":"mgmt-tax-law-685","question":"At a general meeting, a special resolution receives 300 votes in favour, 120 against and 50 abstentions. Is it passed?","options":["Yes, since votes in favour exceed half of all the votes cast","Yes, since 300 is more than two-thirds of all members present","No; votes in favour must be at least three times those against","No, since the 50 abstentions are counted as votes against"],"answer":2,"explanation":"A special resolution needs votes in favour of at least three times the votes against (Section 114). 3 × 120 = 360 > 300, so it fails; abstentions are ignored. A simple majority suffices only for an ordinary resolution.","difficulty":"very-hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-686","question":"A public company has 800 members. Unless its articles require more, what is the quorum for its general meeting under Section 103?","options":["2 members personally present","5 members personally present","15 members personally present","30 members personally present"],"answer":1,"explanation":"For a public company, quorum is 5 members personally present if members are not more than 1,000; 15 if between 1,000 and 5,000; and 30 above 5,000. Two members is the quorum for a private company.","difficulty":"moderate","source":"CA Foundation · bank SO"},
  {"id":"mgmt-tax-law-687","question":"Under Section 173 of the Companies Act, 2013, how often must the board of a public company (other than a small company or OPC) meet?","options":["At least four times a year, with not more than 120 days between meetings","At least four times a year, with not more than 90 days between meetings","At least twice a year, with not more than 180 days between meetings","At least once in each quarter, with not more than 60 days between meetings"],"answer":0,"explanation":"Section 173 requires a minimum of four board meetings every year, with a gap of not more than 120 days between two consecutive meetings. Relaxed rules apply to small companies, OPCs and dormant companies.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-688","question":"A company declares a dividend at its AGM. Which statement about the dividend is correct under the Companies Act, 2013?","options":["It must be paid within 60 days, from a separate account opened within 15 days","It must be paid within 30 days, directly from the company's general current account","It must go to a separate bank account within 5 days and be paid within 30 days","It may be paid at any time before the next AGM, subject to the board's approval"],"answer":2,"explanation":"The dividend amount must be deposited in a scheduled bank in a separate account within 5 days of declaration (Section 123(4)) and paid within 30 days (Section 127). Unpaid amounts go to an unpaid dividend account after that.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-689","question":"A agrees to buy B's horse, both believing it alive; unknown to both it had died the day before. Under Section 20 of the Contract Act, what is the agreement?","options":["Void, as both were mistaken about a fact essential to it","Valid, but B must refund any price that A has already paid","Voidable at A's option, for B's innocent misrepresentation","Voidable at B's option, as he too was under a mistake of fact"],"answer":0,"explanation":"Where both parties are mistaken about a matter of fact essential to the agreement, such as the existence of the subject matter, the agreement is void (Section 20). A unilateral mistake of fact does not make a contract voidable (Section 22).","difficulty":"moderate","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-690","question":"A owes B ₹5 lakh. He authorises B to sell A's land and repay himself from the proceeds. Before the sale, A dies. What is the effect on B's authority?","options":["It ends automatically on A's death, like any other agency","It ends unless A's legal heirs confirm it in writing within a month","It continues only until the end of the period originally agreed","It continues, as an agency coupled with B's own interest"],"answer":3,"explanation":"Where the agent has an interest in the subject matter of the agency, the agency cannot be terminated to the prejudice of that interest, even by the principal's death or insanity (Section 202). Ordinary agencies end on the principal's death.","difficulty":"very-hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-691","question":"A finds a valuable bag on a train. The owner had advertised a reward of ₹5,000 for its return. A traces the owner, who now refuses to pay the reward or A's expenses. What may A do under the Contract Act?","options":["Retain the bag until paid, though he cannot sue for the reward","Sell the bag at once to recover the reward and his expenses","Retain the bag until paid, and also sue for the advertised reward","Neither retain the bag nor claim anything, as a finder acts voluntarily"],"answer":2,"explanation":"Section 168 lets a finder retain the goods until he receives compensation for his trouble and expense, and sue for a specific reward the owner has offered. He may sell only if the goods are perishable or the lawful charges reach two-thirds of their value, under Section 169.","difficulty":"very-hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-692","question":"A manufacturer sells a water purifier to a school for ₹1,00,000. A private charitable foundation pays the manufacturer a further ₹10,000 per unit, directly linked to this sale, so that the school pays less. What is the value of supply under Section 15 of the CGST Act?","options":["₹1,10,000","₹1,00,000","₹90,000","₹1,00,000 plus GST on ₹10,000 as a separate supply"],"answer":0,"explanation":"Subsidies directly linked to the price are included in the value of supply, except those provided by the Central and State Governments. A private foundation's subsidy therefore raises the value to ₹1,10,000.","difficulty":"hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-693","question":"A registered person makes both taxable and exempt supplies. Common input tax credit for the month is ₹1,00,000. Total turnover is ₹10,00,000, of which exempt supplies are ₹2,00,000. Under the proportionate-reversal rule, how much common credit can it keep?","options":["₹1,00,000","₹80,000","₹20,000","₹75,000"],"answer":1,"explanation":"Credit attributable to exempt supplies = common credit × exempt turnover/total turnover = 1,00,000 × 2/10 = ₹20,000, which must be reversed; ₹80,000 remains. ₹20,000 is the reversal, not the eligible credit.","difficulty":"very-hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-694","question":"A trader took input tax credit on goods purchased; some of the goods were later stolen from his godown. What is the GST position on that credit?","options":["The credit stands, as the goods were bought for business","The credit stands if the theft is reported to the police","The credit must be reversed, as credit on stolen goods is blocked","Only half the credit must be reversed, as an insurance-claim offset"],"answer":2,"explanation":"Section 17(5)(h) blocks input tax credit on goods lost, stolen, destroyed, written off or given away as gifts or free samples, so credit already taken on them must be reversed. A police report does not restore it.","difficulty":"hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-695","question":"An exporter of goods wants to avoid blocking funds in tax. Which route does GST law allow for a zero-rated export?","options":["Export under a letter of undertaking without IGST, then claim refund of credit","Export after paying CGST and SGST, then claim a refund of both taxes paid","Export as an exempt supply and reverse all the input tax credit relating to it","Export only on payment of IGST, with no refund of any accumulated input credit"],"answer":0,"explanation":"Exports are zero-rated: the exporter may either export under a bond or letter of undertaking without paying IGST and claim a refund of unutilised ITC, or pay IGST and claim a refund of the tax paid. Unlike exempt supplies, zero-rated supplies keep their credit.","difficulty":"hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-696","question":"For deciding whether a person must register under GST, which of these is EXCLUDED from 'aggregate turnover'?","options":["Exempt supplies of goods and services","Inter-state supplies made to other states","Export of goods and services","Central tax, State tax and IGST charged"],"answer":3,"explanation":"Aggregate turnover covers taxable, exempt, export and inter-state supplies of all persons with the same PAN, but excludes the taxes themselves (CGST, SGST, UTGST, IGST and cess) and inward supplies taxed under reverse charge.","difficulty":"moderate","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-697","question":"Under the old tax regime, an employee in Mumbai has basic salary plus DA (forming part of retirement benefits) of ₹6,00,000 and receives HRA of ₹3,00,000. He pays rent of ₹2,40,000 a year. What part of the HRA is taxable?","options":["₹60,000","₹1,20,000","₹1,80,000","Nil"],"answer":1,"explanation":"Exemption is the least of actual HRA (3,00,000), rent minus 10% of salary (2,40,000 − 60,000 = 1,80,000) and 50% of salary for a metro (3,00,000): ₹1,80,000. Taxable HRA = 3,00,000 − 1,80,000 = ₹1,20,000.","difficulty":"very-hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-698","question":"Which of these is agricultural income exempt under Section 10(1)?","options":["Dividend from a company engaged in growing and processing tea","Interest on a loan given to a farmer for buying seeds","Rent received from agricultural land situated in India","Income from a poultry farm run on agricultural land"],"answer":2,"explanation":"Rent or revenue from land in India used for agricultural purposes is agricultural income. Dividends from an agricultural company, interest received from farmers and poultry income (no basic cultivation of land) are not.","difficulty":"hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-699","question":"A new business is set up on 1 October 2024. What is its first previous year for income tax?","options":["1 April 2024 to 31 March 2025","1 October 2024 to 30 September 2025","1 October 2024 to 31 March 2026","1 October 2024 to 31 March 2025"],"answer":3,"explanation":"For a newly set-up business, the first previous year starts on the date of setting up and ends on the following 31 March, so it may be shorter than 12 months; thereafter it is the financial year.","difficulty":"moderate","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-700","question":"An eligible resident trader opts for presumptive taxation under Section 44AD. Turnover is ₹1 crore, of which ₹60 lakh was received through banking or digital channels by the due date and the rest in cash. What is the minimum deemed business income?","options":["₹8.0 lakh","₹6.0 lakh","₹7.2 lakh","₹6.8 lakh"],"answer":3,"explanation":"Deemed income is 6% of turnover received through prescribed digital or banking modes and 8% of the rest: 6% × 60 + 8% × 40 = 3.6 + 3.2 = ₹6.8 lakh. Swapping the two rates gives ₹7.2 lakh.","difficulty":"very-hard","source":"Big 4 tax · CA Intermediate"},
  {"id":"mgmt-tax-law-701","question":"A owes ₹1 lakh to B. A, B and C agree that C will owe the debt to B and A is released. What has happened?","options":["Novation: a new contract replaces the old one","Assignment: B transfers his right without A's consent","Rescission: the debt is cancelled without substitution","Alteration: a term of the original contract is changed"],"answer":0,"explanation":"Under Section 62, when the parties agree to substitute a new contract, here with a new debtor accepted by the creditor, the original contract need not be performed. That is novation, which needs the consent of all three.","difficulty":"moderate","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-702","question":"A spiritual guru persuades a devotee to gift him the devotee's entire property. The devotee later challenges the gift. What is the legal position?","options":["The gift is void, since a gift of property needs no consideration at all","The gift is valid unless the devotee proves that coercion was actually used","Voidable: the guru must prove he did not use undue influence","The gift is valid, since the devotee was of full age and of sound mind"],"answer":2,"explanation":"A spiritual adviser is presumed to be in a position to dominate the will of a disciple; when such a person gets an unconscionable benefit, Section 16(3) shifts the burden to him to prove he did not use undue influence. Otherwise the transaction is voidable.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-703","question":"A promises to indemnify B against consequences of a dispatch. B is sued, and on a prudent lawyer's advice settles for ₹80,000 and pays ₹20,000 as legal costs. What can B recover from A under Section 125?","options":["₹80,000 only, as costs are never recoverable","₹1,00,000, the settlement plus the legal costs","₹20,000 only, since he chose to settle","Nothing until a court decree is passed against him"],"answer":1,"explanation":"An indemnity-holder can recover damages he is compelled to pay, costs of a suit he was compelled to defend, and sums paid under a prudent compromise not contrary to the indemnifier's orders. Both items qualify, so ₹1,00,000 is recoverable.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-704","question":"S gives a bank a continuing guarantee for loans the bank may make to D. S dies; unaware of this, the bank continues to lend to D. Is S's estate liable for loans made after his death?","options":["Yes, as the guarantee binds his estate until it is expressly revoked","Yes, but only for loans made within one month after his death","No, unless the bank had received formal written notice of his death","No: death revokes it for future loans unless agreed otherwise"],"answer":3,"explanation":"Under Section 131, the death of a surety operates, in the absence of a contract to the contrary, as a revocation of a continuing guarantee as to future transactions. The estate remains liable for advances made before death.","difficulty":"very-hard","source":"CA Foundation · bank SO"},
  {"id":"mgmt-tax-law-705","question":"A creditor holds a guarantee from three co-sureties, X, Y and Z. He releases X from liability. What is the effect on Y and Z?","options":["They are discharged, since releasing one co-surety releases all","They remain liable, and X is still liable to contribute to them","They are discharged only to the extent of X's share of the debt","They remain liable, and X ceases to owe them any contribution"],"answer":1,"explanation":"Under Section 138, release by the creditor of one co-surety does not discharge the others, nor does it free the released surety from his responsibility to the other sureties for contribution.","difficulty":"very-hard","source":"CA Foundation · bank SO"},
  {"id":"mgmt-tax-law-706","question":"X buys a gold chain from Y by fraud; Y has not yet rescinded the contract. X pledges the chain with a pawnbroker who acts in good faith without notice of the fraud. Is the pledge valid?","options":["Valid, since X held it under a contract not yet rescinded","Void, since X obtained the chain by fraud and has no title","Valid only if Y consents to the pledge after learning of it","Void, since only the true owner of goods can make a pledge"],"answer":0,"explanation":"Section 178A: a pledge by a person in possession under a voidable contract that has not been rescinded at the time of the pledge gives the pledgee a good title if he acts in good faith without notice of the defect.","difficulty":"hard","source":"CA Foundation · bank SO"},
  {"id":"mgmt-tax-law-707","question":"At an auction, the seller secretly employs a person to bid up the price, without having notified any right to bid. B buys the lot. What is B's remedy under the Sale of Goods Act?","options":["None, because bids at an auction are only an invitation to offer","He can recover only the excess price paid, as damages from the seller","He may treat the sale as fraudulent and avoid it","He can insist that the whole auction be re-held at once"],"answer":2,"explanation":"Under Section 64(4), if the seller employs a person to bid without notifying a right to bid, the sale may be treated as fraudulent by the buyer, so it is voidable at the buyer's option.","difficulty":"very-hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-708","question":"Which feature belongs to an AGREEMENT TO SELL but not to a sale?","options":["Property in the goods passes to the buyer immediately on contract","On the seller's breach, the buyer generally has only a damages claim","The goods are at the buyer's risk from the moment the contract is made","The seller can sue for the price even before the goods are delivered"],"answer":1,"explanation":"In an agreement to sell, property passes later, so risk generally stays with the seller and the buyer's remedy for breach is damages; the seller can usually sue only for damages, not the price. In a sale, property passes at once.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-709","question":"Which statement about cheques under the Negotiable Instruments Act is FALSE?","options":["A cheque is always drawn on a specified banker","A cheque is always payable on demand","A cheque is entitled to three days of grace","A cheque is a species of bill of exchange"],"answer":2,"explanation":"Days of grace apply only to instruments payable otherwise than on demand, such as time bills and notes. A cheque is a bill of exchange drawn on a specified banker and payable on demand, so it gets no grace.","difficulty":"moderate","source":"Bank SO · CA Foundation"},
  {"id":"mgmt-tax-law-710","question":"The drawer of a cheque instructs his bank to stop payment, and the cheque is dishonoured. Must the holder send the drawer a notice of dishonour under the NI Act to charge him?","options":["Yes, notice of dishonour is needed in every case without exception","Yes, unless the amount of the cheque was below ₹10,000","No: the drawer countermanded payment, so no notice is needed","No, notice of dishonour is never required for any cheque"],"answer":2,"explanation":"Section 98 dispenses with notice of dishonour to charge the drawer when he has countermanded payment, since he knows it will be dishonoured. (A separate demand notice is still needed before a Section 138 prosecution.)","difficulty":"very-hard","source":"Bank SO · CA Foundation"},
  {"id":"mgmt-tax-law-711","question":"X is a director of a company that has not filed its financial statements or annual returns for three continuous financial years. What follows under Section 164(2) of the Companies Act?","options":["Barred from reappointment there and appointment elsewhere for five years","Disqualified from the board of the defaulting company only, indefinitely","Fined, but free to continue as a director on every board he sits on","Disqualified for three years, but only from boards of other companies"],"answer":0,"explanation":"Section 164(2) disqualifies every director of such a company from being reappointed in that company or appointed in any other company for five years from the date of default.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-712","question":"Under Section 149(4) of the Companies Act, 2013, what minimum proportion of the board of a listed public company must be independent directors?","options":["One-half of the total directors","One-third of the total directors","At least two directors in all","One-fourth of the total directors"],"answer":1,"explanation":"Every listed public company must have at least one-third of its total directors as independent directors, with any fraction rounded off as one. SEBI's listing rules may require more in some cases.","difficulty":"hard","source":"CA Foundation · bank SO"},
  {"id":"mgmt-tax-law-713","question":"A lender deals with a company whose articles (filed with the Registrar) limit the directors' borrowing power. The lender never read them and lends beyond the limit. Which doctrine defeats the lender's claim that he did not know of the limit?","options":["Doctrine of constructive notice","Doctrine of indoor management","Doctrine of ultra vires","Doctrine of holding out"],"answer":0,"explanation":"Under constructive notice, outsiders are deemed to know the contents of the memorandum and articles, which are public documents. Indoor management protects outsiders only regarding internal procedures, not limits stated in the articles themselves.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-714","question":"Under the Consumer Protection Act, 2019, a consumer living in Pune buys a defective appliance online from a seller based in Kolkata. Where may she file her complaint before the District Commission?","options":["Only where the seller resides or carries on business","Only where the contract of sale was concluded online","Only in Delhi, before the National Commission","Where she resides or personally works for gain"],"answer":3,"explanation":"The 2019 Act allows a complaint to be filed where the complainant resides or personally works for gain, as well as where the opposite party resides or carries on business or where the cause of action arose.","difficulty":"hard","source":"CA Foundation · UGC NET Commerce"},
  {"id":"mgmt-tax-law-715","question":"Mr K gifts ₹10 lakh to his son's wife, who puts it in a fixed deposit earning ₹70,000 interest. In whose income is the interest taxed?","options":["The daughter-in-law's, as she owns the deposit","Mr K's, under the clubbing provisions","The son's, as the gift was made because of him","Shared equally between Mr K and the daughter-in-law"],"answer":1,"explanation":"Section 64(1)(vi) clubs income from assets transferred, without adequate consideration, to a son's wife with the income of the transferor. The interest is therefore taxed in Mr K's hands.","difficulty":"very-hard","source":"Big 4 tax · CA Intermediate"},
];

export default questions;
